/**
 * Load key=value pairs from a local .env file (no npm package).
 * Needed when starting with plain `node server.js` (systemd Environment= is not used).
 * Does not override vars already set in the shell.
 */
function loadDotEnv(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      return { ok: false, count: 0, path: filePath };
    }
    const text = fs.readFileSync(filePath, "utf8");
    let count = 0;
    text.split(/\n/).forEach((line) => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) {
        return;
      }
      const eq = trimmed.indexOf("=");
      if (eq <= 0) {
        return;
      }
      const key = trimmed.slice(0, eq).trim();
      let val = trimmed.slice(eq + 1).trim();
      if (
        (val.startsWith('"') && val.endsWith('"')) ||
        (val.startsWith("'") && val.endsWith("'"))
      ) {
        val = val.slice(1, -1);
      }
      if (process.env[key] === undefined) {
        process.env[key] = val;
        count += 1;
      }
    });
    console.log(`[env] Loaded ${count} vars from ${filePath}`);
    return { ok: true, count, path: filePath };
  } catch (error) {
    console.warn(`[env] Could not read ${filePath}:`, error.message);
    return { ok: false, count: 0, path: filePath, error: error.message };
  }
}

// Prefer .env next to server.js, then cwd (when you run from ~/Cave)
const envCandidates = [
  path.join(__dirname, ".env"),
  path.join(process.cwd(), ".env")
];
let envLoaded = false;
for (const candidate of envCandidates) {
  const result = loadDotEnv(candidate);
  if (result.ok) {
    envLoaded = true;
    break;
  }
}
if (!envLoaded) {
  console.warn(`[env] No .env found. Tried:\n  - ${envCandidates.join("\n  - ")}`);
  console.warn("[env] Create one:  cp .env.example .env   then edit CLIENT_ID / CLIENT_SECRET");
}

