function nativeSecretHash(value) {
  return crypto.createHash("sha256").update(String(value || ""), "utf8").digest("hex");
}

function loadNativeWorkstations() {
  try {
    const parsed = JSON.parse(fs.readFileSync(nativeWorkstationsFile, "utf8"));
    return {
      version: 1,
      updatedAt: parsed.updatedAt || null,
      pending: Array.isArray(parsed.pending) ? parsed.pending : [],
      devices: Array.isArray(parsed.devices) ? parsed.devices : []
    };
  } catch {
    return { version: 1, updatedAt: null, pending: [], devices: [] };
  }
}

function saveNativeWorkstations(store) {
  fs.mkdirSync(path.dirname(nativeWorkstationsFile), { recursive: true });
  const saved = { ...store, version: 1, updatedAt: new Date().toISOString() };
  const temporary = `${nativeWorkstationsFile}.tmp`;
  fs.writeFileSync(temporary, JSON.stringify(saved, null, 2), { encoding: "utf8", mode: 0o600 });
  fs.renameSync(temporary, nativeWorkstationsFile);
  fs.chmodSync(nativeWorkstationsFile, 0o600);
  return saved;
}

function nativeWorkstationById(id) {
  const wanted = String(id || "");
  if (!wanted) return null;
  return loadNativeWorkstations().devices.find((device) => device?.id === wanted && !device.revokedAt && device.enabled !== false) || null;
}

function nativeWorkstationFromToken(token) {
  const match = String(token || "").match(/^hive_native_[A-Za-z0-9_-]{32,}$/i);
  if (!match) return null;
  const presented = Buffer.from(nativeSecretHash(match[0]), "hex");
  const store = loadNativeWorkstations();
  const device = store.devices.find((entry) => {
    if (entry.revokedAt || entry.enabled === false || typeof entry.tokenHash !== "string" || entry.tokenHash.length !== 64) return false;
    const expected = Buffer.from(entry.tokenHash, "hex");
    return expected.length === presented.length && crypto.timingSafeEqual(expected, presented);
  });
  if (!device) return null;
  if (!device.lastSeenAt || Date.now() - Date.parse(device.lastSeenAt) > 5 * 60_000) {
    device.lastSeenAt = new Date().toISOString();
    try { saveNativeWorkstations(store); } catch { /* authentication remains valid */ }
  }
  const wfos = Array.isArray(device.wfos) ? device.wfos.map((value) => String(value).toUpperCase()).filter(Boolean) : device.wfo ? [String(device.wfo).toUpperCase()] : [];
  return {
    workstationId: device.id,
    workstationName: device.name || "Hive Native Workstation",
    workstationWfo: wfos[0] || "",
    wfos,
    username: `workstation:${device.id}`,
    displayName: device.name || "Hive Native Workstation",
    email: "",
    uid: device.id,
    groups: ["hive-native-workstation", ...wfos.map((wfo) => `wfo:${wfo}`)],
    idToken: "",
    via: "native-device",
    enabled: device.enabled !== false
  };
}

function nativeWorkstationSession(request) {
  const authorization = String(getHeader(request, "authorization") || "");
  const match = authorization.match(/^Bearer\s+(hive_native_[A-Za-z0-9_-]{32,})$/i);
  return match ? nativeWorkstationFromToken(match[1]) : null;
}
