function warningLifecycleSignature(warning) {
  return [warning?.action, warning?.status, warning?.updatedAt, warning?.expiresAt, warning?.text].map((value) => String(value || "")).join("|");
}

function warningIsFreshForNotification(warning, now = Date.now()) {
  const action = String(warning?.action || "NEW").toUpperCase();
  const eventTime = action === "NEW" ? warning?.issuedAt : warning?.updatedAt;
  const timestamp = new Date(eventTime || 0).getTime();
  const age = now - timestamp;
  return Number.isFinite(timestamp) && timestamp > 0 && age >= -60_000 && age <= 5 * 60_000;
}

function mattermostLocalTime(value, wfo) {
  const timeZone = process.env.MATTERMOST_TIME_ZONE || WFO_TIME_ZONES[String(wfo || "").toUpperCase()] || "UTC";
  const date = new Date(value || Date.now());
  if (!Number.isFinite(date.getTime())) return "Unknown";
  return new Intl.DateTimeFormat("en-US", { timeZone, month: "short", day: "numeric", hour: "numeric", minute: "2-digit", timeZoneName: "short" }).format(date);
}

function officeAlertTime(value,wfo){const date=new Date(value),timeZone=WFO_TIME_ZONES[String(wfo||"").toUpperCase()]||"UTC";if(!Number.isFinite(date.getTime()))return "Unknown time";return new Intl.DateTimeFormat("en-US",{timeZone,weekday:"long",month:"short",day:"numeric",hour:"numeric",minute:"2-digit",timeZoneName:"short"}).format(date);}

function mapSnapshotFileId(id) {
  return String(id || "")
    .replace(/[^A-Za-z0-9._-]/g, "_")
    .replace(/_+/g, "_")
    .slice(0, 120);
}

function mapSnapshotPathForId(id) {
  const safe = mapSnapshotFileId(id);
  if (!safe) return null;
  return path.join(mapSnapshotsDir, `${safe}.png`);
}

function mapSnapshotPublicUrl(id, bust = Date.now()) {
  const safe = mapSnapshotFileId(id);
  if (!safe) return "";
  const base = (publicBaseUrl || "").replace(/\/$/, "") || `http://localhost:${port}`;
  return `${base}/api/public/snapshots/${encodeURIComponent(safe)}.png?t=${bust}`;
}

function hasMapSnapshot(id) {
  const filePath = mapSnapshotPathForId(id);
  try {
    // Blank WebGL captures were ~15–30KB transparent PNGs — require a real frame.
    return Boolean(filePath && fs.existsSync(filePath) && fs.statSync(filePath).size > 12000);
  } catch {
    return false;
  }
}

/** Reject fully transparent / empty WebGL captures (they show as grey in Mattermost). */
function pngLooksBlank(pngBuffer) {
  if (!Buffer.isBuffer(pngBuffer) || pngBuffer.length < 200) return true;
  // Heuristic: earlier blank MapLibre captures were ~15–30KB full-frame fully transparent.
  // Real map frames with basemap/radar are typically well over 80KB.
  if (pngBuffer.length < 12000) return true;
  // PNG signature
  if (pngBuffer[0] !== 0x89 || pngBuffer[1] !== 0x50) return true;
  return false;
}

function saveMapSnapshotPng(id, pngBuffer) {
  const filePath = mapSnapshotPathForId(id);
  if (!filePath || !Buffer.isBuffer(pngBuffer) || pngBuffer.length < 100) {
    throw new Error("Invalid map snapshot payload");
  }
  // Cap ~8MB raw PNG
  if (pngBuffer.length > 8 * 1024 * 1024) {
    throw new Error("Map snapshot too large (max 8MB)");
  }
  if (pngLooksBlank(pngBuffer)) {
    throw new Error("Map snapshot appears blank (transparent WebGL buffer) — retry capture");
  }
  fs.mkdirSync(mapSnapshotsDir, { recursive: true });
  fs.writeFileSync(filePath, pngBuffer);
  // Prune old snapshots (keep newest 80)
  try {
    const files = fs
      .readdirSync(mapSnapshotsDir)
      .filter((name) => name.endsWith(".png"))
      .map((name) => {
        const full = path.join(mapSnapshotsDir, name);
        let mtime = 0;
        try {
          mtime = fs.statSync(full).mtimeMs;
        } catch {
          mtime = 0;
        }
        return { name, full, mtime };
      })
      .sort((a, b) => b.mtime - a.mtime);
    files.slice(80).forEach((item) => {
      try {
        fs.unlinkSync(item.full);
      } catch {
        /* ignore */
      }
    });
  } catch {
    /* ignore prune errors */
  }
  return { id: mapSnapshotFileId(id), path: filePath, bytes: pngBuffer.length, url: mapSnapshotPublicUrl(id) };
}

function mattermostThreatParts(warning) {
  const product = String(warning?.product || "").toUpperCase();
  const bulletinText = String(warning?.text || "");
  const threatParts = [];
  const hailSizes = {
    pea: '0.25"', half: '0.50"', penny: '0.75"', nickel: '0.88"', quarter: '1.00"',
    halfdollar: '1.25"', pingpong: '1.50"', golfball: '1.75"', twoinch: '2.00"',
    tennis: '2.50"', baseball: '2.75"', threeinch: '3.00"', softball: '4.00"', grapefruit: '4.50"', dvd: '5.00"'
  };
  const addLandWindHail = (windId, hailId) => {
    const wind = String(windId || "none").match(/\d+/)?.[0];
    if (wind) threatParts.push(`${wind} mph wind`);
    if (hailId && hailId !== "none") {
      const numeric = Number.parseFloat(hailId);
      const hail = hailSizes[hailId] || (Number.isFinite(numeric) ? `${numeric.toFixed(2)}"` : "");
      if (hail) threatParts.push(`${hail} hail`);
    }
  };

  if (product === "TOR") {
    const tornadoTag = bulletinText.match(/<L>TORNADO\.\.\.(OBSERVED|RADAR INDICATED)<\/L>/i)?.[1];
    const observedSources = new Set(["confirmedDoppler", "confirmedLarge", "spotter", "lawEnforcement", "emergencyManagement", "broadcastMedia", "public", "waterspout"]);
    const tornadoStatus = tornadoTag || (observedSources.has(String(warning.tor?.source || "")) ? "OBSERVED" : "RADAR INDICATED");
    threatParts.push(warning.tor?.emergency ? "Tornado Emergency" : `Tornado — ${tornadoStatus.toLowerCase()}`);
    addLandWindHail(warning.tor?.windId, warning.tor?.hailId);
  } else if (product === "SVR") {
    if (/TORNADO\.\.\.POSSIBLE/i.test(bulletinText) || Boolean(warning.ctas?.tornadoPossible)) threatParts.push("Tornado possible");
    addLandWindHail(warning.windId, warning.hailId);
  } else if (product === "SPS") {
    const textWind = bulletinText.match(/(?:winds? in excess of|wind gusts? (?:up to|of))\s*(\d+)/i)?.[1];
    const textHail = bulletinText.match(/\b(pea|half inch|penny|nickel)(?: size)? hail\b/i)?.[1]?.toLowerCase();
    const windId = warning.sps?.windId || (textWind ? `wind${textWind}` : "none");
    const hailId = warning.sps?.hailId || ({ "half inch": "half" }[textHail] || textHail) || "none";
    addLandWindHail(windId, hailId);
  } else if (product === "SMW") {
    const smw = warning.smw || {};
    const marineWind = { kt34: "34+ kt wind", kt40: "40 kt wind", kt40plus: "Nearly 50 kt wind", kt50: "50+ kt wind", kt65: "65+ kt wind" };
    const marineHail = { small: "Small hail", large: "Large hail", destructive: "Large destructive hail" };
    if (smw.spout === "sighted") threatParts.push("Waterspout sighted");
    else if (smw.spout === "possible") threatParts.push("Waterspouts possible");
    if (marineWind[smw.windId]) threatParts.push(marineWind[smw.windId]);
    if (marineHail[smw.hailId]) threatParts.push(marineHail[smw.hailId]);
    if (smw.ashfall) threatParts.push("Ashfall");
    if (smw.debrisFlow) threatParts.push("Debris flow");
  } else if (product === "TOA" || product === "SVA") {
    if (product === "TOA" || warning.tornadoes) threatParts.push("Tornadoes possible");
    if (warning.pds) threatParts.push("Particularly Dangerous Situation");
    addLandWindHail(warning.windId, warning.hailId);
  } else if (product === "FFW") {
    const damageThreat = String(warning.ffw?.damageThreat || warning.ffw?.dam?.damageThreat || "").toLowerCase();
    if (warning.ffw?.emergency || damageThreat === "catastrophic") threatParts.push("Flash Flood Emergency");
    else if (damageThreat === "considerable") threatParts.push("Considerable flash-flood damage threat");
  } else if (product === "FRW" && warning.frw?.fireEmergency) {
    threatParts.push("Fire Emergency");
  }
  return threatParts;
}

async function postWarningToMattermost(warning) {
  if (!mattermostNotificationsEnabled || !warning || warning.practice) return;
  const productId = warning.productId || `${warning.wfo || "ZWS"}${warning.product || ""}${warning.etn ? String(warning.etn).padStart(4, "0") : ""}`;
  const action = warning.action || (warning.status === "cancelled" ? "CAN" : "NEW");
  const areas = (warning.counties || warning.zones || []).slice(0, 8).map((area) => area.areaPhrase || area.name).filter(Boolean);
  const threatParts = mattermostThreatParts(warning);
  const detailsUrl = `${publicBaseUrl}/api/public/alerts/${encodeURIComponent(warning.id)}.txt`;
  const snapshotUrl = hasMapSnapshot(warning.id) ? mapSnapshotPublicUrl(warning.id) : "";
  const lines = [
    `### ${productId} — ${action}`,
    `**Issued by WFO ${warning.wfo || "Unknown"}**`,
    `**Status:** ${warning.status || action}  |  **Issued:** ${mattermostLocalTime(warning.updatedAt || warning.issuedAt, warning.wfo)}${warning.expiresAt ? `  |  **Expires:** ${mattermostLocalTime(warning.expiresAt, warning.wfo)}` : ""}`,
    threatParts.length ? `**Threats:** ${threatParts.join(" · ")}` : "",
    areas.length ? `**Areas:** ${areas.join(", ")}` : "",
    warning.locationOverride || warning.locationPhrase ? `**Location:** ${warning.locationOverride || warning.locationPhrase}` : "",
    `[Open warning text (.txt)](${detailsUrl})`,
    snapshotUrl ? `**Map snapshot** (SPC-style basemap · radar · cities · product):` : "",
    warning.text ? `\n\`\`\`text\n${String(warning.text).slice(0, 3500)}\n\`\`\`` : ""
  ].filter(Boolean);
  const payload = {
    username: mattermostUsername,
    icon_emoji: ":warning:",
    text: lines.join("\n")
  };
  // Incoming webhook image attachment — Mattermost fetches image_url server-side.
  if (snapshotUrl) {
    payload.attachments = [
      {
        fallback: `${productId} map snapshot`,
        color: String(warning.color || "#d27575"),
        title: `${productId} · map`,
        title_link: detailsUrl,
        image_url: snapshotUrl,
        text: "SPC-style map with radar, cities, and product area"
      }
    ];
  }
  const response = await fetch(mattermostWebhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  if (!response.ok) throw new Error(`Mattermost HTTP ${response.status}`);
  return { withMapSnapshot: Boolean(snapshotUrl) };
}

