function isPublicRuntimeRequest(request, pathname) {
  const method = String(request.method || "GET").toUpperCase();
  if (method === "OPTIONS" && pathname.startsWith("/api/public/")) return true;
  if (!["GET", "HEAD"].includes(method)) {
    return false;
  }
  if (isPublicUnauthenticatedPath(pathname, request)) return true;
  return (
    pathname.startsWith("/api/spc/outlook/") ||
    pathname === "/api/spc/fire-outlook" ||
    pathname.startsWith("/api/discussions/") ||
    pathname.startsWith("/api/observations/") ||
    pathname.startsWith("/api/weather/") ||
    pathname.startsWith("/api/satellite/") ||
    pathname.startsWith("/api/forecast/") ||
    pathname.startsWith("/api/lightning/") ||
    pathname.startsWith("/api/radar/") ||
    pathname.startsWith("/api/hydro/") ||
    pathname.startsWith("/api/nhc/") ||
    pathname === "/api/features"
  );
}

function sendJson(response, statusCode, payload) {
  response.writeHead(statusCode, {
    "Content-Type": "application/json; charset=utf-8"
  });
  response.end(JSON.stringify(payload));
}

