  const times=[...temperatures.keys()].sort((a,b)=>a-b),guidance=times.map(time=>{const temperature=temperatures.get(time),windMph=winds.get(time),apparentTemperature=Number.isFinite(windMph)?forecastApparentTemperatureF(temperature,50,windMph):temperature,coldest=Math.min(temperature,Number.isFinite(apparentTemperature)?apparentTemperature:temperature);return{startTime:new Date(time).toISOString(),temperature,apparentTemperature,coldest};});
