function automatedZoneFeature(draft){const type=draft.zoneType==="fire"?"fire":draft.zoneType==="marine"?"marine":draft.zoneType==="county"?"county":"public",fileKey=type==="fire"?"fire-zones":type==="marine"?"marine-zones":type==="county"?"counties":"public-zones";return wfoZoneCaches.get(fileKey)?.find((feature)=>String(feature.properties?.CWA||feature.properties?.WFO||"").toUpperCase()===draft.wfo&&zoneFeatureCode(feature,type)===draft.zoneCode)||(()=>{zonesForWfo(draft.wfo,type);return wfoZoneCaches.get(fileKey)?.find((feature)=>String(feature.properties?.CWA||feature.properties?.WFO||"").toUpperCase()===draft.wfo&&zoneFeatureCode(feature,type)===draft.zoneCode)})();}
