async function activeNwsAlertsByZone(zones) {
  const states = [...new Set(zones.map((zone) => String(zone.state || zone.code.slice(0, 2)).toUpperCase()).filter((state)=>/^[A-Z]{2}$/.test(state)))];
  const wantedZones = new Set(zones.map((zone)=>String(zone.code||"").toUpperCase()));
  const headers = { "User-Agent": "ZASNetWeather/1.0 (https://zasnetwx.com/)", Accept: "application/geo+json" };
  const byZone = new Map();
  byZone.failedStates = new Set();
  byZone.details = new Map();
  const collect = (payload) => {
    for(const feature of payload.features||[]){
      const properties=feature.properties||{},vtec=(properties.parameters?.VTEC||[]).map(String),terminalVtec=vtec.some((value)=>/^\/O\.(?:CAN|EXP|UPG)\./i.test(value)),expiresAt=Date.parse(properties.expires||"");
      // The NWS active endpoint can retain the superseded side of an upgrade
      // until the replacement product ends.  UPG/CAN/EXP records describe a
      // lifecycle transition, not a product that should remain independently
      // active.  An already-expired CAP record is likewise not confirmation.
      if(terminalVtec||(Number.isFinite(expiresAt)&&expiresAt<=Date.now()))continue;
      const event=String(properties.event||"Alert");
      const zoneReferences=[...(properties.affectedZones||[]),...(properties.geocode?.UGC||[])];
      for(const zoneUrl of new Set(zoneReferences)){
        const ugc=String(zoneUrl).split("/").pop()?.toUpperCase()||"",compact=wantedZones.has(ugc)?ugc:ugc.replace(/^([A-Z]{2})Z/,"$1");
        if(!wantedZones.has(compact))continue;
        if(!byZone.has(compact))byZone.set(compact,[]);
        if(!byZone.get(compact).includes(event))byZone.get(compact).push(event);
        if(!byZone.details.has(compact))byZone.details.set(compact,[]);
        if(!byZone.details.get(compact).some((item)=>item.id===(feature.id||properties.id||null)))byZone.details.get(compact).push({id:feature.id||properties.id||null,event,headline:properties.headline||"",description:properties.description||"",instruction:properties.instruction||"",onset:properties.onset||null,ends:properties.ends||null,expires:properties.expires||null,sent:properties.sent||null});
      }
    }
  };
  const collectPages = async (initialUrl, timeoutMs) => {
    const visited = new Set();
    let nextUrl = initialUrl;
    let pageCount = 0;
    while(nextUrl){
      if(visited.has(nextUrl))throw new Error("NWS alert inventory pagination loop detected");
      if(pageCount>=50)throw new Error("NWS alert inventory exceeded 50 pages");
      visited.add(nextUrl);
      const payload=await httpsJson(nextUrl,{headers,timeoutMs});
      collect(payload);
      pageCount+=1;
      const next=payload?.pagination?.next;
      nextUrl=typeof next==="string"&&next.trim()?new URL(next,initialUrl).toString():null;
    }
    return pageCount;
  };
  try {
    // One national inventory avoids rate-limiting from dozens of simultaneous
    // state queries and gives every zone the same observation timestamp. The
    // endpoint is paginated during busy periods, so every page must be read or
    // supported alerts can silently disappear from the priority scan.
    await collectPages("https://api.weather.gov/alerts/active",25_000);
  }catch(nationalError){
    console.warn("[wfo-monitor] national NWS alert inventory failed; using state fallback",nationalError.message);
    await mapWithConcurrency(states,4,async(state)=>{
      try{await collectPages(`https://api.weather.gov/alerts/active?area=${encodeURIComponent(state)}`,20_000);}
      catch(error){byZone.failedStates.add(state);console.warn(`[wfo-monitor] NWS alert inventory unavailable for ${state}:`,error.message);}
    });
  }
  return byZone;
}

function cleanProductForStore(w) {
  if (!w || !w.id) {
    return null;
  }
  const timeline = Array.isArray(w.timeline)
    ? w.timeline
        .filter((s) => s && (s.polygon || s.displayGeometry))
        .slice(-40)
        .map((s) => ({
          validFrom: s.validFrom,
          validTo: s.validTo,
          action: s.action,
          polygon: s.polygon,
          location: s.location,
          locationPhrase: s.locationPhrase,
          expiresAt: s.expiresAt
        }))
    : [];
  const bulletinHistory = Array.isArray(w.bulletinHistory)
    ? w.bulletinHistory
        .filter((b) => b && b.text)
        .slice(-80)
        .map((b) => ({
          validFrom: b.validFrom,
          validTo: b.validTo,
          action: b.action,
          text: b.text,
          polygon: b.polygon || w.polygon,
          location: b.location,
          locationPhrase: b.locationPhrase,
          expiresAt: b.expiresAt,
          updatedAt: b.updatedAt
        }))
    : [];
  return {
    id: w.id,
    kind: w.kind || (w.product === "TOA" || w.product === "SVA" ? "spc-watch" : "warning"),
    practice: Boolean(w.practice),
    product: w.product,
    productName: w.productName,
    productId: w.productId,
    watchNumber: w.watchNumber,
    stormType: w.stormType,
    polygon: w.polygon,
    geometry: w.geometry || w.polygon || null,
    displayGeometry: w.displayGeometry || null,
    vertices: Array.isArray(w.vertices) ? w.vertices.slice(0, 500) : undefined,
    counties: w.counties,
    zones: w.zones,
    places: Array.isArray(w.places) ? w.places.slice(0, 80) : [],
    location: w.location,
    locationPhrase: w.locationPhrase,
    locationOverride: w.locationOverride,
    lineStart: w.lineStart || null,
    lineEnd: w.lineEnd || null,
    lineTrace: w.lineTrace || [],
    projectedLineTrace: w.projectedLineTrace || [],
    lineStartPhrase: w.lineStartPhrase || "",
    lineEndPhrase: w.lineEndPhrase || "",
    motion1: w.motion1,
    motion2: w.motion2,
    motion: w.motion,
    motionOverride: w.motionOverride,
    basis: w.basis,
    windId: w.windId,
    hailId: w.hailId,
    validMinutes: w.validMinutes,
    validHours: w.validHours,
    ctas: w.ctas,
    ffw: w.ffw,
    tor: w.tor,
    sps: w.sps,
    text: w.text,
    wfo: w.wfo,
    office: w.office,
    etn: w.etn,
    action: w.action,
    status: w.status,
    issuedAt: w.issuedAt,
    expiresAt: w.expiresAt,
    segment: w.segment,
    color: w.color,
    timeline,
    bulletinHistory,
    updatedAt: w.updatedAt || w.issuedAt || ""
  };
}

function mergeBulletinHistories(existingHistory, incomingHistory) {
  const byKey = new Map();
  [...(existingHistory || []), ...(incomingHistory || [])]
    .filter((b) => b && b.text)
    .forEach((b) => {
      const key = [
        b.action || "",
        b.validFrom || b.updatedAt || "",
        b.validTo || b.expiresAt || "",
        String(b.text || "").slice(0, 160)
      ].join("|");
      byKey.set(key, b);
    });
  return [...byKey.values()]
    .sort((a, b) => new Date(a.validFrom || a.updatedAt || 0) - new Date(b.validFrom || b.updatedAt || 0))
    .slice(-80);
}

function mergeProductStore(existingStore, incomingProducts, options = {}) {
  const retentionHours = Number(options.retentionHours || warningsServerRetentionHours);
  const retentionMs = retentionHours * 3600_000;
  const nowMs = Date.now();
  const byId = new Map();
  const isNewer = (candidate, existing) => {
    if (!existing) {
      return true;
    }
    const c = new Date(candidate.updatedAt || candidate.issuedAt || 0).getTime();
    const e = new Date(existing.updatedAt || existing.issuedAt || 0).getTime();
    return Number.isFinite(c) && (!Number.isFinite(e) || c >= e);
  };

  ((existingStore && existingStore.warnings) || []).forEach((w) => {
    if (w && w.id) {
      byId.set(w.id, w);
    }
  });
  (incomingProducts || [])
    .map(cleanProductForStore)
    .filter(Boolean)
    .forEach((w) => {
      const existing = byId.get(w.id);
      if (isNewer(w, byId.get(w.id))) {
        byId.set(w.id, {
          ...w,
          bulletinHistory: mergeBulletinHistories(existing && existing.bulletinHistory, w.bulletinHistory)
        });
      } else if (existing && Array.isArray(w.bulletinHistory) && w.bulletinHistory.length) {
        byId.set(w.id, {
          ...existing,
          bulletinHistory: mergeBulletinHistories(existing.bulletinHistory, w.bulletinHistory)
        });
      }
    });

  return [...byId.values()].filter((w) => {
    if (!w || !w.id) {
      return false;
    }
    if (w.status === "active") {
      if (w.expiresAt && new Date(w.expiresAt).getTime() < nowMs) {
        const exp = new Date(w.expiresAt).getTime();
        return Number.isFinite(exp) && nowMs - exp < retentionMs;
      }
      return true;
    }
    if (w.status === "cancelled" || w.status === "expired") {
      const t = new Date(w.updatedAt || w.expiresAt || 0).getTime();
      return Number.isFinite(t) && nowMs - t < retentionMs;
    }
    return false;
  });
}

function reconcileGfePublicLifecycle() {
  const gfeEvents=loadGfeProducts().events||[],publicStore=loadPublicAlerts(),warnings=[...(publicStore.warnings||[])];
  let changed=0;
  for(const event of gfeEvents){
    const index=warnings.findIndex((warning)=>warning?.id===`gfe:${event.id}`);
    if(index<0)continue;
    const warning=warnings[index],eventTime=Date.parse(event.updatedAt||event.issuedAt||0),warningTime=Date.parse(warning.updatedAt||warning.issuedAt||0);
    if(!Number.isFinite(eventTime)||eventTime<=warningTime)continue;
    warnings[index]={...warning,product:event.hazardCode||warning.product,productName:event.hazardName||warning.productName,text:event.productText||warning.text,action:event.action||warning.action,status:event.status||warning.status,expiresAt:event.endTime||warning.expiresAt,updatedAt:event.updatedAt||event.issuedAt,bulletinHistory:mergeBulletinHistories(warning.bulletinHistory,(event.history||[]).map((entry)=>({action:entry.action,validFrom:entry.issuedAt,validTo:entry.endTime,expiresAt:entry.endTime,updatedAt:entry.issuedAt,polygon:event.geometry||warning.polygon,text:entry.productText})))};
    changed+=1;
  }
  if(changed)savePublicAlerts({warnings});
  return changed;
}

function saveOpsProducts(payload) {
  fs.mkdirSync(dataDir, { recursive: true });
  const body = {
    updatedAt: new Date().toISOString(),
    warnings: Array.isArray(payload.warnings) ? payload.warnings : []
  };
  fs.writeFileSync(opsProductsFile, JSON.stringify(body, null, 2));
  const stat = fs.statSync(opsProductsFile);
  opsProductsReadCache = { mtimeMs: stat.mtimeMs, size: stat.size, value: body };
  return body;
}

function saveGfeProducts(payload) {
  fs.mkdirSync(dataDir, { recursive: true });
  const body = { updatedAt: new Date().toISOString(), events: Array.isArray(payload.events) ? payload.events : [] };
  fs.writeFileSync(gfeProductsFile, JSON.stringify(body, null, 2));
  return body;
}

function loadWarningAuditLog() {
  try {
    const raw = JSON.parse(fs.readFileSync(warningAuditFile, "utf8"));
    if (raw && Array.isArray(raw.entries)) {
      return raw;
    }
    if (Array.isArray(raw)) {
      return { updatedAt: null, entries: raw };
    }
  } catch {
    /* empty store */
  }
  return { updatedAt: null, entries: [] };
}

function saveWarningAuditLog(entries) {
  fs.mkdirSync(dataDir, { recursive: true });
  const body = {
    updatedAt: new Date().toISOString(),
    entries: Array.isArray(entries) ? entries.slice(0, 500) : []
  };
  fs.writeFileSync(warningAuditFile, JSON.stringify(body, null, 2));
  return body;
}

function appendWarningAuditEntry(entry) {
  const store = loadWarningAuditLog();
  const safeEntry = {
    ...(entry || {}),
    id:
      (entry && entry.id) ||
      `${Date.now()}-${crypto.randomBytes(4).toString("hex")}`,
    at: (entry && entry.at) || new Date().toISOString()
  };
  const existing = new Set((store.entries || []).map((item) => item && item.id).filter(Boolean));
  const entries = existing.has(safeEntry.id)
    ? store.entries.map((item) => (item && item.id === safeEntry.id ? safeEntry : item))
    : [safeEntry, ...(store.entries || [])];
  return saveWarningAuditLog(entries);
}

/** NWS phen/sig for VTEC from our product codes. */
function vtecPhenSig(product) {
  switch (String(product || "").toUpperCase()) {
    case "TOR":
      return { phen: "TO", sig: "W", fileExt: "TOR", wmo: "WFUS" };
    case "SVR":
      return { phen: "SV", sig: "W", fileExt: "SVR", wmo: "WUUS" };
    case "FFW":
      return { phen: "FF", sig: "W", fileExt: "FFW", wmo: "WGUS" };
    case "FAW":
      return { phen: "FA", sig: "W", fileExt: "FLW", wmo: "WGUS" };
    case "FAY":
      return { phen: "FA", sig: "Y", fileExt: "FLS", wmo: "WGUS" };
    case "FRW":
      return { phen: "FR", sig: "W", fileExt: "FRW", wmo: "WOUS" };
    case "SQW":
      return { phen: "SQ", sig: "W", fileExt: "SQW", wmo: "WUUS" };
    case "DSW":
      return { phen: "DS", sig: "W", fileExt: "DSW", wmo: "WWUS" };
    case "DSY":
      return { phen: "DS", sig: "Y", fileExt: "DSW", wmo: "WWUS" };
    case "SPS":
      return { phen: "SPS", sig: "S", fileExt: "SPS", wmo: "WWUS" };
    case "SMW":
      return { phen: "MA", sig: "W", fileExt: "SMW", wmo: "WHUS" };
    default:
      return { phen: "SV", sig: "W", fileExt: "SVR", wmo: "WUUS" };
  }
}

/** GeoJSON [lng,lat] ring → NWS LAT...LON hundredths (west lon absolute). */
function polygonToLatLonBlock(geometry) {
  const rings = polygonRingsLatLon(geometry);
  if (!rings.length) {
    return "";
  }
  // Use exterior ring; close if needed
  let ring = rings[0].map(([lat, lon]) => [lat, lon]);
  if (ring.length < 3) {
    return "";
  }
  const first = ring[0];
  const last = ring[ring.length - 1];
  if (first[0] !== last[0] || first[1] !== last[1]) {
    ring = ring.concat([[first[0], first[1]]]);
  }
  const pairs = ring.map(([lat, lon]) => {
    const la = Math.round(Number(lat) * 100);
    const lo = Math.round(Math.abs(Number(lon)) * 100);
    return `${la} ${lo}`;
  });
  // 4 pairs per line after LAT...LON
  const lines = [];
  for (let i = 0; i < pairs.length; i += 4) {
    const chunk = pairs.slice(i, i + 4).join(" ");
    if (i === 0) {
      lines.push(`LAT...LON ${chunk}`);
    } else {
      lines.push(`      ${chunk}`);
    }
  }
  return lines.join("\n");
}

function formatVtecTime(iso) {
  const d = new Date(iso);
  if (!Number.isFinite(d.getTime())) {
    return "000000T0000Z";
  }
  const yy = String(d.getUTCFullYear()).slice(2);
  const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(d.getUTCDate()).padStart(2, "0");
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mi = String(d.getUTCMinutes()).padStart(2, "0");
  return `${yy}${mm}${dd}T${hh}${mi}Z`;
}

function hourBucketKey(iso) {
  const d = new Date(iso);
  if (!Number.isFinite(d.getTime())) {
    return null;
  }
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, "0");
  const day = String(d.getUTCDate()).padStart(2, "0");
  const h = String(d.getUTCHours()).padStart(2, "0");
  return `${y}${m}${day}${h}`;
}

/** Products GRLevel Warning Settings can render (SPS stays on placefile / public map only). */
const WARNINGS_SERVER_PRODUCTS = new Set(["TOR", "SVR", "FFW", "SMW", "SQW", "DSW"]);

// Public maps can draw additional issued polygons that are intentionally not
// exported through the GRLevel warning server. Keep this separate so SPS
// retains its bulletin polygon instead of falling back to county/zone fills.
const PUBLIC_ISSUED_POLYGON_PRODUCTS = new Set(["TOR", "SVR", "FFW", "SMW", "MWS", "SQW", "DSW", "DSY", "SPS", "FAY"]);

function isWarningsServerProduct(w) {
  if (!w || isSpcWatchProduct(w)) {
    return false;
  }
  return WARNINGS_SERVER_PRODUCTS.has(String(w.product || "").toUpperCase());
}

function usesPublicIssuedPolygon(w) {
  if (!w || isSpcWatchProduct(w)) {
    return false;
  }
  return PUBLIC_ISSUED_POLYGON_PRODUCTS.has(String(w.product || "").toUpperCase());
}

const officeDisplayByWfo = {
  OHX: "Nashville TN",
  HUN: "Huntsville AL",
  RIW: "Riverton WY",
  BIS: "Bismarck ND",
  DLH: "Duluth MN",
  PSR: "Phoenix AZ"
};

function officeDisplayName(wfo) {
  const code = String(wfo || "OHX")
    .replace(/^K/i, "")
    .toUpperCase()
    .slice(0, 3);
  return officeDisplayByWfo[code] || code;
}

/** Strip non-ASCII so GRLevel parsers never choke on UTF-8 (middle-dot, smart quotes, etc.). */
function asciiCleanProductText(text) {
  return String(text || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[^\x09\x0a\x20-\x7e]/g, " ")
    .replace(/[ \t]+\n/g, "\n")
    .trimEnd() + "\n";
}

/**
 * GR2Analyst is stricter than browsers/placefiles: keep public/ops text branded,
 * but make the COD-style warning-server copy look like a normal NWS bulletin.
 */
function grLevelWarningServerText(text) {
  let cleaned = asciiCleanProductText(text)
    .replace(/\bZAS(?:Network|Net) Weather Service\b/g, "National Weather Service")
    .replace(/\b(National Weather Service [A-Z0-9]{3}) Mutual Aid\b/g, "$1")
    .replace(/\b(National Weather Service office in [A-Z0-9]{3}) Mutual Aid\b/g, "$1")
    .replace(/(LAT\.\.\.LON[^\n]*(?:\n\s+\d{4}.*)*)\n\n(TIME\.\.\.MOT\.\.\.LOC)/g, "$1\n$2");
  Object.entries(officeDisplayByWfo).forEach(([wfo, name]) => {
    cleaned = cleaned
      .replace(new RegExp(`\\bNational Weather Service ${wfo}\\b`, "g"), `National Weather Service ${name}`)
      .replace(
        new RegExp(`\\bNational Weather Service office in ${wfo}\\b`, "g"),
        `National Weather Service office in ${name}`
      );
  });
  return cleaned;
}

/**
 * Prefer the ops-issued bulletin when it already has LAT...LON (matches real NWS / COD).
 * Fall back to a minimal synthetic product for GRLevel polygon parse.
 */
function buildNwsStyleProductText(w, segment = null) {
  if (!isWarningsServerProduct(w)) {
    return null; // SPS / watches are not on the COD-style warnings server
  }
  const product = String(w.product || "SVR").toUpperCase();
  const meta = vtecPhenSig(product);
  const action = String((segment && segment.action) || w.action || "NEW").toUpperCase();
  const vtecAction = ["NEW", "CON", "EXT", "CAN", "EXP"].includes(action) ? action : "NEW";
  const office = String(w.wfo || "OHX")
    .replace(/^K/i, "")
    .toUpperCase()
    .slice(0, 3);
  const officeName = officeDisplayName(office);
  const fullOffice = `K${office}`;
  const etn = formatEtnPublic(w.etn);
  const isTerminalAction =
    vtecAction === "CAN" ||
    vtecAction === "EXP" ||
    w.status === "cancelled" ||
    w.status === "expired";
  const terminalTime = w.updatedAt || w.expiresAt || new Date().toISOString();
  const issued =
    (segment && segment.validFrom) ||
    (isTerminalAction ? terminalTime : null) ||
    w.issuedAt ||
    new Date().toISOString();
  const expires =
    (segment && segment.validTo) ||
    (isTerminalAction ? terminalTime : null) ||
    w.expiresAt ||
    new Date(Date.now() + 3600_000).toISOString();
  const poly = (segment && segment.polygon) || w.polygon;
  const latLon = polygonToLatLonBlock(poly);
  if (!latLon) {
    return null;
  }

  // Use the real WarnGen bulletin when present — do NOT wrap it (double headers break GR parsers)
  const rawText = String((segment && segment.text) || w.text || "").trim();
  if (rawText && /LAT\.\.\.LON/i.test(rawText)) {
    // Fix practice WMO stamp "000000" → real ddhhmm (GRLevel rejects bad WMO times)
    let cleaned = grLevelWarningServerText(rawText);
    const issuedDate = new Date(issued);
    if (Number.isFinite(issuedDate.getTime())) {
      const wmoStamp =
        `${String(issuedDate.getUTCDate()).padStart(2, "0")}` +
        `${String(issuedDate.getUTCHours()).padStart(2, "0")}` +
        `${String(issuedDate.getUTCMinutes()).padStart(2, "0")}`;
      cleaned = cleaned.replace(
        // WU=SVR, WF=TOR, WG=FFW/FLW, WW=SPS, WH=SMW (and other marine)
        /^((?:WU|WF|WG|WW|WH)US\d{2}\s+K[A-Z]{3}\s+)000000\b/m,
        `$1${wmoStamp}`
      );
      // NEW VTEC must have a real start time; CON/CAN/EXP correctly use 000000T0000Z
      if (vtecAction === "NEW" || vtecAction === "EXT") {
        cleaned = cleaned.replace(
          /(\/O\.(?:NEW|EXT)\.K[A-Z0-9]{3}\.[A-Z]{2}\.[A-Z]\.\d{4}\.)000000T0000Z-/,
          `$1${formatVtecTime(issued)}-`
        );
      }
    }
    // Draft/review path often baked ETN 0000 before nextEtn was assigned — GR keys
    // polygons by full VTEC, so NEW .0000. never matches later CON/CAN .000N.
    if (etn && etn !== "0000") {
      cleaned = cleaned.replace(
        /(\/O\.(?:NEW|CON|EXT|CAN|EXP)\.K[A-Z0-9]{3}\.[A-Z]{2}\.[A-Z]\.)0000\./g,
        `$1${etn}.`
      );
    }
    return {
      fileExt: meta.fileExt,
      hourKey: hourBucketKey(issued),
      issued,
      expires,
      text: cleaned
    };
  }

  const productName = PRODUCT_NAMES[product] || product;
  const loc = (segment && segment.locationPhrase) || w.locationOverride || w.locationPhrase || "";
  // UGC like NWS/COD: TNC055-… for land, LSZ145-… / AMZ131-… for marine SMW
  const expDate = new Date(expires);
  const ugcExpire = Number.isFinite(expDate.getTime())
    ? `${String(expDate.getUTCDate()).padStart(2, "0")}${String(expDate.getUTCHours()).padStart(2, "0")}${String(expDate.getUTCMinutes()).padStart(2, "0")}`
    : "010000";
  const ugcFromCounties = Array.isArray(w.counties)
    ? w.counties.map((c) => c && c.ugc).filter(Boolean)
    : [];
  const ugcFromZones = Array.isArray(w.zones)
    ? w.zones.map((z) => z && z.ugc).filter(Boolean)
    : [];
  // SMW is marine-zone based; other products prefer county UGC then public zones
  const ugcCodes = (
    product === "SMW"
      ? [...ugcFromZones, ...ugcFromCounties]
      : [...ugcFromCounties, ...ugcFromZones]
  ).slice(0, 40);
  const ugcLine = ugcCodes.length
    ? `${ugcCodes.join("-")}-${ugcExpire}-`
    : product === "SMW"
      ? `AMZ000-${ugcExpire}-`
      : `${office}C000-${ugcExpire}-`;

  const issuedDate = new Date(issued);
  const wmoTime = Number.isFinite(issuedDate.getTime())
    ? `${String(issuedDate.getUTCDate()).padStart(2, "0")}${String(issuedDate.getUTCHours()).padStart(2, "0")}${String(issuedDate.getUTCMinutes()).padStart(2, "0")}`
    : "010000";
  // WMO region digit: WHUS5x for SMW (same convention as coastal marine products)
  const wmoId =
    product === "SMW"
      ? `${meta.wmo}5${office === "RIW" ? "5" : "3"}`
      : `${meta.wmo}53`;
  const lines = [];
  lines.push(`${wmoId} ${fullOffice} ${wmoTime}`);
  lines.push(`${meta.fileExt}${office}`);
  lines.push(ugcLine);
  lines.push(
    `/O.${vtecAction}.${fullOffice}.${meta.phen}.${meta.sig}.${etn}.${formatVtecTime(issued)}-${formatVtecTime(expires)}/`
  );
  lines.push("");
  lines.push("BULLETIN - IMMEDIATE BROADCAST REQUESTED");
  lines.push(productName);
  lines.push(`National Weather Service ${officeName}`);
  lines.push(new Date(issued).toUTCString().replace(/GMT/, "UTC"));
  lines.push("");
  if (product === "SMW") {
    lines.push("...Special Marine Warning for...");
    lines.push("");
    if (ugcFromZones.length || (Array.isArray(w.zones) && w.zones.length)) {
      (w.zones || []).slice(0, 24).forEach((z) => {
        if (z && (z.name || z.ugc)) lines.push(`${z.name || z.ugc}...`);
      });
      lines.push("");
    }
    lines.push(`* ${productName}${loc ? " for " + loc : ""}.`);
  } else {
    lines.push(`The National Weather Service in ${officeName} has issued a`);
    lines.push("");
    lines.push(`* ${productName}${loc ? " for " + loc : ""}.`);
  }
  lines.push("");
  lines.push(`* Until ${new Date(expires).toUTCString()}.`);
  lines.push("");
  lines.push("&&");
  lines.push("");
  lines.push(latLon);
  if (w.motion && Number.isFinite(w.motion.dirDeg) && Number.isFinite(w.motion.speedKt)) {
    const hhmm = formatVtecTime(issued).slice(7, 11);
    const dir = Math.round(w.motion.dirDeg) % 360;
    const spd = Math.round(w.motion.speedKt);
    const rings = polygonRingsLatLon(poly);
    let locLat = 0;
    let locLon = 0;
    if (rings[0] && rings[0].length) {
      const c = centroidOfRing(rings[0]);
      if (c) {
        locLat = Math.round(c[0] * 100);
        locLon = Math.round(Math.abs(c[1]) * 100);
      }
    }
    if (locLat && locLon) {
      lines.push(`TIME...MOT...LOC ${hhmm}Z ${String(dir).padStart(3, "0")}DEG ${spd}KT ${locLat} ${locLon}`);
    }
  }
  lines.push("");
  lines.push("$$");
  lines.push("");
  lines.push(office.slice(0, 3));
  lines.push("");

  return {
    fileExt: meta.fileExt,
    hourKey: hourBucketKey(issued),
    issued,
    expires,
    text: asciiCleanProductText(lines.join("\n"))
  };
}

/**
 * Normalize bulletin text for COD/GR framing (ASCII, LF, trailing blank line).
 */
function normalizeWarningProductText(textLf) {
  let text = String(textLf || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[^\x09\x0a\x20-\x7e]/g, " ")
    .trimEnd();
  if (!text.endsWith("\n")) {
    text += "\n";
  }
  if (!/\n\n$/.test(text)) {
    text += "\n";
  }
  return text;
}

/**
 * COD type files YYYYMMDDHH.SVR / .TOR / .FFW / .SMW:
 *   \n{exactByteLength} \n{payload with \n endings}
 * Length is exact payload bytes and MUST include LAT...LON.
 */
function frameCodTypeProduct(textLf) {
  const text = normalizeWarningProductText(textLf);
  const payload = Buffer.from(text, "utf8");
  const header = Buffer.from(`\n${payload.length} \n`, "utf8");
  return Buffer.concat([header, payload]);
}

/**
 * COD hourly length field is NOT the full product size.
 * Live COD samples (04z 2026-07-12): L=392 / 363 / 010 — windows end mid-text,
 * LAT...LON always lives AFTER the length window, and ETX ends the product.
 *
 * Advertise a short "header prefix" length (WMO through first body paragraph),
 * then write the FULL payload and terminate with ETX — same as COD.
 */
function codHourlyDeclaredLength(payloadRrNn) {
  const text = payloadRrNn.toString("latin1");
  // Prefer end of first blank line after VTEC / H-VTEC block (start of BULLETIN)
  const bulletin = text.search(/\r\r\nBULLETIN\b/);
  if (bulletin > 40) {
    return bulletin;
  }
  // Else first double-blank after start
  const blank = text.indexOf("\r\r\n\r\r\n");
  if (blank > 40) {
    return blank + 6; // include the blank separator
  }
  // Fallback: ~first 1/4 of product or 200 bytes (COD often ~300–400)
  return Math.min(Math.max(80, Math.floor(payloadRrNn.length / 4)), 400);
}

/**
 * COD hourly warnings_YYYYMMDD_HH.txt (matches live warnings.cod.edu):
 *   \x01\r\r\n{shortLen} \r\r\n{FULL payload with \r\r\n newlines}\x03
 *
 * Product boundary = ETX (0x03), not shortLen. shortLen must NOT cover LAT...LON
 * (COD never does). Using full payload length as shortLen can prevent GR from
 * scanning through to LAT...LON / ETX.
 */
function frameCodHourlyProduct(textLf) {
  const text = normalizeWarningProductText(textLf);
  const payload = Buffer.from(text.replace(/\n/g, "\r\r\n"), "utf8");
  let declared = codHourlyDeclaredLength(payload);
  // Never claim a length that includes LAT...LON (COD never does)
  const latAt = payload.indexOf(Buffer.from("LAT...LON"));
  if (latAt > 0 && declared >= latAt) {
    declared = Math.max(40, latAt - 10);
  }
  // Zero-pad to 3 digits when small (COD uses "010" for 10)
  const lenStr = declared < 100 ? String(declared).padStart(3, "0") : String(declared);
  const header = Buffer.from(`\x01\r\r\n${lenStr} \r\r\n`, "utf8");
  const etx = Buffer.from([0x03]);
  return Buffer.concat([header, payload, etx]);
}

/** "soh" = COD hourly, "type" = \nLEN \n payload */
function warningsServerExpectedStyle(frameFn) {
  return frameFn === frameCodHourlyProduct ? "soh" : "type";
}

function warningsServerBufferStyle(buf) {
  if (!buf || !buf.length) {
    return "empty";
  }
  if (buf[0] === 0x01) {
    return "soh";
  }
  if (buf[0] === 0x0a || (buf[0] >= 0x30 && buf[0] <= 0x39)) {
    return "type";
  }
  return "unknown";
}

function warningsServerFileLooksCorrupt(buf, expectedStyle = null) {
  if (!buf || !buf.length) {
    return false;
  }
  const style = warningsServerBufferStyle(buf);
  if (expectedStyle && style !== "empty" && style !== expectedStyle) {
    return true; // e.g. type-framed hourly after we switched back to SOH
  }
  if (style === "soh") {
    if (!buf.includes(0x03)) {
      return true;
    }
    // Trailing junk after final ETX
    const lastEtx = buf.lastIndexOf(0x03);
    if (lastEtx >= 0 && lastEtx < buf.length - 1) {
      const tail = buf.slice(lastEtx + 1);
      if (tail.some((c) => c !== 0x0a && c !== 0x0d) || tail.length > 8) {
        return true;
      }
    }
    // Full-size length that includes LAT in the length window is NOT how COD
    // frames hourlies — rewrite so GR can scan past the prefix to LAT/ETX.
    try {
      if (buf[1] === 0x0d && buf[2] === 0x0d && buf[3] === 0x0a) {
        const sp = buf.indexOf(0x20, 4);
        const declared = parseInt(buf.slice(4, sp).toString("ascii"), 10);
        const start = sp + 4; // after " \r\r\n"
        if (Number.isFinite(declared) && declared > 0) {
          const window = buf.slice(start, start + declared);
          if (window.includes(Buffer.from("LAT...LON"))) {
            return true;
          }
        }
      }
    } catch {
      /* ignore */
    }
    return false;
  }
  if (style === "type") {
    const head = buf.slice(0, 48).toString("latin1");
    const m = head.match(/^\n?(\d+) \n/);
    if (!m) {
      return true;
    }
    const declared = Number(m[1]);
    if (declared > 0 && buf.includes(Buffer.from("LAT...LON"))) {
      const window = buf.slice(m[0].length, m[0].length + declared);
      if (!window.includes(Buffer.from("LAT...LON"))) {
        return true; // length/10 bug
      }
    }
    // Long run of only newlines at end = migration pad (breaks GR)
    let i = buf.length - 1;
    let pad = 0;
    while (i >= 0 && (buf[i] === 0x0a || buf[i] === 0x0d)) {
      pad++;
      i--;
    }
    if (pad > 32) {
      return true;
    }
    return false;
  }
  return true;
}

/**
 * True if this bulletin is already on disk (works for both \n and \r\r\n bodies).
 * NEW vs CON: different VTEC action → not a match. Same VTEC + same LAT prefix → skip.
 */
function warningsFileAlreadyHasProduct(buf, textLf) {
  if (!buf || !buf.length || !textLf) {
    return false;
  }
  const text = String(textLf);
  const vtec = text.match(/\/O\.[A-Z]{3}\.[A-Z0-9.T\-]+\//);
  const lat = text.match(/LAT\.\.\.LON(?:[ \t]+\d+){2,12}/);
  if (vtec) {
    const hasVtec = buf.includes(Buffer.from(vtec[0]));
    if (!hasVtec) {
      return false;
    }
    if (lat) {
      // First coords only — stable across \n vs \r\r\n framing
      const latKey = lat[0].replace(/\s+/g, " ").trim().slice(0, 48);
      return buf.includes(Buffer.from(latKey)) || buf.includes(Buffer.from(lat[0].slice(0, 40)));
    }
    return true;
  }
  // Fallback: first 80 chars of WMO header
  const head = text.split("\n").find((l) => /^(WU|WF|WG|WW)US\d{2}\s+K/.test(l));
  return Boolean(head && buf.includes(Buffer.from(head.slice(0, 32))));
}

/**
 * Append framed products only if not already present.
 * GRLevel tracks a byte offset into each hourly file (like COD) — rewriting the
 * file from scratch makes live polls miss new issues until GR is restarted.
 * Returns number of products newly appended.
 */
function appendWarningProductsToFile(filePath, texts, frameFn) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const expectedStyle = warningsServerExpectedStyle(frameFn);
  let existing = Buffer.alloc(0);
  let fullRewrite = false;
  if (fs.existsSync(filePath)) {
    existing = fs.readFileSync(filePath);
    if (warningsServerFileLooksCorrupt(existing, expectedStyle)) {
      // Wrong style (type vs SOH), length/10, or newline padding — clean rewrite, no pad.
      existing = Buffer.alloc(0);
      fullRewrite = true;
    }
  }

  const chunks = [];
  let existingPlus = existing;
  const batchBuf = () => Buffer.concat(chunks);
  for (const text of texts) {
    if (!text) {
      continue;
    }
    const framed = frameFn(text);
    if (fullRewrite) {
      if (warningsFileAlreadyHasProduct(batchBuf(), text)) {
        continue;
      }
    } else if (warningsFileAlreadyHasProduct(existingPlus, text) || existingPlus.includes(framed)) {
      continue;
    }
    chunks.push(framed);
    if (!fullRewrite) {
      existingPlus = Buffer.concat([existingPlus, framed]);
    }
  }

  if (!fs.existsSync(filePath) && chunks.length === 0) {
    fs.writeFileSync(filePath, Buffer.alloc(0));
    return 0;
  }
  if (fullRewrite) {
    // Exact product bytes only — never pad (pad broke GR multi-product parse).
    fs.writeFileSync(filePath, Buffer.concat(chunks));
    return chunks.length;
  }
  if (chunks.length) {
    fs.appendFileSync(filePath, Buffer.concat(chunks));
  }
  return chunks.length;
}

function writeWarningsServerIndex() {
  fs.mkdirSync(warningsServerDir, { recursive: true });
  const names = fs
    .readdirSync(warningsServerDir)
    .filter((n) => /^\d{10}\.[A-Z0-9]+$/i.test(n) || /^warnings_\d{8}_\d{2}\.txt$/i.test(n))
    .sort()
    .reverse();
  const indexRows = names
    .map((n) => {
      const st = fs.statSync(path.join(warningsServerDir, n));
      const mtime = st.mtime.toISOString().replace("T", " ").slice(0, 16);
      const size = st.size < 1024 ? `${st.size}` : `${Math.round(st.size / 1024)}K`;
      return `<tr><td><a href="/warnings/${n}">${n}</a></td><td align="right">${mtime}</td><td align="right">${size}</td></tr>`;
    })
    .join("\n");
  const indexHtml = `<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 3.2 Final//EN">
<html><head>
<title>Index of /warnings/</title>
<base href="/warnings/">
</head>
<body>
<h1>Index of /warnings/</h1>
<p>ZNCave COD-style Warnings Server — TOR / SVR / FFW / SMW. Other products use the placefile.<br>
Point GR2Analyst: <b>View &rarr; Warning Settings &rarr; Server</b> to<br>
<code>https://YOUR_HOST/warnings/</code> (include trailing slash).<br>
Files are <b>append-only</b> (like COD) so GR live polling picks up new issues without restart.</p>
<table>
<tr><th>Name</th><th>Last modified</th><th>Size</th></tr>
${indexRows || "<tr><td colspan=3>No TOR/SVR/FFW/SMW yet. Issue one from ops.</td></tr>"}
</table>
</body></html>
`;
  fs.writeFileSync(path.join(warningsServerDir, "index.html"), indexHtml, "utf8");
  return names.length;
}

/**
 * Write COD-style warning product files so GRLevel can use:
 *   View → Warning Settings → server = https://YOUR_HOST/warnings/
 *
 * TOR / SVR / FFW / SMW. Other products stay on the placefile + public map.
 *
 * IMPORTANT: GRLevel treats hourly files as append-only (byte-offset poll).
 * We must APPEND new products, never rewrite/truncate the current hour file.
 * Full restart of GR re-reads from offset 0 — which is why "close & reopen works".
 */
function rebuildCodStyleWarningsServer(store) {
  fs.mkdirSync(warningsServerDir, { recursive: true });
  const now = Date.now();
  const cutoff = now - warningsServerRetentionHours * 3600_000;
  /** @type {Map<string, string[]>} file name -> product texts to ensure present (append if missing) */
  const typeBuckets = new Map();
  /** @type {Map<string, string[]>} hourly warnings_*.txt -> product texts */
  const hourBuckets = new Map();

  const hourFileName = (hourKey) =>
    `warnings_${hourKey.slice(0, 8)}_${hourKey.slice(8, 10)}.txt`;

  const addToHour = (hourKey, text) => {
    if (!hourKey || !text) {
      return;
    }
    const hourMs = Date.UTC(
      Number(hourKey.slice(0, 4)),
      Number(hourKey.slice(4, 6)) - 1,
      Number(hourKey.slice(6, 8)),
      Number(hourKey.slice(8, 10))
    );
    if (hourMs < cutoff - 3600_000) {
      return;
    }
    const name = hourFileName(hourKey);
    if (!hourBuckets.has(name)) {
      hourBuckets.set(name, []);
    }
    const list = hourBuckets.get(name);
    if (!list.includes(text)) {
      list.push(text);
    }
  };

  const addToType = (hourKey, fileExt, text) => {
    if (!hourKey || !fileExt || !text) {
      return;
    }
    const typeName = `${hourKey}.${fileExt}`;
    if (!typeBuckets.has(typeName)) {
      typeBuckets.set(typeName, []);
    }
    if (!typeBuckets.get(typeName).includes(text)) {
      typeBuckets.get(typeName).push(text);
    }
  };

  const pushProduct = (w, segment, options = {}) => {
    const mirrorLive = options.mirrorLive !== false;
    const built = buildNwsStyleProductText(w, segment);
    if (!built || !built.hourKey || !built.text) {
      return;
    }

    // Issue-hour (COD default)
    addToHour(built.hourKey, built.text);
    addToType(built.hourKey, built.fileExt, built.text);

    // Also ensure current UTC hour file grows when product is still live so
    // GR's primary poll of warnings_YYYYMMDD_HH.txt sees an append.
    const issuedMs = new Date(built.issued || 0).getTime();
    const expiresMs = new Date(built.expires || 0).getTime();
    const nowKey = hourBucketKey(new Date(now).toISOString());
    if (
      mirrorLive &&
      nowKey &&
      Number.isFinite(issuedMs) &&
      Number.isFinite(expiresMs) &&
      expiresMs > now &&
      nowKey !== built.hourKey
    ) {
      addToHour(nowKey, built.text);
      addToType(nowKey, built.fileExt, built.text);
    }
  };

  (store.warnings || []).forEach((w) => {
    if (!isWarningsServerProduct(w)) {
      return; // skip SPS, SPC watches, etc.
    }
    const status = String(w.status || "active").toLowerCase();
    const history = Array.isArray(w.bulletinHistory)
      ? w.bulletinHistory.filter((b) => b && b.text)
      : [];
    if (status === "cancelled" || status === "expired") {
      const terminalMs = new Date(w.updatedAt || w.expiresAt || 0).getTime();
      if (
        Number.isFinite(terminalMs) &&
        terminalMs <= now + 60_000 &&
        now - terminalMs <= warningsServerCancelNoticeMs
      ) {
        // Append terminal CAN/EXP so GR can drop the polygon (do not rewrite history)
        if (history.length) {
          // Only the latest terminal bulletin
          const last = history[history.length - 1];
          pushProduct(w, last, { mirrorLive: true });
        } else {
          pushProduct(w, null, { mirrorLive: true });
        }
      }
      return;
    }
    if (status && status !== "active") {
      return;
    }
    if (w.expiresAt && new Date(w.expiresAt).getTime() < now - 15 * 60_000) {
      return;
    }
    if (history.length) {
      // Append any history segments not yet on disk (NEW, then CON, …)
      history.forEach((bulletin) => pushProduct(w, bulletin));
    } else if (Array.isArray(w.timeline) && w.timeline.length) {
      w.timeline.forEach((seg) => pushProduct(w, seg));
    } else if (w.polygon) {
      pushProduct(w, null);
    }
  });

  // Ensure current hour file exists for GR HEAD/GET even with no products yet
  const nowKey = hourBucketKey(new Date().toISOString());
  if (nowKey && !hourBuckets.has(hourFileName(nowKey))) {
    hourBuckets.set(hourFileName(nowKey), []);
  }

  // Drop files older than retention (whole file remove is OK — GR no longer polls them)
  for (const name of fs.readdirSync(warningsServerDir)) {
    if (!/^\d{10}\.[A-Z0-9]+$/i.test(name) && !/^warnings_\d{8}_\d{2}\.txt$/i.test(name)) {
      continue;
    }
    let hourKey = null;
    if (/^warnings_(\d{8})_(\d{2})\.txt$/i.test(name)) {
      const m = name.match(/^warnings_(\d{8})_(\d{2})\.txt$/i);
      hourKey = `${m[1]}${m[2]}`;
    } else if (/^(\d{10})\./i.test(name)) {
      hourKey = name.slice(0, 10);
    }
    if (!hourKey) {
      continue;
    }
    const hourMs = Date.UTC(
      Number(hourKey.slice(0, 4)),
      Number(hourKey.slice(4, 6)) - 1,
      Number(hourKey.slice(6, 8)),
      Number(hourKey.slice(8, 10))
    );
    if (hourMs < cutoff - 3600_000) {
      fs.rmSync(path.join(warningsServerDir, name), { force: true });
    }
  }

  let appended = 0;
  for (const [name, texts] of typeBuckets) {
    appended += appendWarningProductsToFile(
      path.join(warningsServerDir, name),
      texts,
      frameCodTypeProduct
    );
  }
  for (const [name, texts] of hourBuckets) {
    appended += appendWarningProductsToFile(
      path.join(warningsServerDir, name),
      texts,
      frameCodHourlyProduct
    );
  }

  // Current hour empty placeholder if still missing
  if (nowKey) {
    const curPath = path.join(warningsServerDir, hourFileName(nowKey));
    if (!fs.existsSync(curPath)) {
      fs.writeFileSync(curPath, Buffer.alloc(0));
    }
  }

  const fileCount = writeWarningsServerIndex();
  console.log(
    `[warnings-server] append-only sync: +${appended} product(s), ${fileCount} file(s) in ${warningsServerDir}`
  );
  return { appended, fileCount };
}

/** Resolve product files case-insensitively (Linux is case-sensitive; browsers may request .svr). */
function resolveWarningsServerFile(requestedName) {
  fs.mkdirSync(warningsServerDir, { recursive: true });
  if (!requestedName || requestedName === "." || requestedName === "index.html") {
    return path.join(warningsServerDir, "index.html");
  }
  const direct = path.join(warningsServerDir, requestedName);
  if (fs.existsSync(direct) && fs.statSync(direct).isFile()) {
    return direct;
  }
  // Case-insensitive match (e.g. 2026071121.svr → 2026071121.SVR)
  const want = requestedName.toLowerCase();
  try {
    const hit = fs.readdirSync(warningsServerDir).find((n) => n.toLowerCase() === want);
    if (hit) {
      return path.join(warningsServerDir, hit);
    }
  } catch {
    /* empty */
  }
  return direct;
}

function logWarningsServerRequest(request, status, name, size = 0) {
  const ua = String((request && request.headers && request.headers["user-agent"]) || "")
    .replace(/\s+/g, " ")
    .slice(0, 80);
  console.log(
    `[warnings-server] ${request.method || "GET"} ${name || "/"} -> ${status} ${size}b${ua ? ` ua="${ua}"` : ""}`
  );
}

function handleWarningsServerRequest(request, requestUrl, response) {
  // GET/HEAD /warnings/  or  /warnings/2026071120.SVR (any case)
  // GRLevel probes with HEAD + expects Content-Length (like COD/Apache).
  const method = String((request && request.method) || "GET").toUpperCase();
  const isHead = method === "HEAD";

  // Redirect /warnings → /warnings/ so relative links never break
  if (requestUrl.pathname === "/warnings") {
    logWarningsServerRequest(request, 301, "/warnings", 0);
    response.writeHead(301, {
      Location: "/warnings/",
      ...warningsServerNoCacheHeaders,
      "Content-Length": 0
    });
    response.end();
    return true;
  }

  let raw = decodeURIComponent(requestUrl.pathname.replace(/^\/warnings\/?/, "") || "index.html");
  // Strip query-ish junk; block path escape
  raw = raw.split("?")[0].split("#")[0];
  const safe = path.normalize(raw).replace(/^(\.\.(\/|\\|$))+/, "");
  if (safe.includes("..") || path.isAbsolute(safe)) {
    logWarningsServerRequest(request, 403, safe, 0);
    response.writeHead(403, { "Content-Length": 0 });
    response.end();
    return true;
  }

  // Rebuild when empty, stale SPS, or framing broken (SOH hourlies / length/10)
  try {
    const names = fs.existsSync(warningsServerDir) ? fs.readdirSync(warningsServerDir) : [];
    const hasProducts = names.some((n) => /^\d{10}\./i.test(n) || /^warnings_\d{8}_\d{2}\.txt$/i.test(n));
    const hasStaleSps = names.some((n) => /\.SPS$/i.test(n));
    let framingBroken = false;
    for (const n of names) {
      if (!/^warnings_\d{8}_\d{2}\.txt$/i.test(n) && !/^\d{10}\./i.test(n)) {
        continue;
      }
      try {
        const sample = fs.readFileSync(path.join(warningsServerDir, n));
        if (!sample.length) {
          continue;
        }
        const expected = /^warnings_/i.test(n) ? "soh" : "type";
        if (warningsServerFileLooksCorrupt(sample, expected)) {
          framingBroken = true;
          break;
        }
      } catch {
        /* ignore sample */
      }
    }
    if (!hasProducts || hasStaleSps || framingBroken) {
      rebuildCodStyleWarningsServer(loadPublicAlerts());
    }
  } catch {
    try {
      rebuildCodStyleWarningsServer(loadPublicAlerts());
    } catch {
      /* ignore */
    }
  }

  const filePath = resolveWarningsServerFile(safe === "" || safe === "." ? "index.html" : safe);

  if (!filePath.startsWith(warningsServerDir)) {
    response.writeHead(403, { "Content-Length": 0 });
    response.end();
    return true;
  }

  if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
    // Directory / missing file → show index so GRLevel still sees the listing
    const indexPath = path.join(warningsServerDir, "index.html");
    if (fs.existsSync(indexPath) && (safe === "" || safe === "." || safe === "index.html")) {
      const body = fs.readFileSync(indexPath);
      logWarningsServerRequest(request, 200, "index.html", body.length);
      response.writeHead(200, {
        "Content-Type": "text/html",
        "Content-Length": body.length,
        "Accept-Ranges": "bytes",
        ...warningsServerNoCacheHeaders
      });
      if (isHead) {
        response.end();
      } else {
        response.end(body);
      }
      return true;
    }
    const msg = `Not found: ${safe}\nTip: product files use UPPERCASE extensions (e.g. .SVR).\nList: /warnings/\n`;
    logWarningsServerRequest(request, 404, safe, Buffer.byteLength(msg));
    response.writeHead(404, {
      "Content-Type": "text/plain",
      "Content-Length": Buffer.byteLength(msg),
      ...warningsServerNoCacheHeaders
    });
    if (isHead) {
      response.end();
    } else {
      response.end(msg);
    }
    return true;
  }

  const stats = fs.statSync(filePath);
  const ext = path.extname(filePath).toLowerCase();
  // Match COD/Apache: text/plain (no charset) + Content-Length + Accept-Ranges
  const type = ext === ".html" ? "text/html" : "text/plain";
  const size = stats.size;
  const baseHeaders = {
    "Content-Type": type,
    "Accept-Ranges": "bytes",
    "Last-Modified": stats.mtime.toUTCString(),
    ...warningsServerNoCacheHeaders
  };

  // GR2Analyst polls with Range: bytes=<prevSize>- after the first full GET.
  // Match live COD/Apache (warnings.cod.edu):
  // - Satisfiable open range → 206 with ONLY the new tail (append-only).
  // - At/past EOF (no new bytes) → 416. Returning 200+full body for a Range
  //   request makes GR treat the body as a delta append and corrupt its state
  //   (we used to "stale→full" every idle poll — that was the regression).
  const rangeHeader = String((request && request.headers && request.headers.range) || "").trim();
  let start = 0;
  let end = size > 0 ? size - 1 : 0;
  let status = 200;
  let rangeNote = "";

  if (rangeHeader && /^bytes=/i.test(rangeHeader)) {
    // Support: bytes=START-  |  bytes=START-END  |  bytes=-SUFFIX
    const spec = rangeHeader.replace(/^bytes=/i, "").split(",")[0].trim();
    const m = spec.match(/^(\d*)-(\d*)$/);
    if (m) {
      let reqStart;
      let reqEnd;
      if (m[1] === "" && m[2] !== "") {
        const suffix = Number(m[2]);
        reqStart = size > 0 ? Math.max(0, size - suffix) : 0;
        reqEnd = size > 0 ? size - 1 : 0;
      } else {
        reqStart = m[1] !== "" ? Number(m[1]) : 0;
        reqEnd = m[2] !== "" ? Number(m[2]) : size > 0 ? size - 1 : 0;
      }
      rangeNote = ` range=${spec}`;

      if (!Number.isFinite(reqStart) || !Number.isFinite(reqEnd) || reqStart < 0) {
        // Malformed range → ignore and serve full file
        start = 0;
        end = size > 0 ? size - 1 : 0;
        status = 200;
      } else if (size === 0 || reqStart >= size) {
        // Unsatisfiable (idle poll at EOF, empty file, or offset past rewrite).
        // COD returns 416 here — GR keeps its offset and retries next cycle.
        logWarningsServerRequest(
          request,
          416,
          path.basename(filePath) + rangeNote + " unsat",
          0
        );
        response.writeHead(416, {
          "Content-Range": `bytes */${size}`,
          "Content-Type": "text/plain",
          "Content-Length": 0,
          "Accept-Ranges": "bytes",
          ...warningsServerNoCacheHeaders
        });
        response.end();
        return true;
      } else if (reqStart === 0 && (m[2] === "" || reqEnd >= size - 1)) {
        // bytes=0-  equivalent to full GET
        start = 0;
        end = size - 1;
        status = 200;
      } else {
        start = reqStart;
        end = Math.min(reqEnd, size - 1);
        if (end < start) {
          logWarningsServerRequest(
            request,
            416,
            path.basename(filePath) + rangeNote + " unsat",
            0
          );
          response.writeHead(416, {
            "Content-Range": `bytes */${size}`,
            "Content-Type": "text/plain",
            "Content-Length": 0,
            "Accept-Ranges": "bytes",
            ...warningsServerNoCacheHeaders
          });
          response.end();
          return true;
        }
        status = 206;
      }
    }
  }

  const chunkLen = size === 0 ? 0 : end - start + 1;
  const headers = {
    ...baseHeaders,
    "Content-Length": chunkLen
  };
  if (status === 206) {
    headers["Content-Range"] = `bytes ${start}-${end}/${size}`;
  }

  logWarningsServerRequest(
    request,
    status,
    path.basename(filePath) + (status === 206 ? `@${start}-${end}` : "") + rangeNote,
    chunkLen
  );
  response.writeHead(status, headers);
  if (isHead) {
    response.end();
    return true;
  }
  if (size === 0) {
    response.end();
    return true;
  }
  fs.createReadStream(filePath, { start, end }).pipe(response);
  return true;
}

