const permanentPublicOutlookRegionKeys = new Set(Object.keys(publicOutlookRegions));
const gfsOnlyPublicOutlookRegionKeys = new Set(Object.entries(publicOutlookRegions).filter(([, definition]) => definition.gfsOnly).map(([key]) => key));
const gfsUsPublicOutlookRegionKeys = new Set(Object.entries(publicOutlookRegions).filter(([, definition]) => definition.gfsUs).map(([key]) => key));
