function loadTemporaryMapRegions({ activeOnly = false } = {}) {
  let store = { updatedAt: null, updatedBy: null, regions: [] };
  try {
    const raw = JSON.parse(fs.readFileSync(temporaryMapRegionsFile, "utf8"));
    if (raw && Array.isArray(raw.regions)) store = raw;
  } catch { /* empty store */ }
  if (!activeOnly) return store;
  const now = Date.now();
  return {
    ...store,
    regions: store.regions.filter((region) => Date.parse(region.expiresAt) > now)
  };
}

function cleanTemporaryMapRegions(value) {
  if (!Array.isArray(value)) throw new Error("Expected a regions array");
  return value.slice(0, 20).map((raw, index) => {
    if (!raw || typeof raw !== "object") throw new Error(`Region ${index + 1} is invalid`);
    const label = String(raw.label || "").trim().slice(0, 60);
    const slugBase = String(raw.id || label).trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 45);
    const id = `meso-${slugBase.replace(/^meso-/, "")}`;
    const bbox = [raw.west, raw.south, raw.east, raw.north].map(Number);
    const expiresAt = new Date(raw.expiresAt).toISOString();
    const fallback = String(raw.fallback || "");
    const domains=[...new Set((Array.isArray(raw.domains)?raw.domains:[raw.domain]).map((item)=>String(item||"").toUpperCase()).filter(Boolean))];
    const domain=domains[0]||"";
    if (!label || !/^meso-[a-z0-9][a-z0-9-]*$/.test(id)) throw new Error(`Region ${index + 1} needs a name`);
    if (new Set(value.slice(0, index).map((entry) => String(entry.id || entry.label).trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^meso-/, ""))).has(id.replace(/^meso-/, ""))) throw new Error(`Duplicate region: ${label}`);
    if (!bbox.every(Number.isFinite) || bbox[0] < -180 || bbox[2] > 180 || bbox[1] < -90 || bbox[3] > 90 || bbox[0] >= bbox[2] || bbox[1] >= bbox[3]) throw new Error(`Region ${label} has invalid bounds`);
    if (bbox[2] - bbox[0] > 30 || bbox[3] - bbox[1] > 22) throw new Error(`Region ${label} is too large for a mesoscale view`);
    if (!Number.isFinite(Date.parse(expiresAt))) throw new Error(`Region ${label} needs an expiration time`);
    if (!permanentPublicOutlookRegionKeys.has(fallback)) throw new Error(`Region ${label} has an invalid fallback`);
    if (domains.some((item)=>!ncepForecastDomains.has(item))) throw new Error(`Region ${label} has an invalid NCEP domain`);
    const displayBbox=expandWeatherMapBboxToFrame(bbox,1400,654);
    const displayBounds={west:displayBbox[0],south:displayBbox[1],east:displayBbox[2],north:displayBbox[3]};
    return { id, label, bbox, west: bbox[0], south: bbox[1], east: bbox[2], north: bbox[3], displayBounds, expiresAt, fallback, domain, domains };
  });
}

function saveTemporaryMapRegions(regions, session) {
  fs.mkdirSync(dataDir, { recursive: true });
  const body = { updatedAt: new Date().toISOString(), updatedBy: String(session.username || "admin").slice(0, 80), regions };
  fs.writeFileSync(temporaryMapRegionsFile, JSON.stringify(body, null, 2), { encoding: "utf8", mode: 0o600 });
  syncTemporaryMapRegions();
  return body;
}

function syncTemporaryMapRegions() {
  Object.keys(publicOutlookRegions).forEach((key) => { if (!permanentPublicOutlookRegionKeys.has(key)) delete publicOutlookRegions[key]; });
  loadTemporaryMapRegions({ activeOnly: true }).regions.forEach((region) => {
    publicOutlookRegions[region.id] = { label: region.label, bbox: region.bbox, temporary: true, expiresAt: region.expiresAt, fallback: region.fallback };
  });
}

syncTemporaryMapRegions();

function renderAdminMapBaseSvg() {
  const width = 1180, height = 530, west = -125.5, east = -66.5, south = 24, north = 50.5;
  const project = ([lon, lat]) => [(lon - west) / (east - west) * width, (north - lat) / (north - south) * height];
  const paths = loadOutlookStateGeometry().map((feature) => outlookGeometryPath(feature.geometry, project)).filter(Boolean).map((d) => `<path d="${d}"/>`).join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><rect width="100%" height="100%" fill="#101812"/><g fill="#26352b" stroke="#829477" stroke-width="1.2" vector-effect="non-scaling-stroke">${paths}</g></svg>`;
}

function renderPublicWrfOperationsMapSvg(sectors = []) {
  const width = 1180, height = 530, west = -125.5, east = -66.5, south = 24, north = 50.5;
  const x = (longitude) => (Number(longitude) - west) / (east - west) * width;
  const y = (latitude) => (north - Number(latitude)) / (north - south) * height;
  const colors = ["#9caf88", "#d5b85a", "#68a7c2"];
  const overlays = sectors.map((sector, index) => {
    const bounds = sector?.bounds;
    if (![bounds?.west, bounds?.south, bounds?.east, bounds?.north].every(Number.isFinite)) return "";
    const left = x(bounds.west), top = y(bounds.north);
    const boxWidth = x(bounds.east) - left, boxHeight = y(bounds.south) - top;
    if (boxWidth <= 0 || boxHeight <= 0) return "";
    const color = colors[index % colors.length];
    const labelX = Math.max(8, Math.min(width - 90, left + 10));
    const labelY = Math.max(24, Math.min(height - 8, top + 25));
    return `<g><rect x="${left.toFixed(2)}" y="${top.toFixed(2)}" width="${boxWidth.toFixed(2)}" height="${boxHeight.toFixed(2)}" rx="5" fill="${color}" fill-opacity=".28" stroke="${color}" stroke-width="4" vector-effect="non-scaling-stroke"/><text x="${labelX.toFixed(2)}" y="${labelY.toFixed(2)}" fill="#fff" stroke="#101812" stroke-width="3" paint-order="stroke" font-family="system-ui,sans-serif" font-size="20" font-weight="900">${escapeSvgText(sector.domain)}</text></g>`;
  }).join("");
  return renderAdminMapBaseSvg()
    .replace("<svg ", '<svg role="img" aria-label="United States map showing current ZNWS-WRF sector coverage" ')
    .replace("</svg>", `<g aria-label="Active model sectors">${overlays}</g></svg>`);
}

