async function fetchNoaaModelRecord(baseUrls, match, unavailableMessage) {
  const failures = [];
  for (const base of baseUrls) {
    try {
      const index = (await fetchBuffer(`${base}.idx`)).toString("utf8").split("\n");
      const record = index.findIndex((line) => match.test(line));
      if (record < 0) throw new Error(unavailableMessage);
      const start = Number(index[record].split(":")[1]);
      const nextStart = Number(index[record + 1]?.split(":")[1]);
      if (!Number.isFinite(start) || !Number.isFinite(nextStart)) throw new Error("The model inventory was incomplete");
      const buffer = await fetchBuffer(base, 0, { headers: { Range: `bytes=${start}-${nextStart - 1}` }, timeoutMs: 20_000 });
      return { buffer, source: new URL(base).hostname };
    } catch (error) {
      failures.push(`${new URL(base).hostname}: ${error.message}`);
    }
  }
  throw new Error(`${unavailableMessage} (${failures.join("; ")})`);
}

async function getHrrrModelField(product, run, forecastHour) {
  const config = hrrrModelProducts[product];
  if (!config) throw new Error("Unknown HRRR model product");
  if (!/^\d{10}$/.test(run) || !Number.isInteger(forecastHour) || forecastHour < 0 || forecastHour > 48) throw new Error("Invalid HRRR model frame");
  const date = run.slice(0, 8), hour = run.slice(8, 10), forecast = String(forecastHour).padStart(2, "0");
  const workDir = path.join(dataDir, "generated", "hrrr-model"), filePath = path.join(workDir, `${product}-${run}-f${forecast}.grb2`);
  fs.mkdirSync(workDir, { recursive: true });
  const minimumBytes = config.minimumBytes || 40_000;
  if (fs.existsSync(filePath) && fs.statSync(filePath).size > minimumBytes) return filePath;
  const relative = `hrrr.${date}/conus/hrrr.t${hour}z.${config.fileFamily || "wrfsfc"}f${forecast}.grib2`;
  const { buffer } = await fetchNoaaModelRecord([
    `https://noaa-hrrr-bdp-pds.s3.amazonaws.com/${relative}`,
    `https://nomads.ncep.noaa.gov/pub/data/nccf/com/hrrr/prod/${relative}`
  ], config.match, `${config.title} is unavailable for this HRRR frame`);
  if (buffer.length < minimumBytes || buffer.subarray(0, 4).toString("ascii") !== "GRIB") throw new Error("The HRRR model record was incomplete");
  fs.writeFileSync(filePath, buffer);
  return filePath;
}

async function getGfsModelField(product, run, forecastHour) {
  const config = gfsModelProducts[product];
  if (!config || !/^\d{10}$/.test(run) || !Number.isInteger(forecastHour) || forecastHour < 0 || forecastHour > (config.maximumHour || 120) || forecastHour % 3) throw new Error("Invalid GFS model frame");
  const date = run.slice(0, 8), hour = run.slice(8, 10), forecast = String(forecastHour).padStart(3, "0");
  const workDir = path.join(dataDir, "generated", "gfs-model"), filePath = path.join(workDir, `${product}-${run}-f${forecast}.grb2`);
  fs.mkdirSync(workDir, { recursive: true });
  if (fs.existsSync(filePath) && fs.statSync(filePath).size > 40_000) return filePath;
  const relative = `gfs.${date}/${hour}/atmos/gfs.t${hour}z.pgrb2.0p25.f${forecast}`;
  const { buffer } = await fetchNoaaModelRecord([
    `https://noaa-gfs-bdp-pds.s3.amazonaws.com/${relative}`,
    `https://nomads.ncep.noaa.gov/pub/data/nccf/com/gfs/prod/${relative}`
  ], config.match, "This GFS field is unavailable for this frame");
  if (buffer.length < 40_000 || buffer.subarray(0, 4).toString("ascii") !== "GRIB") throw new Error("The GFS reflectivity record was incomplete");
  fs.writeFileSync(filePath, buffer); return filePath;
}

async function getHafsModelFields(model, stormId, domain, product, run, forecastHour) {
  const config = hafsModelProducts[product];
  if (!config || !["storm","parent"].includes(domain) || !Object.hasOwn(hafsModelCatalogCaches, model) || !/^[0-9]{2}[a-z]$/.test(stormId) || !/^\d{10}$/.test(run) || !Number.isInteger(forecastHour) || forecastHour < 0 || forecastHour > 126 || forecastHour % 3) throw new Error("Invalid HAFS model frame");
  const date=run.slice(0,8),hour=run.slice(8,10),forecast=String(forecastHour).padStart(3,"0"),workDir=path.join(dataDir,"generated","hafs-model");
  fs.mkdirSync(workDir,{recursive:true});
  const base=`https://nomads.ncep.noaa.gov/pub/data/nccf/com/hafs/prod/${model}.${date}/${hour}/${stormId}.${run}.${model}.${domain}.${config.fileFamily||"atm"}.f${forecast}.grb2`;
  const index=(await fetchBuffer(`${base}.idx`)).toString("utf8").split("\n"),matches=config.vectorMatches||[config.match],paths=[];
  for (let fieldIndex=0;fieldIndex<matches.length;fieldIndex+=1) {
    const filePath=path.join(workDir,`${model}-${stormId}-${domain}-${product}-${run}-f${forecast}-${fieldIndex}.grb2`);
    if (fs.existsSync(filePath)&&fs.statSync(filePath).size>10_000){paths.push(filePath);continue;}
    const record=index.findIndex((line)=>matches[fieldIndex].test(line));
    if(record<0)throw new Error(`${config.title} is unavailable for this HAFS frame`);
    const start=Number(index[record].split(":")[1]),end=Number(index[record+1]?.split(":")[1])-1,buffer=await fetchBuffer(base,0,{headers:{Range:`bytes=${start}-${end}`}});
    if(buffer.length<10_000||buffer.subarray(0,4).toString("ascii")!=="GRIB")throw new Error("The HAFS model record was incomplete");
    fs.writeFileSync(filePath,buffer);paths.push(filePath);
  }
  return paths;
}

async function renderHafsModelField(model,stormId,domain,product,run,forecastHour,selectedRegion,project,cacheStem){
  if(hafsModelProducts[product]?.combinedReflectivityPressure){
    const [reflectivity,pressure]=await Promise.all([
      renderHafsModelField(model,stormId,domain,"refc",run,forecastHour,selectedRegion,project,`${cacheStem}-refc`),
      renderHafsModelField(model,stormId,domain,"pressure",run,forecastHour,selectedRegion,project,`${cacheStem}-pressure`)
    ]);
    return {...reflectivity,pressureTifPath:pressure.tifPath};
  }
  const config=hafsModelProducts[product],fields=await getHafsModelFields(model,stormId,domain,product,run,forecastHour),[west,south,east,north]=selectedRegion.bbox,[x,y]=project([west,north]),[right,bottom]=project([east,south]);
  const workDir=path.join(dataDir,"generated","hafs-model"),stamp=`${model}-${stormId}-${domain}-${run}-f${String(forecastHour).padStart(3,"0")}`,tif=path.join(workDir,`${cacheStem}-${stamp}.tif`),png=path.join(workDir,`${cacheStem}-${stamp}.png`),width=Math.max(1,Math.round(right-x)),height=Math.max(1,Math.round(bottom-y));
  if(!fs.existsSync(png)||fs.statSync(png).size<1_000){
    const warped=[];
    for(let index=0;index<fields.length;index+=1){const target=path.join(workDir,`${cacheStem}-${stamp}-raw${index}.tif`);await runWeatherMapCommand("gdalwarp",["-overwrite","-q","-t_srs","EPSG:4326","-te",String(west),String(south),String(east),String(north),"-ts",String(width),String(height),"-r","bilinear","-dstnodata","-9999","-of","GTiff",fields[index],target]);warped.push(target);}
    if(config.calc){const args=["-A",warped[0]];if(warped[1])args.push("-B",warped[1]);args.push(`--calc=${config.calc}`,"--type=Float32","--NoDataValue=-9999","--overwrite",`--outfile=${tif}`);await runWeatherMapCommand("gdal_calc.py",args);}else fs.copyFileSync(warped[0],tif);
    await runWeatherMapCommand("gdaldem",["color-relief",tif,path.join(__dirname,"scripts",config.colors),png,"-of","PNG","-alpha"]);
  }
  const runTime=Date.UTC(Number(run.slice(0,4)),Number(run.slice(4,6))-1,Number(run.slice(6,8)),Number(run.slice(8,10)));
  return{dataUri:`data:image/png;base64,${fs.readFileSync(png).toString("base64")}`,tifPath:tif,x,y,width:right-x,height:bottom-y,runTime,validTime:runTime+forecastHour*3_600_000};
}

async function renderGfsModelField(product, run, forecastHour, selectedRegion, project, cacheStem) {
  if (product === "pcpn") return renderGfsPrecipitationPressureThickness(run, forecastHour, selectedRegion, project, cacheStem);
  const config = gfsModelProducts[product], grib = await getGfsModelField(product, run, forecastHour);
  const [west, south, east, north] = selectedRegion.bbox, [x, y] = project([west, north]), [right, bottom] = project([east, south]);
  const workDir = path.join(dataDir, "generated", "gfs-model"), stamp = `${run}-f${String(forecastHour).padStart(3, "0")}`;
  const tif = path.join(workDir, `${cacheStem}-${stamp}.tif`), rawTif = path.join(workDir, `${cacheStem}-${stamp}-raw.tif`), png = path.join(workDir, `${cacheStem}-${stamp}.png`);
  if (!fs.existsSync(png) || fs.statSync(png).size < 1_000) {
    const resampling = selectedRegion.gfsOnly ? "bilinear" : config.resampling || "bilinear";
    await runWeatherMapCommand("gdalwarp", ["-overwrite", "-q", "-t_srs", "EPSG:4326", "-te", String(west), String(south), String(east), String(north), "-ts", String(Math.round(right - x)), String(Math.round(bottom - y)), "-r", resampling, "-dstnodata", "-9999", "-of", "GTiff", grib, config.calc ? rawTif : tif]);
    if (config.calc) await runWeatherMapCommand("gdal_calc.py", ["-A", rawTif, `--calc=${config.calc}`, "--type=Float32", "--NoDataValue=-9999", "--overwrite", `--outfile=${tif}`]);
    await runWeatherMapCommand("gdaldem", ["color-relief", tif, path.join(__dirname, "scripts", config.colors), png, "-of", "PNG", "-alpha"]);
  }
  const runTime = Date.UTC(Number(run.slice(0, 4)), Number(run.slice(4, 6)) - 1, Number(run.slice(6, 8)), Number(run.slice(8, 10)));
  return { dataUri: `data:image/png;base64,${fs.readFileSync(png).toString("base64")}`, tifPath: tif, x, y, width: right - x, height: bottom - y, runTime, validTime: runTime + forecastHour * 3_600_000 };
}

function renderGfsContourPaths(features, project, valueKey, styleForValue) {
  return features.flatMap((feature) => {
    const value = Number(feature.properties?.[valueKey]), geometry = feature.geometry;
    const lines = geometry?.type === "LineString" ? [geometry.coordinates] : geometry?.type === "MultiLineString" ? geometry.coordinates : [];
    return lines.map((line) => {
      const points = [];
      for (const point of line || []) {
        const projected = project(point), previous = points.at(-1);
        if (!previous || Math.hypot(projected[0] - previous[0], projected[1] - previous[1]) >= 1.4) points.push(projected);
      }
      if (points.length < 3) return "";
      const d = points.map(([x, y], index) => `${index ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`).join("");
      return `<path d="${d}" fill="none" ${styleForValue(value)} vector-effect="non-scaling-stroke"/>`;
    });
  }).filter(Boolean).join("");
}

async function renderGfsPrecipitationPressureThickness(run, forecastHour, selectedRegion, project, cacheStem) {
  if (forecastHour < 6 || forecastHour % 6) throw new Error("GFS six-hour precipitation rate is available at six-hour intervals");
  const [rateGrib, pressureGrib, height500Grib, height1000Grib] = await Promise.all([
    getGfsModelField("pcpn", run, forecastHour), getGfsModelField("prmsl", run, forecastHour),
    getGfsModelField("hgt500", run, forecastHour), getGfsModelField("hgt1000", run, forecastHour)
  ]);
  const [west, south, east, north] = selectedRegion.bbox, [x, y] = project([west, north]), [right, bottom] = project([east, south]);
  const workDir = path.join(dataDir, "generated", "gfs-model"), stamp = `${run}-f${String(forecastHour).padStart(3, "0")}`;
  const width = Math.round(right - x), height = Math.round(bottom - y), rateRaw = path.join(workDir, `${cacheStem}-${stamp}-rate-raw.tif`);
  const tif = path.join(workDir, `${cacheStem}-${stamp}.tif`), pressureTif = path.join(workDir, `${cacheStem}-${stamp}-pressure.tif`);
  const height500Tif = path.join(workDir, `${cacheStem}-${stamp}-hgt500.tif`), height1000Tif = path.join(workDir, `${cacheStem}-${stamp}-hgt1000.tif`);
  const thicknessTif = path.join(workDir, `${cacheStem}-${stamp}-thickness.tif`), png = path.join(workDir, `${cacheStem}-${stamp}.png`);
  const pressureContours = path.join(workDir, `${cacheStem}-${stamp}-pressure.geojson`), thicknessContours = path.join(workDir, `${cacheStem}-${stamp}-thickness.geojson`);
  const warp = (source, target) => runWeatherMapCommand("gdalwarp", ["-overwrite", "-q", "-t_srs", "EPSG:4326", "-te", String(west), String(south), String(east), String(north), "-ts", String(width), String(height), "-r", "bilinear", "-dstnodata", "-9999", "-of", "GTiff", source, target]);
  if (!fs.existsSync(png) || fs.statSync(png).size < 1_000) {
    await Promise.all([warp(rateGrib, rateRaw), warp(pressureGrib, pressureTif), warp(height500Grib, height500Tif), warp(height1000Grib, height1000Tif)]);
    await Promise.all([
      runWeatherMapCommand("gdal_calc.py", ["-A", rateRaw, "--calc=A*141.732283", "--type=Float32", "--NoDataValue=-9999", "--overwrite", `--outfile=${tif}`]),
      runWeatherMapCommand("gdal_calc.py", ["-A", height500Tif, "-B", height1000Tif, "--calc=A-B", "--type=Float32", "--NoDataValue=-9999", "--overwrite", `--outfile=${thicknessTif}`])
    ]);
    await runWeatherMapCommand("gdaldem", ["color-relief", tif, path.join(__dirname, "scripts", gfsModelProducts.pcpn.colors), png, "-of", "PNG", "-alpha"]);
  }
  if (!fs.existsSync(pressureContours)) await runWeatherMapCommand("gdal_contour", ["-q", "-i", "400", "-a", "pressure", "-f", "GeoJSON", pressureTif, pressureContours]);
  if (!fs.existsSync(thicknessContours)) await runWeatherMapCommand("gdal_contour", ["-q", "-i", "60", "-a", "thickness", "-f", "GeoJSON", thicknessTif, thicknessContours]);
  const pressureFeatures = JSON.parse(fs.readFileSync(pressureContours, "utf8")).features || [];
  const thicknessFeatures = JSON.parse(fs.readFileSync(thicknessContours, "utf8")).features || [];
  const pressurePaths = renderGfsContourPaths(pressureFeatures, project, "pressure", () => `stroke="#171717" stroke-opacity=".86" stroke-width="1.35"`);
  const thicknessPaths = renderGfsContourPaths(thicknessFeatures, project, "thickness", (value) => {
    const near540 = Math.abs(value - 5400) < 1;
    return `stroke="${near540 ? "#d52d36" : value < 5400 ? "#376cc4" : "#c55745"}" stroke-opacity=".88" stroke-width="${near540 ? "2.3" : "1.25"}" stroke-dasharray="${near540 ? "9 4" : "6 5"}"`;
  });
  const overlay = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="${x} ${y} ${right-x} ${bottom-y}">${thicknessPaths}${pressurePaths}</svg>`;
  const runTime = Date.UTC(Number(run.slice(0, 4)), Number(run.slice(4, 6)) - 1, Number(run.slice(6, 8)), Number(run.slice(8, 10)));
  return { dataUri: `data:image/png;base64,${fs.readFileSync(png).toString("base64")}`, overlayDataUri: `data:image/svg+xml;base64,${Buffer.from(overlay).toString("base64")}`, tifPath: tif, x, y, width: right-x, height: bottom-y, runTime, validTime: runTime + forecastHour * 3_600_000 };
}

async function renderHrrrModelField(product, run, forecastHour, selectedRegion, project, cacheStem) {
  const config = hrrrModelProducts[product];
  if (config?.derivedDailySignal) return renderHrrrDailySevereGuidance(product, run, forecastHour, selectedRegion, project, cacheStem);
  if (config?.derivedApparent) return renderHrrrApparentTemperature(run, forecastHour, selectedRegion, project, cacheStem);
  if (config?.derivedWind) return renderHrrrWind(run, forecastHour, selectedRegion, project, cacheStem);
  if (config?.derivedWindDirection) return renderHrrrWindDirection(run, forecastHour, selectedRegion, project, cacheStem);
  if (config?.derivedPrecipType) return renderHrrrPrecipitationType(run, forecastHour, selectedRegion, project, cacheStem);
  if (config?.derivedSevere) return renderHrrrModelSevereParameter(product, run, forecastHour, selectedRegion, project, cacheStem);
  if (config?.derivedExclusive) return renderHrrrExclusiveIndex(product, run, forecastHour, selectedRegion, project, cacheStem);
  if (config?.derivedRunMax) return renderHrrrUh03RunMaximum(run, forecastHour, selectedRegion, project, cacheStem);
  if (config?.combined) {
    const [base, uh] = await Promise.all([
      renderHrrrModelField("refc", run, forecastHour, selectedRegion, project, `${cacheStem}-refc`),
      renderHrrrModelField("uh75", run, forecastHour, selectedRegion, project, `${cacheStem}-uh75`)
    ]);
    return { ...base, overlayDataUri: uh.dataUri, overlayTifPath: uh.tifPath };
  }
  const grib = await getHrrrModelField(product, run, forecastHour);
  const [west, south, east, north] = selectedRegion.bbox, [x, y] = project([west, north]), [right, bottom] = project([east, south]);
  const unitVersion = product === "apcp" ? "-inches20" : product === "prate" ? "-inches" : "";
  const workDir = path.join(dataDir, "generated", "hrrr-model"), stamp = `${run}-f${String(forecastHour).padStart(2, "0")}${unitVersion}`;
  const sourceTif = path.join(workDir, `${cacheStem}-${stamp}-source.tif`), tif = config.calc ? path.join(workDir, `${cacheStem}-${stamp}.tif`) : sourceTif, png = path.join(workDir, `${cacheStem}-${stamp}.png`);
  if (!fs.existsSync(png) || fs.statSync(png).size < 1_000) {
    await runWeatherMapCommand("gdalwarp", ["-overwrite", "-q", "-t_srs", "EPSG:4326", "-te", String(west), String(south), String(east), String(north), "-ts", String(Math.round(right - x)), String(Math.round(bottom - y)), "-r", "bilinear", "-dstnodata", "-9999", "-of", "GTiff", grib, sourceTif]);
    if (config.calc) await runWeatherMapCommand("gdal_calc.py", ["-A", sourceTif, `--calc=${config.calc}`, "--type=Float32", "--NoDataValue=-9999", "--overwrite", `--outfile=${tif}`]);
    await runWeatherMapCommand("gdaldem", ["color-relief", tif, path.join(__dirname, "scripts", config.colors), png, "-of", "PNG", "-alpha"]);
  }
  const runTime = Date.UTC(Number(run.slice(0, 4)), Number(run.slice(4, 6)) - 1, Number(run.slice(6, 8)), Number(run.slice(8, 10)));
  return { dataUri: `data:image/png;base64,${fs.readFileSync(png).toString("base64")}`, tifPath: tif, x, y, width: right - x, height: bottom - y, runTime, validTime: runTime + forecastHour * 3_600_000 };
}

async function renderHrrrWind(run, forecastHour, selectedRegion, project, cacheStem) {
  const [uGrib, vGrib] = await Promise.all([
    getHrrrModelField("u10", run, forecastHour),
    getHrrrModelField("v10", run, forecastHour)
  ]);
  const [west, south, east, north] = selectedRegion.bbox;
  const [x, y] = project([west, north]), [right, bottom] = project([east, south]);
  const workDir = path.join(dataDir, "generated", "hrrr-model");
  const stamp = `${run}-f${String(forecastHour).padStart(2, "0")}-wind-v1`;
  const uTif = path.join(workDir, `${cacheStem}-${stamp}-u.tif`);
  const vTif = path.join(workDir, `${cacheStem}-${stamp}-v.tif`);
  const tif = path.join(workDir, `${cacheStem}-${stamp}-speed.tif`);
  const directionTifPath = path.join(workDir, `${cacheStem}-${stamp}-direction.tif`);
  const png = path.join(workDir, `${cacheStem}-${stamp}.png`);
  if (!fs.existsSync(png) || fs.statSync(png).size < 1_000) {
    const warp = (source, target) => runWeatherMapCommand("gdalwarp", ["-overwrite", "-q", "-t_srs", "EPSG:4326", "-te", String(west), String(south), String(east), String(north), "-ts", String(Math.round(right - x)), String(Math.round(bottom - y)), "-r", "bilinear", "-dstnodata", "-9999", "-of", "GTiff", source, target]);
    await Promise.all([warp(uGrib, uTif), warp(vGrib, vTif)]);
    await Promise.all([
      runWeatherMapCommand("gdal_calc.py", ["-A", uTif, "-B", vTif, "--calc=sqrt(A*A+B*B)*2.236936", "--type=Float32", "--NoDataValue=-9999", "--overwrite", `--outfile=${tif}`]),
      runWeatherMapCommand("gdal_calc.py", ["-A", uTif, "-B", vTif, "--calc=mod(arctan2(-A,-B)*57.29577951308232+360,360)", "--type=Float32", "--NoDataValue=-9999", "--overwrite", `--outfile=${directionTifPath}`])
    ]);
    await runWeatherMapCommand("gdaldem", ["color-relief", tif, path.join(__dirname, "scripts", hrrrModelProducts.wind.colors), png, "-of", "PNG", "-alpha"]);
  }
  const runTime = Date.UTC(Number(run.slice(0, 4)), Number(run.slice(4, 6)) - 1, Number(run.slice(6, 8)), Number(run.slice(8, 10)));
  return { dataUri: `data:image/png;base64,${fs.readFileSync(png).toString("base64")}`, tifPath: tif, directionTifPath, x, y, width: right - x, height: bottom - y, runTime, validTime: runTime + forecastHour * 3_600_000 };
}

