    await runWeatherMapCommand("gdal_calc.py",args);
    await runWeatherMapCommand("gdaldem",["color-relief",tif,path.join(__dirname,"scripts",hrrrModelProducts[product].colors),png,"-of","PNG","-alpha"]);
