async function handleNativeLatestModelImage(request, requestUrl, response) {
  const model = String(requestUrl.searchParams.get("model") || "hrrr").toLowerCase();
  const product = String(requestUrl.searchParams.get("product") || "refc").toLowerCase();
  const requestedHour = Math.max(0, Number(requestUrl.searchParams.get("fh")) || 0);
  try {
    if (model === "hrrr") {
      const catalog = await latestHrrrModelCatalog();
      const run = (catalog.runs || [catalog]).find((entry) => entry.run === catalog.preferredRun) || catalog;
      const hours = run.productForecastHours?.[product] || run.forecastHours || [];
      const forecastHour = hours.includes(requestedHour) ? requestedHour : hours[0];
      if (!Number.isInteger(forecastHour) || !hrrrModelProducts[product] || hrrrModelProducts[product].internal) throw new Error("Requested HRRR product is unavailable");
      const proxy = new URL(requestUrl);
      proxy.pathname = "/api/ops/models/overlay.png";
      proxy.search = "";
      proxy.searchParams.set("source", "hrrr");
      proxy.searchParams.set("run", run.run);
      proxy.searchParams.set("fh", forecastHour);
      proxy.searchParams.set("product", product);
      proxy.searchParams.set("bbox", "-126.5,23,-65.5,51");
      proxy.searchParams.set("width", "2048");
      return handleOpsModelOverlay(proxy, response);
    }
    if (model === "gfs") {
      const catalog = await latestGfsModelCatalog();
      const run = (catalog.runs || [catalog]).find((entry) => entry.run === catalog.preferredRun) || catalog;
      const hours = run.productForecastHours?.[product] || run.forecastHours || [];
      const forecastHour = hours.includes(requestedHour) ? requestedHour : hours[0];
      if (!Number.isInteger(forecastHour) || !gfsModelProducts[product]) throw new Error("Requested GFS product is unavailable");
      const proxy = new URL(requestUrl);
      proxy.pathname = "/api/ops/models/overlay.png";
      proxy.search = "";
      proxy.searchParams.set("source", "gfs");
      proxy.searchParams.set("run", run.run);
      proxy.searchParams.set("fh", forecastHour);
      proxy.searchParams.set("product", product);
      proxy.searchParams.set("bbox", "-126.5,23,-65.5,51");
      proxy.searchParams.set("width", "2048");
      return handleOpsModelOverlay(proxy, response);
    }
    if (model === "ncep") {
      const catalog = await latestNcepModelCatalog();
      const run = (catalog.runs || [catalog]).find((entry) => entry.run === catalog.preferredRun) || (catalog.runs || [catalog])[0];
      const hours = run?.productForecastHours?.[product] || run?.forecastHours || [];
      const forecastHour = hours.includes(requestedHour) ? requestedHour : hours[0];
      if (!run || !Number.isFinite(forecastHour) || !NCEP_OPS_OVERLAY_PRODUCTS.has(product) || !run.products?.[product]) throw new Error("Requested ZNWS WRF product is unavailable");
      const proxy = new URL(requestUrl);
      proxy.pathname = "/api/ops/models/overlay.png";
      proxy.search = "";
      proxy.searchParams.set("source", "ncep");
      proxy.searchParams.set("run", run.run);
      proxy.searchParams.set("fh", forecastHour);
      proxy.searchParams.set("product", product);
      proxy.searchParams.set("bbox", "-126.5,23,-65.5,51");
      proxy.searchParams.set("width", "2048");
      return handleOpsModelOverlay(proxy, response);
    }
    sendJson(response, 400, { error: "Unsupported native model" });
  } catch (error) {
    sendJson(response, 502, { error: "Native model frame unavailable", detail: error.message });
  }
  return true;
}

