function readPublicModelPrewarmStatus() {
  let status = { running: false, queued: 0, processed: 0, failed: 0, current: null, updatedAt: null };
  try {
    const raw = JSON.parse(fs.readFileSync(modelPrewarmStatusFile, "utf8"));
    status = {
      running: Boolean(raw.running), total: Math.max(0, Number(raw.total ?? raw.queued) || 0),
      queued: Math.max(0, Number(raw.queued) || 0), processed: Math.max(0, Number(raw.processed) || 0),
      failed: Math.max(0, Number(raw.failed) || 0), framesPerMinute: Math.max(0, Number(raw.framesPerMinute) || 0),
      current: String(raw.current || "").slice(0, 240) || null, passStartedAt: raw.passStartedAt || null,
      updatedAt: raw.updatedAt || null, hrrrError: raw.hrrrError || null, wrfError: raw.wrfError || null,
      breakdown: {
        ...Object.fromEntries(["sources", "products", "regions"].map((group) => [group, Object.fromEntries(Object.entries(raw.breakdown?.[group] || {}).map(([key, value]) => [String(key).slice(0, 80), Math.max(0, Number(value) || 0)]))])),
        phase: raw.breakdown?.phase === "backfill" ? "backfill" : "latest",
        backfillQueued: Math.max(0, Number(raw.breakdown?.backfillQueued) || 0),
        coverage: { regions: Object.fromEntries(Object.entries(raw.breakdown?.coverage?.regions || {}).map(([key, value]) => [String(key).slice(0, 100), { source: ["ncep","gfs"].includes(value?.source) ? value.source : "hrrr", region: String(value?.region || "national").slice(0, 80), total: Math.max(0, Number(value?.total) || 0), remaining: Math.max(0, Number(value?.remaining) || 0) }])) }
      }
    };
  } catch { /* worker has not published status yet */ }
  try {
    const disk = fs.statfsSync(dataDir), blockSize = Number(disk.bsize || disk.frsize || 0);
    status.storage = { availableBytes: Number(disk.bavail) * blockSize, totalBytes: Number(disk.blocks) * blockSize };
  } catch { status.storage = null; }
  const linkedWrfSectors = loadTemporaryMapRegions({ activeOnly: true }).regions.filter((region) => (region.domains || [region.domain]).some((domain) => ncepForecastDomains.has(domain))).length;
  return { ...status, batchSize: modelPrewarmBatchSize, concurrency: modelPrewarmConcurrency, products: modelPrewarmProducts, regions: hrrrPublicOutlookRegionKeys.size, linkedWrfSectors, gfsRegions: 1 + gfsOnlyPublicOutlookRegionKeys.size, gfsProducts: ["refc", "apcp", "pcpn", "temperature", "cloud", "pwat"], retainedRuns: 3, timeZone: "UTC" };
}

async function handlePublicModelStatus(response) {
  const domains=await Promise.all(["MESO1","MESO2","MESO3"].map(async(domain)=>{
    try{
      const history=await getNcepDomainRunHistory(domain,3);
      const runs=await Promise.all(history.map(async(meta)=>{
        const historicRunId=ncepHistoryRunId(meta);
        if(!historicRunId)return null;
        try{
          const inventory=await getNcepHistoricalRunProducts(domain,historicRunId);
          const products={};
          for(const item of inventory.products||[]){
            if(!products[item.code])products[item.code]={code:item.code,name:item.name||item.code,frames:0,hours:[],latestValidTime:null};
            const entry=products[item.code],hour=Number(item.forecast_minutes??Number(item.forecast_hour)*60)/60;
            entry.frames+=1;
            if(Number.isFinite(hour)&&!entry.hours.includes(hour))entry.hours.push(hour);
            if(item.valid_time&&(!entry.latestValidTime||item.valid_time>entry.latestValidTime))entry.latestValidTime=item.valid_time;
          }
          Object.values(products).forEach((item)=>item.hours.sort((a,b)=>a-b));
          return {
            runId:historicRunId,status:meta.status||inventory.status||"unknown",
            initializationTime:meta.initialization_time||null,generatedAt:meta.generated_at||inventory.generated_at||null,
            spacing:meta.spacing??inventory.spacing??null,physicsPreset:meta.physics_preset||inventory.physics_preset||"OPERATIONAL",productCount:Number(meta.product_count)||(inventory.products||[]).length,
            products:Object.values(products).sort((a,b)=>a.code.localeCompare(b.code)),
            requestedBounds:meta.requested_bounds||inventory.requested_bounds||null,
            gridBounds:meta.grid_bounds||inventory.grid_bounds||null,usableGridBounds:meta.usable_grid_bounds||inventory.usable_grid_bounds||null
          };
        }catch(error){return {runId:historicRunId,status:meta.status||"unavailable",initializationTime:meta.initialization_time||null,generatedAt:meta.generated_at||null,spacing:meta.spacing??null,physicsPreset:meta.physics_preset||"OPERATIONAL",productCount:Number(meta.product_count)||0,products:[],error:error.message};}
      }));
      const validRuns=runs.filter(Boolean);
      return {domain,runs:validRuns,error:null};
    }catch(error){return {domain,runs:[],error:error.message};}
  }));
  if(domains.some((entry)=>!entry.runs.length)){
    try{
      const catalog=await latestNcepModelCatalog(),catalogRuns=catalog.runs||[catalog];
      for(const domainEntry of domains){
        if(domainEntry.runs.length)continue;
        domainEntry.runs=catalogRuns.filter((run)=>run.domain===domainEntry.domain).slice(0,3).map((run)=>{
          const products=Object.entries(run.productForecastHours||{}).filter(([,hours])=>Array.isArray(hours)&&hours.length).map(([key,hours])=>({
            code:key==="refcuh75"?"REFC+UH75":key.toUpperCase(),
            name:run.products?.[key]?.title||key.toUpperCase(),
            frames:hours.length,hours:[...hours],latestValidTime:new Date(Date.parse(run.runTime)+hours.at(-1)*3_600_000).toISOString()
          }));
          return {
            runId:run.run,status:run.status||"publishing",initializationTime:run.runTime||null,generatedAt:run.generatedAt||null,
            spacing:run.spacing??null,physicsPreset:run.physicsPreset||"OPERATIONAL",
            productCount:products.reduce((sum,item)=>sum+item.frames,0),products,
            requestedBounds:run.bounds||null,gridBounds:run.gridBounds||null,usableGridBounds:run.usableGridBounds||null,
            inventorySource:"approval_queue"
          };
        });
        if(domainEntry.runs.length)domainEntry.error=null;
      }
    }catch{/* retain the history result when both catalog paths are unavailable */}
  }
  const recurring=loadTrackedNcepForecastRequests()
    .filter((entry)=>entry.frequency==="hourly"||entry.frequency==="scheduled")
    .filter((entry)=>!entry.scheduleEnd||Date.parse(entry.scheduleEnd)>Date.now()-24*3_600_000)
    .sort((a,b)=>Date.parse(b.submittedAt||0)-Date.parse(a.submittedAt||0));
  const scheduleCandidates=await Promise.all(recurring.map(async(entry)=>{
    let live={
      status:entry.status||"unknown",
      state:entry.state||entry.status||"unknown",
      decision:entry.decision||"",
      nextRunAt:entry.nextRunAt||""
    };
    try{
      live=await getNcepForecastRequestStatus(entry.requestId);
      // Persist terminal/live state so cancelled schedules drop off without
      // relying on a stale tracked status after the next refresh.
      trackNcepForecastRequest({
        ...entry,
        status:live.status,
        state:live.state,
        decision:live.decision||entry.decision||"",
        nextRunAt:live.nextRunAt
      });
    }catch(error){
      live.error=error.message;
      // Upstream cancelled status used to throw before it was a known status;
      // still treat that message as a terminal cancelled lifecycle.
      if(/status:\s*cancelled/i.test(error.message)||/\bcancelled\b/i.test(error.message)){
        live.status="cancelled";
        live.state="cancelled";
      }
    }
    return {
      requestId:entry.requestId,name:entry.name,domain:entry.domain,frequency:entry.frequency,
      status:live.status,state:live.state||live.status,decision:String(live.decision||entry.decision||"").toLowerCase(),
      nextRunAt:live.nextRunAt||null,scheduleStart:entry.scheduleStart||null,
      scheduleEnd:entry.scheduleEnd||null,cadenceHours:Number(entry.cadenceHours||1),
      forecastHours:entry.forecastHours||null,spacing:entry.spacing||null,
      initialization:entry.initialization||null,physicsPreset:entry.physicsPreset||"OPERATIONAL",
      error:live.error||null
    };
  }));
  // Public Model Status shows only active, approved recurring schedules.
  // Completed, cancelled, denied, and failed requests are ops history only.
  const schedules=scheduleCandidates.filter(isActivePublicNcepSchedule);
  const latestGenerated=domains.flatMap((item)=>item.runs).map((run)=>run.generatedAt).filter(Boolean).sort().at(-1)||null;
  let lanes=[],lanesError=null;
  try{lanes=await getNcepActiveRuns();}catch(error){lanesError=error.message;}
  sendJson(response,200,{generatedAt:new Date().toISOString(),latestInventoryUpdate:latestGenerated,refreshSeconds:60,domains,schedules,lanes,lanesError,prewarm:readPublicModelPrewarmStatus(),scheduler:{concurrency:1,priority:["MESO1","MESO2","MESO3"]}});
  return true;
}

async function handlePublicNcepModelImage(request,requestUrl,response) {
  const betaWebp=requestUrl.pathname.endsWith(".webp");
  const run=String(requestUrl.searchParams.get("run")||""),forecastHour=Number(requestUrl.searchParams.get("fh")),region=String(requestUrl.searchParams.get("region")||""),product=String(requestUrl.searchParams.get("product")||"refc");
  let requestedTimeZone="UTC";const candidate=String(requestUrl.searchParams.get("tz")||"UTC").slice(0,80);
  try{new Intl.DateTimeFormat("en-US",{timeZone:candidate}).format();requestedTimeZone=candidate;}catch{/* UTC */}
  let catalog;
  try{catalog=await latestNcepModelCatalog();}catch(error){sendJson(response,502,{error:"NCEP model run unavailable",detail:error.message});return true;}
  const selectedRun=(catalog.runs||[catalog]).find((entry)=>entry.run===run);
  const availableProductHours=selectedRun?.productForecastHours?.[product]||selectedRun?.forecastHours||[];
  if(!selectedRun||!["zasSevere","zasTornado","zasWind","zasConfidence","zasStormMode","zasFlood","zasFloodV2","refc","ref1km","refcuh75","uh03","runuh03","mucape","mucin","sbcape","sbcin","srh01","srh03","bs06","lightning","maxuvv","maxdvv","temperature","dewpoint","humidity","wind","winddir","gust","pressure","visibility","cloud","ceiling","prate","apcp","preciptype","pwat","snowwe","fzra","smoke"].includes(product)||!selectedRun.products?.[product]||!Number.isFinite(forecastHour)||!availableProductHours.includes(forecastHour)||!Object.hasOwn(publicOutlookRegions,region)){
    sendJson(response,400,{error:"Invalid NCEP model frame"});return true;
  }
  const modelRequest={run,forecastHour,product,inventoryKey:selectedRun.inventoryKey},modelCacheKey=`-${run}-f${String(forecastHour).padStart(2,"0")}${!region?"-nocities":""}`,timeZoneCacheKey=`-${requestedTimeZone.replace(/[^a-z0-9_-]/gi,"_").slice(0,50)}`,mapProduct=`ncep-model-${product}-${product==="wind"?"v24":product==="smoke"?"v26":"v25"}`;
  const cacheName=`wpc-maps-${publicWpcMapRenderVersion}-${mapProduct}${region?`-${region}`:""}${modelCacheKey}${timeZoneCacheKey}.svg`,cachePath=path.join(publicOutlookCacheDir,cacheName);
  try{
    if(!fs.existsSync(cachePath)) await generatePublicWpcMapImage(mapProduct,1,region,"",requestedTimeZone,modelRequest);
    if(betaWebp)await streamPublicModelWebp(response,cachePath,request);
    else streamPublicOutlookImage(response,cachePath,true,request);
  }catch(error){
    console.warn("[public-ncep-model] render failed",error.message);
    response.writeHead(502,{"Content-Type":"image/svg+xml; charset=utf-8","Cache-Control":"no-store"});
    response.end(`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="300"><rect width="100%" height="100%" fill="#111210"/><text x="40" y="150" fill="white" font-family="sans-serif" font-size="24">NCEP model frame is temporarily unavailable.</text></svg>`);
  }
  return true;
}

/** Full ZNWS-WRF product set allowed on the Ops map overlay (matches public models page). */
const NCEP_OPS_OVERLAY_PRODUCTS = new Set([
  "zasSevere", "zasTornado", "zasWind", "zasConfidence", "zasStormMode", "zasFlood", "zasFloodV2",
  "refc", "ref1km", "refcuh75", "uh03", "runuh03", "mucape", "mucin", "sbcape", "sbcin",
  "srh01", "srh03", "bs06", "lightning", "maxuvv", "maxdvv",
  "temperature", "dewpoint", "humidity", "wind", "winddir", "gust", "pressure",
  "visibility", "cloud", "ceiling", "prate", "apcp", "preciptype", "pwat", "snowwe", "fzra", "smoke"
]);

/**
 * MapLibre image sources interpolate the texture in Web Mercator between the four
 * lon/lat corners. Equirectangular (EPSG:4326) model plates therefore look shifted
 * N/S on CONUS-scale domains. Reproject the colored PNG so rows follow mercator Y.
 */
async function reprojectOpsOverlayPngToWebMercator(pngBuffer, bboxLonLat, width, height) {
  const [west, south, east, north] = bboxLonLat.map(Number);
  const [minX, minY] = webMercatorPoint(west, south);
  const [maxX, maxY] = webMercatorPoint(east, north);
  if (![minX, minY, maxX, maxY].every(Number.isFinite) || maxX <= minX || maxY <= minY) {
    throw new Error("Invalid mercator bounds for ops overlay");
  }
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "ops-overlay-merc-"));
  try {
    const srcPng = path.join(tmpDir, "src.png");
    const srcTif = path.join(tmpDir, "src.tif");
    // This GDAL build cannot write PNG via gdalwarp — warp to GeoTIFF, then translate.
    const mercTif = path.join(tmpDir, "merc.tif");
    const outPng = path.join(tmpDir, "out.png");
    fs.writeFileSync(srcPng, pngBuffer);
    // Stamp the equirectangular plate with its lon/lat envelope, then warp to 3857.
    await runWeatherMapCommand("gdal_translate", [
      "-q", "-of", "GTiff",
      "-a_srs", "EPSG:4326",
      "-a_ullr", String(west), String(north), String(east), String(south),
      srcPng, srcTif
    ]);
    await runWeatherMapCommand("gdalwarp", [
      "-overwrite", "-q",
      "-t_srs", "EPSG:3857",
      "-te", String(minX), String(minY), String(maxX), String(maxY),
      "-te_srs", "EPSG:3857",
      "-ts", String(Math.max(8, Math.round(width))), String(Math.max(8, Math.round(height))),
      "-r", "bilinear",
      "-dstalpha",
      "-of", "GTiff",
      srcTif, mercTif
    ]);
    await runWeatherMapCommand("gdal_translate", [
      "-q", "-of", "PNG",
      "-co", "WORLDFILE=NO",
      mercTif, outPng
    ]);
    const out = fs.readFileSync(outPng);
    if (!out || out.length < 200) throw new Error("Empty mercator overlay PNG");
    return out;
  } finally {
    try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch { /* ignore */ }
  }
}

async function handleOpsModelOverlay(requestUrl, response) {
  const requestedSource = requestUrl.searchParams.get("source");
  const source = requestedSource === "ncep" ? "ncep" : requestedSource === "gfs" ? "gfs" : "hrrr";
  const run = String(requestUrl.searchParams.get("run") || "");
  const forecastHour = Number(requestUrl.searchParams.get("fh"));
  const product = String(requestUrl.searchParams.get("product") || "refc");
  const bbox = String(requestUrl.searchParams.get("bbox") || "").split(",").map(Number);
  if (bbox.length !== 4 || !bbox.every(Number.isFinite) || bbox[0] >= bbox[2] || bbox[1] >= bbox[3] || bbox[0] < -180 || bbox[2] > 180 || bbox[1] < -85 || bbox[3] > 85 || !Number.isFinite(forecastHour)) {
    sendJson(response, 400, { error: "Invalid model overlay bounds" });
    return true;
  }
  try {
    const catalog = source === "ncep" ? await latestNcepModelCatalog() : source === "gfs" ? await latestGfsModelCatalog() : await latestHrrrModelCatalog();
    const selectedRun = (catalog.runs || [catalog]).find((entry) => entry.run === run);
    const hours = selectedRun?.productForecastHours?.[product] || selectedRun?.forecastHours || [];
    // HRRR rejects internal-only product keys. ZNWS-WRF uses its own product set
    // (uh03/runuh03/sbcape/etc.) which may be marked internal on the HRRR table.
    const productOk = source === "ncep"
      ? NCEP_OPS_OVERLAY_PRODUCTS.has(product) && Boolean(selectedRun?.products?.[product])
      : source === "gfs"
        ? Boolean(gfsModelProducts[product])
        : Boolean(hrrrModelProducts[product] && !hrrrModelProducts[product].internal);
    if (!selectedRun || !hours.includes(forecastHour) || !productOk) {
      sendJson(response, 400, { error: "Invalid or unavailable model overlay frame" });
      return true;
    }
    // Render at map-pixel density for the requested bbox. Default 2048 (was 1024);
    // client may request up to 4096 when zoomed so detail survives pan/zoom.
    const [minX, minY] = webMercatorPoint(bbox[0], bbox[1]);
    const [maxX, maxY] = webMercatorPoint(bbox[2], bbox[3]);
    const aspect = Math.max(0.15, (maxY - minY) / Math.max(1e-6, maxX - minX));
    let width = Math.max(512, Math.min(4096, Math.round(Number(requestUrl.searchParams.get("width")) || 2048)));
    let height = Math.max(256, Math.round(width * aspect));
    if (height > 4096) {
      height = 4096;
      width = Math.max(256, Math.round(height / aspect));
    }
    // Soft cap ~12 MP so zoomed-in dual-pane renders stay responsive.
    const maxPixels = 12_000_000;
    if (width * height > maxPixels) {
      const scale = Math.sqrt(maxPixels / (width * height));
      width = Math.max(256, Math.round(width * scale));
      height = Math.max(256, Math.round(height * scale));
    }
    const project = webMercatorMapProjection(bbox, width, height, 0);
    const component = requestUrl.searchParams.get("component") === "overlay" ? "overlay" : "base";
    const inventoryKey = source === "ncep" && selectedRun.inventoryKey ? `-i${selectedRun.inventoryKey}` : "";
    // smoke-v3: repaired Lambert georef for ZNWS-WRF SMOKE_SFC (was ~11 km south).
    const overlayRev = source === "ncep" && product === "smoke" ? "v3" : "v2";
    const cacheStem = `ops-overlay-${source}-${product}-${run}-f${String(forecastHour).padStart(2, "0")}-w${width}-${bbox.map((value) => value.toFixed(2).replace("-", "m").replace(".", "p")).join("-")}${inventoryKey}`;
    // Web Mercator-aligned plate for MapLibre image sources.
    const mercCacheDir = path.join(dataDir, "generated", "ops-model-overlay");
    fs.mkdirSync(mercCacheDir, { recursive: true });
    const mercCachePath = path.join(mercCacheDir, `${cacheStem}-${component}-3857-${overlayRev}.png`);
    let png;
    if (fs.existsSync(mercCachePath) && fs.statSync(mercCachePath).size > 200) {
      png = fs.readFileSync(mercCachePath);
    } else {
      const raster = source === "ncep"
        ? await renderNcepModelField(product, run, forecastHour, { bbox }, project, cacheStem)
        : source === "gfs"
          ? await renderGfsModelField(product, run, forecastHour, { bbox }, project, cacheStem)
          : await renderHrrrModelField(product, run, forecastHour, { bbox }, project, cacheStem);
      const requestedDataUri = component === "overlay" ? raster.overlayDataUri : raster.dataUri;
      if (!requestedDataUri) {
        sendJson(response, 404, { error: "Model overlay component unavailable" });
        return true;
      }
      const match = /^data:image\/png;base64,([A-Za-z0-9+/=]+)$/.exec(requestedDataUri);
      if (!match) throw new Error("Model renderer did not return a PNG raster");
      const equirectPng = Buffer.from(match[1], "base64");
      png = await reprojectOpsOverlayPngToWebMercator(equirectPng, bbox, width, height);
      try { fs.writeFileSync(mercCachePath, png); } catch { /* cache is best-effort */ }
    }
    response.writeHead(200, {
      "Content-Type": "image/png",
      "Content-Length": png.length,
      "Cache-Control": "private, max-age=120",
      "X-Ops-Overlay-Crs": "EPSG:3857"
    });
    response.end(png);
  } catch (error) {
    console.warn("[ops-model-overlay] render failed", error.message);
    sendJson(response, 502, { error: "Model overlay unavailable", detail: error.message });
  }
  return true;
}

async function handlePublicHrrrModelImage(request, requestUrl, response) {
  // Active MESO zones can be created or expire without restarting the public
  // service. Refresh the render-region registry before validating the request.
  syncTemporaryMapRegions();
  const betaWebp = requestUrl.pathname.endsWith(".webp");
  const run = String(requestUrl.searchParams.get("run") || ""), forecastHour = Number(requestUrl.searchParams.get("fh"));
  const region = String(requestUrl.searchParams.get("region") || ""), product = String(requestUrl.searchParams.get("product") || "refc");
  let requestedTimeZone = "UTC";
  const candidate = String(requestUrl.searchParams.get("tz") || "UTC").slice(0, 80);
  try { new Intl.DateTimeFormat("en-US", { timeZone: candidate }).format(); requestedTimeZone = candidate; } catch { requestedTimeZone = "UTC"; }
  if (!/^\d{10}$/.test(run) || !Number.isInteger(forecastHour) || forecastHour < 0 || forecastHour > 48 || !hrrrModelProducts[product] || hrrrModelProducts[product].internal || forecastHour < (hrrrModelProducts[product].minimumHour || 0) || !Object.hasOwn(publicOutlookRegions, region)) {
    sendJson(response, 400, { error: "Invalid HRRR model frame" });
    return true;
  }
  const antecedentKey = product === "zasFloodV2" ? new Date().toISOString().slice(0,13).replace(/[-T]/g,"") : "";
  const modelRequest = { run, forecastHour, product, antecedentKey }, modelCacheKey = `-${run}-f${String(forecastHour).padStart(2, "0")}${!region || gfsOnlyPublicOutlookRegionKeys.has(region) ? "-nocities" : ""}${antecedentKey ? `-a${antecedentKey}` : ""}`;
  const timeZoneCacheKey = `-${requestedTimeZone.replace(/[^a-z0-9_-]/gi, "_").slice(0, 50)}`;
  const mapProduct = `hrrr-model-${product}`, cacheName = `wpc-maps-${publicWpcMapRenderVersion}-${mapProduct}${region ? `-${region}` : ""}${modelCacheKey}${timeZoneCacheKey}.svg`;
  const cachePath = path.join(publicOutlookCacheDir, cacheName);
  try {
    if (!fs.existsSync(cachePath) && hrrrModelProducts[product]?.derivedDailySignal) {
      const generation = generatePublicWpcMapImage(mapProduct, 1, region, "", requestedTimeZone, modelRequest).catch((error) => console.warn("[public-hrrr-daily] background render failed", error.message));
      const productRegionPrefix = `-${mapProduct}${region ? `-${region}` : ""}-`;
      const timeZoneSuffix = `${timeZoneCacheKey}.svg`;
      const fallback = fs.readdirSync(publicOutlookCacheDir)
        .filter((name) => {
          if (!name.startsWith("wpc-maps-") || !name.endsWith(timeZoneSuffix)) return false;
          const marker = name.indexOf(productRegionPrefix);
          return marker >= 0 && /^\d{10}-f\d+/.test(name.slice(marker + productRegionPrefix.length));
        })
        .map((name) => ({ path: path.join(publicOutlookCacheDir, name), mtime: fs.statSync(path.join(publicOutlookCacheDir, name)).mtimeMs }))
        .sort((a, b) => b.mtime - a.mtime)[0];
      if (fallback) {
        if (betaWebp) await streamPublicModelWebp(response, fallback.path, request);
        else streamPublicOutlookImage(response, fallback.path, true, request);
        return true;
      }
      await generation;
    } else if (!fs.existsSync(cachePath)) {
      await generatePublicWpcMapImage(mapProduct, 1, region, "", requestedTimeZone, modelRequest);
    }
    if (!fs.existsSync(cachePath)) throw new Error("HRRR daily guidance is still generating");
    if (betaWebp) await streamPublicModelWebp(response, cachePath, request);
    else streamPublicOutlookImage(response, cachePath, true, request);
  } catch (error) {
    console.warn("[public-hrrr-model] render failed", error.message);
    response.writeHead(502, { "Content-Type": "image/svg+xml; charset=utf-8", "Cache-Control": "no-store" });
    response.end(`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="300"><rect width="100%" height="100%" fill="#111210"/><text x="40" y="150" fill="white" font-family="sans-serif" font-size="24">HRRR model frame is temporarily unavailable.</text></svg>`);
  }
  return true;
}

async function handlePublicGfsModelImage(request, requestUrl, response) {
  const betaWebp = requestUrl.pathname.endsWith(".webp"), run = String(requestUrl.searchParams.get("run") || ""), forecastHour = Number(requestUrl.searchParams.get("fh")), product = String(requestUrl.searchParams.get("product") || "refc"), region = String(requestUrl.searchParams.get("region") || "");
  let requestedTimeZone = "UTC"; const candidate = String(requestUrl.searchParams.get("tz") || "UTC").slice(0, 80);
  try { new Intl.DateTimeFormat("en-US", { timeZone: candidate }).format(); requestedTimeZone = candidate; } catch { /* UTC */ }
  let catalog;
  try { catalog = await latestGfsModelCatalog(); } catch (error) { sendJson(response, 502, { error: "GFS model run unavailable", detail: error.message }); return true; }
  const selectedRun = (catalog.runs || [catalog]).find((entry) => entry.run === run);
  const productHours = selectedRun?.productForecastHours?.[product] || [];
  if (!selectedRun || !gfsModelProducts[product] || !productHours.includes(forecastHour) || forecastHour < (gfsModelProducts[product].minimumHour || 0) || !(region === "" || gfsOnlyPublicOutlookRegionKeys.has(region)) || (product === "temperature" && region !== "" && !gfsUsPublicOutlookRegionKeys.has(region))) { sendJson(response, 400, { error: "Invalid GFS model frame" }); return true; }
  const modelRequest = { run, forecastHour, product }, mapProduct = `gfs-model-${product}`, timeZoneCacheKey = `-${requestedTimeZone.replace(/[^a-z0-9_-]/gi, "_").slice(0, 50)}`;
  const cachePath = path.join(publicOutlookCacheDir, `wpc-maps-${publicWpcMapRenderVersion}-${mapProduct}${region ? `-${region}` : ""}-${run}-f${String(forecastHour).padStart(2, "0")}-edge2edge${product === "refc" ? "-smooth3" : ""}${region === "north-atlantic" ? "-atl4" : ""}-nocities${timeZoneCacheKey}.svg`);
  try {
    if (!fs.existsSync(cachePath)) await generatePublicWpcMapImage(mapProduct, 1, region, "", requestedTimeZone, modelRequest);
    if (betaWebp) await streamPublicModelWebp(response, cachePath, request); else streamPublicOutlookImage(response, cachePath, true, request);
  } catch (error) {
    console.warn("[public-gfs-model] render failed", error.message);
    response.writeHead(502, { "Content-Type": "image/svg+xml; charset=utf-8", "Cache-Control": "no-store" });
    response.end(`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="300"><rect width="100%" height="100%" fill="#111210"/><text x="40" y="150" fill="white" font-family="sans-serif" font-size="24">GFS model frame is temporarily unavailable.</text></svg>`);
  }
  return true;
}

async function handlePublicHafsModelImage(model,request,requestUrl,response){
  const run=String(requestUrl.searchParams.get("run")||""),forecastHour=Number(requestUrl.searchParams.get("fh")),product=String(requestUrl.searchParams.get("product")||"refc"),region=String(requestUrl.searchParams.get("region")||""),domain=String(requestUrl.searchParams.get("domain")||"storm");
  let catalog;try{catalog=await latestHafsModelCatalog(model);}catch(error){sendJson(response,502,{error:`${model.toUpperCase()} model run unavailable`,detail:error.message});return true;}
  const selectedRun=(catalog.runs||[catalog]).find((entry)=>entry.run===run&&entry.region===region),productHours=selectedRun?.productForecastHours?.[product]||[];
  if(!selectedRun||!hafsModelProducts[product]||!productHours.includes(forecastHour)||!["storm","parent"].includes(domain)){sendJson(response,400,{error:"Invalid HAFS model frame"});return true;}
  // Temporary mesoscale-region refreshes intentionally prune dynamic map
  // regions. Re-register this storm from the validated catalog immediately
  // before rendering so those refreshes cannot invalidate a HAFS frame.
  const trackPoints=selectedRun.trackPoints||[],trackPoint=trackPoints.find((point)=>point.hour===forecastHour)||trackPoints.reduce((best,point)=>!best||Math.abs(point.hour-forecastHour)<Math.abs(best.hour-forecastHour)?point:best,null);
  const fallbackCenter={lon:(selectedRun.bbox[0]+selectedRun.bbox[2])/2,lat:(selectedRun.bbox[1]+selectedRun.bbox[3])/2},center=trackPoint||fallbackCenter;
  let bbox;
  if(product==="apcp"&&trackPoints.length){
    // Accumulated precipitation must retain a stationary geographic frame;
    // a moving camera makes a growing run total difficult to interpret.
    const lons=trackPoints.map((point)=>point.lon),lats=trackPoints.map((point)=>point.lat),pad=domain==="parent"?12:6;
    bbox=[Math.max(-180,Math.min(...lons)-pad),Math.max(-75,Math.min(...lats)-pad),Math.min(180,Math.max(...lons)+pad),Math.min(80,Math.max(...lats)+pad)];
  }else{
    // Preserve most of the square storm nest while cropping enough of its
    // north/south edges to fit the widescreen plate with narrow side margins.
    const halfLongitude=domain==="parent"?30:10;
    // Match the parent crop to the 1400×654 map viewport at the storm's
    // latitude so frame expansion does not reveal empty grid edges.
    const halfLatitude=domain==="parent"?Math.max(9,Math.min(13,halfLongitude*Math.cos(center.lat*Math.PI/180)/(1400/654))):5;
    bbox=[Math.max(-180,center.lon-halfLongitude),Math.max(-75,center.lat-halfLatitude),Math.min(180,center.lon+halfLongitude),Math.min(80,center.lat+halfLatitude)];
  }
  publicOutlookRegions[region]={label:selectedRun.stormName,bbox,hafsOnly:true,stormId:selectedRun.stormId,model};
  // NOAA can publish the atmospheric grids before storm_info or the tracker
  // file. Include the resolved name and moving-frame bounds in the cache key so
  // an early "Invest"/fallback-location plate cannot remain after metadata
  // arrives for the same run and forecast hour.
  const metadataRevision=crypto.createHash("sha1").update(JSON.stringify({name:selectedRun.stormName,bbox,center:trackPoint||null})).digest("hex").slice(0,10);
  const modelRequest={model,stormId:selectedRun.stormId,domain,run,forecastHour,product,bbox,regionLabel:selectedRun.stormName,stormCenter:trackPoint||null,metadataRevision},mapProduct=`hafs-model-${product}`;
  try{const cachePath=await generatePublicWpcMapImage(mapProduct,1,region,"","UTC",modelRequest);await streamPublicModelWebp(response,cachePath,request);}
  catch(error){console.warn("[public-hafs-model] render failed",error.message);response.writeHead(502,{"Content-Type":"image/svg+xml; charset=utf-8","Cache-Control":"no-store"});response.end(`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="300"><rect width="100%" height="100%" fill="#111210"/><text x="40" y="150" fill="white" font-family="sans-serif" font-size="24">${model.toUpperCase()} storm frame is temporarily unavailable.</text></svg>`);}
  return true;
}

function geometryBoundingBox(geometry) {
  const bounds = [Infinity, Infinity, -Infinity, -Infinity];
  const walk = (value) => {
    if (!Array.isArray(value)) return;
    if (typeof value[0] === "number" && typeof value[1] === "number") {
      bounds[0] = Math.min(bounds[0], value[0]); bounds[1] = Math.min(bounds[1], value[1]);
      bounds[2] = Math.max(bounds[2], value[0]); bounds[3] = Math.max(bounds[3], value[1]);
      return;
    }
    value.forEach(walk);
  };
  walk(geometry?.coordinates);
  return bounds.every(Number.isFinite) ? bounds : null;
}

function renderPublicAlertGraphicSvg(store, requestedWfo = "", includeRadar = false, includeSatellite = false) {
  const width = 1400, mapTop = 122, mapBottom = 900;
  const wfo = String(requestedWfo || "").replace(/^K/i, "").toUpperCase();
  const selectedCwa = /^[A-Z0-9]{3}$/.test(wfo) ? loadPublicCwaGeometry().find((feature) => String(feature.properties?.CWA || feature.properties?.WFO || "").toUpperCase() === wfo) : null;
  const mapWidth = selectedCwa ? width - 330 : width;
  const padding = selectedCwa ? 14 : 38;
  const cwaBounds = selectedCwa ? geometryBoundingBox(selectedCwa.geometry) : null;
  // Keep neighboring county context visible, but frame local WFO maps tightly
  // enough that the selected office and its active products remain prominent.
  const bbox = cwaBounds ? [cwaBounds[0] - 2.4, cwaBounds[1] - 1.35, cwaBounds[2] + 2.4, cwaBounds[3] + 1.35] : [-126.5, 23, -65.5, 51];
  const mapProject = outlookProjection(bbox, mapWidth, mapBottom - mapTop, padding);
  const project = (point) => { const [x, y] = mapProject(point); return [x, y + mapTop]; };
  const states = loadOutlookStateGeometry();
  const statePaths = states.map((f) => outlookGeometryPath(f.geometry, project)).filter(Boolean).map((d) => `<path d="${d}"/>`).join("");
  const surroundingCountries = renderSurroundingCountries(bbox, project);
  const radarTiles = includeRadar ? renderIemRadarTiles(bbox, project) : "";
  const satelliteTiles = includeSatellite && !selectedCwa ? renderNesdisGeoColorTiles(bbox, project) : "";
  // On a local map, retain every CWA touching the cropped view. This gives a
  // visitor a seamless way to click into a neighboring office without going
  // back to the national map first.
  const wfoAreaPaths = loadPublicCwaGeometry().filter((feature) => {
    // National graphics keep invisible CWA hit areas for click-through WFO
    // navigation; visible WFO outlines remain disabled by the map styles.
    if (!selectedCwa) return true;
    const bounds = geometryBoundingBox(feature.geometry);
    return bounds && bounds[2] >= bbox[0] && bounds[0] <= bbox[2] && bounds[3] >= bbox[1] && bounds[1] <= bbox[3];
  }).map((feature) => {
    const p = feature.properties || {};
    const code = String(p.CWA || p.WFO || "").toUpperCase();
    const d = outlookGeometryPath(feature.geometry, project);
    if (!/^[A-Z0-9]{3}$/.test(code) || !d) return "";
    const selectedClass = selectedCwa && code === wfo ? " selected" : "";
    return { boundary: `<path class="wfo-boundary${selectedClass}" d="${d}"/>`, hit: `<path class="wfo-hit" data-wfo="${code}" d="${d}"/>` };
  }).filter(Boolean);
  const boundaryContrastStyles = selectedCwa
    ? `<style>.county path{stroke:#35566b;stroke-opacity:.98;stroke-width:1.25}.state-boundaries path{stroke:#172f40;stroke-opacity:1;stroke-width:3.15}.wfo-boundary{display:none}.wfo-hit:hover{fill:#20d6ff;fill-opacity:.12}</style>`
    : `<style>.wfo-boundary{display:none}.wfo-hit:hover{fill:#1769aa;fill-opacity:.08}.state-boundaries path{stroke:#000000;stroke-opacity:1;stroke-width:2.5}</style>`;
  const areaFillStyle = `<style>.alert-shape.area,.alert-shape.area.local-area{fill-opacity:1;stroke:none;stroke-width:0}.alert-shape.area:hover{fill-opacity:1;stroke:none;stroke-width:0}</style>`;
  const wfoBoundaries = areaFillStyle + boundaryContrastStyles + wfoAreaPaths.map((item) => item.boundary).join("");
  const wfoHits = wfoAreaPaths.map((item) => item.hit).join("");
  // County boundaries are useful local reference detail, but are intentionally
  // omitted from the national page to keep that graphic light and uncluttered.
  const countyLines = renderAlertCountyLines(bbox, project);
  // A local page is a geographic view, not an issuer filter: neighboring WFO
  // products remain visible whenever their areas overlap the zoomed CWA map.
  const features = (publicAlertsGeoJson(store).features || []).filter((feature) => {
    if (!selectedCwa) return true;
    const bounds = geometryBoundingBox(feature.geometry);
    return bounds && bounds[2] >= bbox[0] && bounds[0] <= bbox[2] && bounds[3] >= bbox[1] && bounds[1] <= bbox[3];
  }).sort((a, b) => Number(b.properties?.priority || 200) - Number(a.properties?.priority || 200));
  const productInfo = new Map();
  const zoneShapes = [];
  const warningShapes = [];
  features.forEach((feature) => {
    const p = feature.properties || {};
    const d = outlookGeometryPath(feature.geometry, project);
    if (!d) return;
    const productKey = String(p.productId || p.id || "");
    if (!productKey) return;
    if (!productInfo.has(productKey)) productInfo.set(productKey, { id: String(p.id || ""), productId: productKey, productName: String(p.productName || p.product || "Alert"), watchNumber: String(p.etnLabel || p.etn || ""), kind: String(p.kind || ""), color: String(p.color || "#f2b84b"), wfo: String(p.wfo || ""), expiresAt: String(p.expiresAt || ""), priority: zoneProductDisplayPriority(p.product, p.priority) });
    const warning = p.geometryTier
      ? p.geometryTier === "polygon"
      : p.kind === "warning" || usesPublicIssuedPolygon({ product: p.product });
    const color = escapeSvgText(p.color || "#f2b84b");
    const interactive = selectedCwa ? ` data-alert-id="${escapeSvgText(productKey)}"` : "";
    // Alert polygons and zones remain visually steady on local WFO maps;
    // operators use the legend for details rather than shape hover effects.
    const noHover = selectedCwa ? " no-hover" : "";
    const shape = warning
      ? `<path class="alert-shape warning${selectedCwa ? "" : " passive"}${noHover}"${interactive} d="${d}" fill="${color}" stroke="none" style="fill-opacity:1;stroke:none;stroke-width:0"/>`
      : `<path class="alert-shape area${selectedCwa ? " local-area" : " passive"}${noHover}"${interactive} d="${d}" fill="${color}" stroke="${color}" style="fill-opacity:1;stroke:${color};stroke-width:1.35;stroke-opacity:1;stroke-linejoin:round;paint-order:stroke fill"/>`;
    (warning ? warningShapes : zoneShapes).push(shape);
  });
  const cityLabels = renderOutlookCityLabels(bbox, project, selectedCwa
    ? { maximum: 30, minimumSpacing: 54 }
    : { maximum: 32, minimumSpacing: 82 });
  const products = [...productInfo.values()];
  // A watch can span several WFOs or be re-issued as multiple geometry
  // features. The legend describes product types once, not every feature.
  const legendGroups = new Map();
  products.forEach((product) => {
    const key = `${product.productName}:${product.color}`;
    if (!legendGroups.has(key)) legendGroups.set(key, { ...product, productIds: [] });
    const group = legendGroups.get(key);
    group.priority = Math.min(group.priority, product.priority);
    group.productIds.push(product.productId);
  });
  const legendProducts = [...legendGroups.values()]
    .sort((a, b) => a.priority - b.priority || a.productName.localeCompare(b.productName));
  const legendColumns = selectedCwa ? 1 : 4;
  const legendRowHeight = selectedCwa ? 32 : 35;
  const legendRowCount = Math.max(1, Math.ceil(legendProducts.length / legendColumns));
  const panelMargin = 14;
  const panelWidth = selectedCwa ? width - mapWidth : width - panelMargin * 2;
  const panelHeight = selectedCwa ? Math.max(mapBottom - mapTop,62 + legendRowCount * legendRowHeight) : 62 + legendRowCount * legendRowHeight;
  const lx = selectedCwa ? mapWidth : panelMargin;
  const ly = selectedCwa ? mapTop : mapBottom + panelMargin;
  const height = selectedCwa ? Math.max(mapBottom,ly + panelHeight) : ly + panelHeight + panelMargin;
  const legendColumnWidth = (panelWidth - 36) / legendColumns;
  const legendRows = legendProducts.length ? legendProducts.map((p, index) => {
    // Legend rows represent a product type, which can contain several active
    // alerts. Keep the individual ID on map shapes and group legend details by
    // product name so every matching product text is available.
    const interactive = ` data-alert-product="${escapeSvgText(p.productName)}" data-alert-ids="${escapeSvgText(JSON.stringify(p.productIds))}"`;
    const column = index % legendColumns;
    const row = Math.floor(index / legendColumns);
    const itemX = lx + 18 + column * legendColumnWidth;
    const itemY = ly + 48 + row * legendRowHeight;
    return `<g${interactive} class="legend-row" role="button" tabindex="0" aria-label="Read all ${escapeSvgText(p.productName)} products"><rect x="${itemX}" y="${itemY}" width="16" height="16" rx="3" fill="${escapeSvgText(p.color)}"/><text x="${itemX + 28}" y="${itemY + 13}">${escapeSvgText(p.productName)}</text></g>`;
  }).join("") : `<text x="${lx + 18}" y="${ly + 61}" class="legend-text">No active ZWS products</text>`;
  const updated = store.updatedAt ? new Date(store.updatedAt).toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit", timeZoneName: "short" }) : "Awaiting products";
  const mapTitle = selectedCwa ? `WFO ${wfo} ACTIVE WEATHER` : "ACTIVE WEATHER ALERTS";
  const mapSubtitle = selectedCwa ? `${selectedCwa.properties?.CITYSTATE || wfo} · Latest ZASNet watches and warnings · Updated ${updated}` : `Latest ZASNet watches and warnings · Updated ${updated}`;
  // Round ZNWS seal (znws-map-mark.png from ZNWS.png). Full seal embed was ~2.2MB base64.
  return `<?xml version="1.0" encoding="UTF-8"?><svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeSvgText(mapTitle)}"><defs><clipPath id="mapClip"><rect x="0" y="${mapTop}" width="${width}" height="${mapBottom - mapTop}"/></clipPath><linearGradient id="alertOcean" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#176f91"/><stop offset="55%" stop-color="#0f607f"/><stop offset="100%" stop-color="#0a4f6e"/></linearGradient><style>.country path{fill:#36404a;stroke:#050709;stroke-width:1.1}.country text{fill:#a9c7d2;font:700 18px Arial,sans-serif;letter-spacing:2px;text-anchor:middle;pointer-events:none}.satellite{opacity:.72;pointer-events:none}.radar{opacity:1;pointer-events:none}.alert-shape{cursor:pointer;stroke-width:2.1;vector-effect:non-scaling-stroke}.alert-shape.passive{cursor:default;pointer-events:none}.alert-shape.area{fill-opacity:.54;stroke-opacity:.92}.alert-shape.area.local-area{fill-opacity:1}.alert-shape.area.passive{stroke:none;stroke-width:0}.alert-shape.warning{fill-opacity:.19;stroke-width:3.2;stroke-opacity:1}.alert-shape:hover{fill-opacity:.72;stroke:#fff;stroke-width:3.6}.wfo-boundary{fill:none;stroke:#9bb4c2;stroke-opacity:.7;stroke-width:1.7;vector-effect:non-scaling-stroke;pointer-events:none}.wfo-boundary.selected{stroke:#8ed7ff;stroke-opacity:1;stroke-width:3.4}.wfo-hit{fill:#000;fill-opacity:.001;stroke:none;cursor:pointer;pointer-events:all}.wfo-hit:hover{fill:#8ed7ff;fill-opacity:.10}.county path{fill:none;stroke:#6f8798;stroke-opacity:.72;stroke-width:.85;vector-effect:non-scaling-stroke;pointer-events:none}.state-boundaries path{fill:none;stroke:#16324a;stroke-opacity:.96;stroke-width:2.35;vector-effect:non-scaling-stroke;pointer-events:none}.city{pointer-events:none}.city circle{fill:#f7fbff;stroke:#12202a;stroke-width:1.5}.city text{fill:#f7fbff;font:600 14px Arial,sans-serif;paint-order:stroke;stroke:#09131b;stroke-width:3px;stroke-linejoin:round}.legend-row{cursor:pointer}.legend-row.passive{cursor:default;pointer-events:none}.legend-row:hover rect{stroke:#fff;stroke-width:2}.legend-row text,.legend-text{fill:#f1f7fb;font:600 14px Arial,sans-serif}.legend-title{fill:#a9c0d0;font:700 13px Arial,sans-serif;letter-spacing:1px}</style></defs><rect width="100%" height="100%" fill="#082452"/><g clip-path="url(#mapClip)"><rect y="${mapTop}" width="100%" height="${mapBottom - mapTop}" fill="url(#alertOcean)"/><g class="country">${surroundingCountries}</g><g fill="#3e4652">${statePaths}</g>${wfoHits}<g class="satellite">${satelliteTiles}</g><g>${zoneShapes.join("")}</g><g class="radar">${radarTiles}</g><g>${warningShapes.join("")}</g><g class="county">${countyLines}</g><g class="state-boundaries">${statePaths}</g>${wfoBoundaries}${cityLabels}</g><g><rect x="${lx}" y="${ly}" width="${panelWidth}" height="${panelHeight}" rx="10" fill="#080e14" fill-opacity=".94" stroke="#66879b"/><text x="${lx + 18}" y="${ly + 25}" class="legend-title">ACTIVE ZWS PRODUCTS · ${products.length}</text>${legendRows}</g><g font-family="Arial,sans-serif"><rect width="100%" height="${mapTop}" fill="#080d12"/><rect y="${mapTop - 4}" width="100%" height="4" fill="#294250"/><text x="28" y="52" fill="#f5f8fb" font-size="31" font-weight="800">${escapeSvgText(mapTitle)}</text><text x="28" y="88" fill="#aeb9c8" font-size="19" font-weight="700">${escapeSvgText(mapSubtitle)}</text><rect x="${width - 158}" y="10" width="130" height="100" rx="8" fill="#121b20" stroke="#4a626f"/><image href="${getZwsMapMarkPublicDataUri()}" x="${width - 148}" y="15" width="110" height="90" preserveAspectRatio="xMidYMid meet"/></g></svg>`;
}

function sendGzippableBody(request, response, statusCode, body, contentType, cacheControl = "public, max-age=20") {
  const payload = Buffer.isBuffer(body) ? body : Buffer.from(String(body || ""), "utf8");
  const acceptsGzip = /(?:^|,)\s*gzip\s*(?:;|,|$)/i.test(String(request?.headers?.["accept-encoding"] || ""));
  const headers = {
    "Content-Type": contentType,
    "Cache-Control": cacheControl,
    Vary: "Accept-Encoding"
  };
  if (acceptsGzip && payload.length > 2048) {
    const compressed = zlib.gzipSync(payload, { level: zlib.constants.Z_BEST_SPEED });
    headers["Content-Encoding"] = "gzip";
    headers["Content-Length"] = compressed.length;
    response.writeHead(statusCode, headers);
    response.end(compressed);
    return;
  }
  headers["Content-Length"] = payload.length;
  response.writeHead(statusCode, headers);
  response.end(payload);
}

function handlePublicAlertGraphic(requestUrl, response, request = null) {
  const store = loadPublicAlerts();
  const wfo = String(requestUrl.searchParams.get("wfo") || "").replace(/^K/i, "").toUpperCase();
  const includeRadar = requestUrl.searchParams.get("radar") === "1";
  const includeSatellite = requestUrl.searchParams.get("satellite") === "1";
  // Bump cache key when logo embedding strategy changes.
  const key = `bluegray-v11-znws-seal:${store.updatedAt || ""}:${wfo}:${includeRadar ? "radar" : "plain"}:${includeSatellite ? "satellite" : "base"}`;
  let cached = publicAlertGraphicCache.get(key);
  if (!cached || Date.now() - cached.createdAt > 60_000) {
    cached = {
      svg: refreshPublicAlertMapTheme(renderPublicAlertGraphicSvg(store, wfo, includeRadar, includeSatellite), { cityLabelsAboveState: true }),
      createdAt: Date.now()
    };
    publicAlertGraphicCache.set(key, cached);
    // Keep a small set of recently visited local maps plus the national view.
    if (publicAlertGraphicCache.size > 12) publicAlertGraphicCache.delete(publicAlertGraphicCache.keys().next().value);
  }
  // no-store so WFO/public pages pick up new products on the 30s poll without
  // a hard refresh. In-memory cache above still avoids re-rendering every hit.
  sendGzippableBody(
    request,
    response,
    200,
    cached.svg,
    "image/svg+xml; charset=utf-8",
    "no-store, no-cache, must-revalidate, max-age=0"
  );
  return true;
}

async function prewarmPublicOutlooks() {
  // National graphics are the page defaults. Generate them shortly after
  // startup, while the service is otherwise idle, so the first visitor gets a
  // local file rather than waiting on the official geometry service.
  for (const [day, type] of [["1", "cat"], ["2", "cat"], ["3", "cat"]]) {
    try {
      await generatePublicSpcOutlookImage(day, type, "");
      await Promise.all(Object.keys(publicOutlookRegions).filter(Boolean).map((region) => generatePublicSpcOutlookImage(day, type, region)));
    } catch (error) {
      console.warn("[public-outlook] prewarm failed", error.message);
    }
  }
}

async function prewarmPublicHrrrDailyGuidance() {
  try {
    const catalog = await latestHrrrModelCatalog(), runs = catalog.runs || [catalog];
    const selected = runs.find((run) => /(?:00|06|12|18)$/.test(run.run || "") && (run.forecastHours || []).includes(18));
    if (!selected?.run) throw new Error("No complete HRRR F18 run is available");
    await generatePublicWpcMapImage("hrrr-model-zasSevereDaily", 1, "", "", "UTC", { run: selected.run, forecastHour: 18, product: "zasSevereDaily" });
    const extended = runs.find((run) => /(?:00|12)$/.test(run.run || "") && (run.forecastHours || []).includes(48));
    if (extended?.run) await generatePublicWpcMapImage("hrrr-model-zasSevereDay2", 1, "", "", "UTC", { run: extended.run, forecastHour: 48, product: "zasSevereDay2" });
  } catch (error) {
    console.warn("[hrrr-daily-severe] prewarm failed", error.message);
  }
}

const modelPrewarmProducts = ["refc", "temperature", "dewpoint", "wind", "gust", "mucape", "apcp", "smoke"];
const modelPrewarmStatusFile = path.join(dataDir, "model-prewarm-status.json");
const modelPrewarmFailureBackoff = new Map();
const modelPrewarmFailureBackoffMs = 15 * 60_000;
const modelPrewarmBatchSize = 120;
// GDAL frames can consume hundreds of MB each. Scale concurrency by RAM as
// well as CPU so background coverage remains continuous without crowding the
// interactive Hive render path on the 16 GB operations host.
const modelPrewarmMemoryGiB = os.totalmem() / (1024 ** 3);
const modelPrewarmConcurrency = Math.max(2, Math.min(
  10,
  Math.floor((os.cpus()?.length || 4) / 3),
  modelPrewarmMemoryGiB <= 16 ? 4 : modelPrewarmMemoryGiB <= 32 ? 6 : 10
));

function modelBoundsIntersectRegion(run, regionKey) {
  if (!run?.bounds || !regionKey) return true;
  const regionBounds = publicOutlookRegions[regionKey]?.bbox;
  const bounds = [run.bounds.west, run.bounds.south, run.bounds.east, run.bounds.north].map(Number);
  if (!Array.isArray(regionBounds) || !bounds.every(Number.isFinite)) return true;
  return regionBounds[2] >= bounds[0] && regionBounds[0] <= bounds[2] && regionBounds[3] >= bounds[1] && regionBounds[1] <= bounds[3];
}

function retainedModelRuns(catalog, source) {
  const runs = catalog?.runs || (catalog?.run ? [catalog] : []);
  if (source === "gfs") return runs.slice(0, 3);
  if (source === "hrrr") {
    const ordered = runs.slice().sort((a, b) => Date.parse(b.runTime || 0) - Date.parse(a.runTime || 0));
    const preferred = ordered.find((run) => run.run === (catalog.preferredRun || catalog.run));
    return [preferred, ...ordered.filter((run) => run !== preferred)].filter(Boolean).slice(0, 3);
  }
  const retained = [];
  for (const domain of ["MESO1", "MESO2", "MESO3"]) {
    retained.push(...runs.filter((run) => run.domain === domain).sort((a, b) => Date.parse(b.runTime || 0) - Date.parse(a.runTime || 0)).slice(0, 3));
  }
  return retained;
}

function modelPrewarmCachePaths(source, run, product, region, forecastHour) {
  const mapProduct = `${source === "ncep" ? "ncep" : source === "gfs" ? "gfs" : "hrrr"}-model-${product}-${source === "ncep" ? (product === "wind" ? "v24" : product === "smoke" ? "v26" : "v25") : ""}`.replace(/-$/, "");
  const cacheName = `wpc-maps-${publicWpcMapRenderVersion}-${mapProduct}${region ? `-${region}` : ""}-${run.run}-f${String(forecastHour).padStart(2, "0")}${source === "gfs" ? "-edge2edge" : ""}${source === "gfs" && product === "refc" ? "-smooth3" : ""}${region === "north-atlantic" ? "-atl4" : ""}${!region || gfsOnlyPublicOutlookRegionKeys.has(region) ? "-nocities" : ""}-UTC.svg`;
  const svgPath = path.join(publicOutlookCacheDir, cacheName);
  return { svgPath, webpPath: svgPath.replace(/\.svg$/i, "-beta-q82.webp"), mapProduct };
}

function buildModelPrewarmJobs(hrrrCatalog, ncepCatalog, gfsCatalog) {
  syncTemporaryMapRegions();
  // Temporary mesoscale sectors belong to their linked WRF domains. They stay
  // available to HRRR on demand, but are excluded from the eager HRRR sweep to
  // avoid duplicating permanent Wyoming/Northeast regional coverage.
  const hrrrRegions = [...hrrrPublicOutlookRegionKeys];
  const temporaryRegions = loadTemporaryMapRegions({ activeOnly: true }).regions;
  const tiers = {
    latest: { jobs: { hrrr: [], ncep: [], gfs: [] }, coverage: { regions: {} } },
    backfill: { jobs: { hrrr: [], ncep: [], gfs: [] }, coverage: { regions: {} } }
  };
  for (const [source, catalog] of [["hrrr", hrrrCatalog], ["ncep", ncepCatalog], ["gfs", gfsCatalog]]) {
    const retainedRuns = retainedModelRuns(catalog, source), latestRunIds = new Set();
    if (source === "hrrr" && retainedRuns[0]) latestRunIds.add(retainedRuns[0].run);
    if (source === "gfs" && retainedRuns[0]) latestRunIds.add(retainedRuns[0].run);
    if (source === "ncep") for (const domain of ["MESO1", "MESO2", "MESO3"]) {
      const latest = retainedRuns.find((run) => run.domain === domain);
      if (latest) latestRunIds.add(latest.run);
    }
    for (const run of retainedRuns) {
      const tier = latestRunIds.has(run.run) ? tiers.latest : tiers.backfill;
      for (const product of source === "gfs" ? ["refc", "apcp", "pcpn", "temperature", "cloud", "pwat"] : modelPrewarmProducts) {
        if (source === "ncep" && !run.products?.[product]) continue;
        if (source === "hrrr" && (!hrrrModelProducts[product] || hrrrModelProducts[product].internal)) continue;
        const hours = run.productForecastHours?.[product] || run.forecastHours || [];
        const definition = source === "hrrr" ? hrrrModelProducts[product] : source === "gfs" ? gfsModelProducts[product] : null;
        const regions = source === "gfs" ? (["temperature", "cloud", "pwat"].includes(product) ? ["", ...gfsUsPublicOutlookRegionKeys, ...(product === "temperature" ? [] : gfsBasinPublicOutlookRegionKeys)] : ["", ...gfsBasinPublicOutlookRegionKeys]) : source === "hrrr" ? hrrrRegions : temporaryRegions
          .filter((candidate) => (candidate.domains || [candidate.domain]).includes(run.domain))
          .filter((candidate) => {
            const requested = run.bounds, values = candidate.bbox;
            return requested && Array.isArray(values) && [[requested.west, values[0]], [requested.south, values[1]], [requested.east, values[2]], [requested.north, values[3]]]
              .every(([a, b]) => Number.isFinite(Number(a)) && Math.abs(Number(a) - Number(b)) < 0.02);
          })
          .map((candidate) => candidate.id);
        for (const region of regions) {
          for (const forecastHour of hours) {
            const hourValue = Number(forecastHour);
            if (!Number.isFinite(hourValue)) continue;
            if (Number.isFinite(Number(definition?.minimumHour)) && hourValue < Number(definition.minimumHour)) continue;
            if (Number.isFinite(Number(definition?.maximumHour)) && hourValue > Number(definition.maximumHour)) continue;
            const paths = modelPrewarmCachePaths(source, run, product, region, Number(forecastHour));
            const coverageKey = `${source}:${region || "national"}`, regionCoverage = tier.coverage.regions[coverageKey] ||= { source, region: region || "national", total: 0, remaining: 0 };
            regionCoverage.total += 1;
            if (fs.existsSync(paths.webpPath) && fs.statSync(paths.webpPath).size > 1_000) continue;
            regionCoverage.remaining += 1;
            tier.jobs[source].push({ source, run, product, region, forecastHour: Number(forecastHour), ...paths });
          }
        }
      }
    }
  }
  const latestMissing = tiers.latest.jobs.hrrr.length + tiers.latest.jobs.ncep.length + tiers.latest.jobs.gfs.length;
  const selectedTier = latestMissing ? tiers.latest : tiers.backfill, phase = latestMissing ? "latest" : "backfill";
  const jobs = [], total = Math.max(selectedTier.jobs.hrrr.length, selectedTier.jobs.ncep.length, selectedTier.jobs.gfs.length);
  for (let index = 0; index < total; index += 1) {
    if (selectedTier.jobs.hrrr[index]) jobs.push(selectedTier.jobs.hrrr[index]);
    if (selectedTier.jobs.ncep[index]) jobs.push(selectedTier.jobs.ncep[index]);
    if (selectedTier.jobs.gfs[index]) jobs.push(selectedTier.jobs.gfs[index]);
  }
  jobs.coverage = selectedTier.coverage;
  jobs.phase = phase;
  jobs.backfillQueued = tiers.backfill.jobs.hrrr.length + tiers.backfill.jobs.ncep.length + tiers.backfill.jobs.gfs.length;
  return jobs;
}

function saveModelPrewarmStatus(status) {
  try {
    let previous = {};
    try { previous = JSON.parse(fs.readFileSync(modelPrewarmStatusFile, "utf8")); } catch { /* first status write */ }
    fs.writeFileSync(modelPrewarmStatusFile, JSON.stringify({ ...previous, ...status, updatedAt: new Date().toISOString() }, null, 2));
  } catch { /* status reporting is best effort */ }
}

function summarizeModelPrewarmJobs(jobs) {
  const summary = { phase: jobs.phase || "latest", backfillQueued: jobs.backfillQueued || 0, sources: {}, products: {}, regions: {}, coverage: jobs.coverage || { regions: {} } };
  for (const job of jobs) {
    summary.sources[job.source] = (summary.sources[job.source] || 0) + 1;
    summary.products[job.product] = (summary.products[job.product] || 0) + 1;
    summary.regions[job.region || "national"] = (summary.regions[job.region || "national"] || 0) + 1;
  }
  return summary;
}

async function generateModelPrewarmFrame(job) {
  const generate = async () => {
    const request = {
      run: job.run.run,
      forecastHour: job.forecastHour,
      product: job.product,
      ...(job.source === "ncep" && job.run.inventoryKey ? { inventoryKey: job.run.inventoryKey } : {})
    };
    await generatePublicWpcMapImage(job.mapProduct, 1, job.region, "", "UTC", request);
  };
  if (!fs.existsSync(job.svgPath)) await generate();
  try {
    await ensurePublicModelWebp(job.svgPath, job.webpPath);
  } catch (error) {
    // A full disk can leave a truncated SVG/WebP that exists but can never be
    // decoded. Remove only those final cache files and regenerate from GRIB.
    for (const filePath of [job.webpPath, job.svgPath]) {
      try { fs.rmSync(filePath, { force: true }); } catch { /* best effort */ }
    }
    await generate();
    await ensurePublicModelWebp(job.svgPath, job.webpPath);
  }
}

async function runModelPrewarmPass() {
  pruneModelIntermediateTiffs();
  pruneCorruptModelFinalArtifacts();
  const [hrrrCatalog, ncepCatalog, gfsCatalog] = await Promise.all([
    latestHrrrModelCatalog().catch((error) => ({ error: error.message, runs: [] })),
    latestNcepModelCatalog().catch((error) => ({ error: error.message, runs: [] })),
    latestGfsModelCatalog().catch((error) => ({ error: error.message, runs: [] }))
  ]);
  const retained = new Map();
  const retainedHrrr = retainedModelRuns(hrrrCatalog, "hrrr").map((run) => run.run);
  if (retainedHrrr.length) retained.set("hrrr", new Set(retainedHrrr));
  const retainedGfs = retainedModelRuns(gfsCatalog, "gfs").map((run) => run.run);
  if (retainedGfs.length) retained.set("gfs", new Set(retainedGfs));
  for (const domain of ["MESO1", "MESO2", "MESO3"]) {
    const domainRuns = retainedModelRuns(ncepCatalog, "ncep").filter((run) => run.domain === domain).map((run) => String(run.run).match(/MESO[123]-run-(\d{8}T\d{6}Z)/i)?.[1]).filter(Boolean);
    if (domainRuns.length) retained.set(domain, new Set(domainRuns));
  }
  pruneModelArtifactsToThreeRuns(retained);
  const jobs = buildModelPrewarmJobs(hrrrCatalog, ncepCatalog, gfsCatalog);
  const passStartedAt = Date.now();
  saveModelPrewarmStatus({ running: true, total: jobs.length, batchTotal: Math.min(jobs.length, modelPrewarmBatchSize), queued: jobs.length, processed: 0, failed: 0, deferred: 0, cooldowns: modelPrewarmFailureBackoff.size, framesPerMinute: 0, passStartedAt: new Date(passStartedAt).toISOString(), current: null, breakdown: summarizeModelPrewarmJobs(jobs), hrrrError: hrrrCatalog.error || null, wrfError: ncepCatalog.error || null, gfsError: gfsCatalog.error || null });
  let processed = 0, failed = 0, deferred = 0, lastSuccess = null, lastFailure = null;
  const batch = jobs.slice(0, modelPrewarmBatchSize);
  let nextJob = 0;
  await Promise.all(Array.from({ length: Math.min(modelPrewarmConcurrency, batch.length) }, async () => {
    while (nextJob < batch.length) {
      const job = batch[nextJob++];
      const label = `${job.source}:${job.run.run}:${job.product}:${job.region || "national"}:f${String(job.forecastHour).padStart(2, "0")}`;
      const retryAt = modelPrewarmFailureBackoff.get(label) || 0;
      if (retryAt > Date.now()) { processed += 1; deferred += 1; continue; }
      modelPrewarmFailureBackoff.delete(label);
      const elapsedMinutes = Math.max(1 / 60, (Date.now() - passStartedAt) / 60_000);
      saveModelPrewarmStatus({ running: true, total: jobs.length, batchTotal: batch.length, queued: Math.max(0, jobs.length - processed), processed, failed, deferred, cooldowns: modelPrewarmFailureBackoff.size, framesPerMinute: Number((processed / elapsedMinutes).toFixed(1)), passStartedAt: new Date(passStartedAt).toISOString(), current: label, ...(lastSuccess ? { lastSuccess } : {}), ...(lastFailure ? { lastFailure } : {}) });
      try {
        await generateModelPrewarmFrame(job);
        modelPrewarmFailureBackoff.delete(label);
        lastSuccess = { label, at: new Date().toISOString() };
      } catch (error) {
        failed += 1;
        modelPrewarmFailureBackoff.set(label, Date.now() + modelPrewarmFailureBackoffMs);
        lastFailure = { label, at: new Date().toISOString(), error: String(error?.message || error).slice(0, 240) };
        console.warn(`[model-prewarm] ${label} failed`, error?.message || error);
      }
      processed += 1;
    }
  }));
  const elapsedMinutes = Math.max(1 / 60, (Date.now() - passStartedAt) / 60_000);
  saveModelPrewarmStatus({ running: false, total: jobs.length, batchTotal: batch.length, queued: Math.max(0, jobs.length - processed), processed, failed, deferred, cooldowns: modelPrewarmFailureBackoff.size, framesPerMinute: Number((processed / elapsedMinutes).toFixed(1)), passStartedAt: new Date(passStartedAt).toISOString(), current: null, ...(lastSuccess ? { lastSuccess } : {}), ...(lastFailure ? { lastFailure } : {}) });
  pruneModelIntermediateTiffs();
  return jobs.length - processed;
}

async function startModelPrewarmWorker() {
  console.log(`[model-prewarm] worker started as PID ${process.pid} · concurrency ${modelPrewarmConcurrency} · RAM ${modelPrewarmMemoryGiB.toFixed(1)} GiB`);
  process.on("disconnect", () => process.exit(0));
  try { os.setPriority(process.pid, os.constants.priority.PRIORITY_LOW); } catch { /* best effort */ }
  while (true) {
    let remaining = 0;
    try { remaining = await runModelPrewarmPass(); }
    catch (error) { console.warn("[model-prewarm] pass failed", error?.message || error); }
    await new Promise((resolve) => setTimeout(resolve, remaining > 0 ? 5_000 : 90_000));
  }
}

async function ensureRadarStationList() {
  if (radarStationsCache && Date.now() - radarStationsCacheAt <= 6 * 60 * 60_000) {
    return radarStationsCache;
  }
  const upstream = JSON.parse(await fetchText("https://api.weather.gov/radar/stations", {
    headers: { "User-Agent": "ZASNet-Cave/1.0 (https://zasnetwx.com)" }
  }));
  radarStationsCache = {
    type: "FeatureCollection",
    features: (upstream.features || [])
      .filter((feature) => feature?.geometry?.type === "Point" && feature?.properties?.stationType === "WSR-88D")
      .map((feature) => ({
        type: "Feature",
        geometry: feature.geometry,
        properties: {
          id: String(feature.properties.id || "").toUpperCase(),
          name: feature.properties.name || "Radar",
          stationType: feature.properties.stationType
        }
      }))
      .filter((feature) => /^[A-Z0-9]{4}$/.test(feature.properties.id))
  };
  radarStationsCacheAt = Date.now();
  return radarStationsCache;
}

async function ensureRadarShelterTemperatures() {
  const cacheHasCurrentSchema = radarShelterTemperaturesCache?.properties?.dataVersion === 2 &&
    radarShelterTemperaturesCache.features?.some((feature) =>
      Object.hasOwn(feature.properties || {}, "leavingAirTempF") &&
      Object.hasOwn(feature.properties || {}, "transmitterPowerKw") &&
      Object.hasOwn(feature.properties || {}, "levelTwoAgeMinutes")
    );
  if (cacheHasCurrentSchema && Date.now() - radarShelterTemperaturesCacheAt <= 5 * 60_000) {
    return radarShelterTemperaturesCache;
  }
  if (radarShelterTemperaturesJob) return radarShelterTemperaturesJob;
  radarShelterTemperaturesJob = (async () => {
    const stations = await ensureRadarStationList();
    const features = stations.features.map((feature) => ({
      ...feature,
      properties: {
        ...feature.properties,
        shelterTempF: null,
        leavingAirTempF: null,
        transmitterPowerKw: null,
        levelTwoLastReceivedTime: null,
        levelTwoAgeMinutes: null,
        performanceTime: null
      }
    }));
    let nextIndex = 0;
    let reporting = 0;
    const worker = async () => {
      while (nextIndex < features.length) {
        const index = nextIndex++;
        const feature = features[index];
        try {
          const detail = JSON.parse(await fetchText(`https://api.weather.gov/radar/stations/${feature.properties.id}`, {
            headers: { "User-Agent": "ZASNet-Cave/1.0 (https://zasnetwx.com)" }
          }));
          const performance = detail?.properties?.performance;
          const performanceProperties = performance?.properties || {};
          const shelterCelsius = Number(performanceProperties.shelterTemperature?.value);
          const leavingAirCelsius = Number(performanceProperties.transmitterLeavingAirTemperature?.value);
          const transmitterPowerKw = Number(performanceProperties.transmitterPeakPower?.value);
          const levelTwoLastReceivedTime = detail?.properties?.latency?.levelTwoLastReceivedTime || null;
          if (Number.isFinite(shelterCelsius)) {
            feature.properties.shelterTempF = Math.round(shelterCelsius * 9 / 5 + 32);
            feature.properties.performanceTime = performance?.timestamp || null;
            reporting += 1;
          }
          feature.properties.leavingAirTempF = Number.isFinite(leavingAirCelsius)
            ? Math.round(leavingAirCelsius * 9 / 5 + 32)
            : null;
          feature.properties.transmitterPowerKw = Number.isFinite(transmitterPowerKw)
            ? Math.round(transmitterPowerKw)
            : null;
          feature.properties.levelTwoLastReceivedTime = levelTwoLastReceivedTime;
          feature.properties.levelTwoAgeMinutes = levelTwoLastReceivedTime
            ? Math.max(0, Math.round((Date.now() - new Date(levelTwoLastReceivedTime).getTime()) / 60_000))
            : null;
        } catch {
          // A station may be offline or omit its performance block; retain it without a value.
        }
      }
    };
    await Promise.all(Array.from({ length: 12 }, () => worker()));
    radarShelterTemperaturesCache = {
      type: "FeatureCollection",
      features,
      properties: { dataVersion: 2, reporting, total: features.length, generatedAt: new Date().toISOString() }
    };
    radarShelterTemperaturesCacheAt = Date.now();
    return radarShelterTemperaturesCache;
  })().finally(() => { radarShelterTemperaturesJob = null; });
  return radarShelterTemperaturesJob;
}

function spcMesoscaleTextSection(text,label,nextLabels){
  const escaped=label.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),next=(nextLabels||[]).map((item)=>item.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|");
  const match=String(text||"").match(new RegExp(`${escaped}\\.\\.\\.([\\s\\S]*?)${next?`(?=\\n\\s*(?:${next})(?:\\.\\.\\.|\\s)|$)`:"$"}`,"i"));
  return match?match[1].replace(/\s+/g," ").trim():"";
}
async function loadSpcMesoscaleDetail(number,year){
  const key=`${year}:${number}`,cached=spcMesoscaleDetailCache.get(key);if(cached&&cached.expires>Date.now())return cached.value;
  const text=await fetchText(`https://www.spc.noaa.gov/products/md/md${String(number).padStart(4,"0")}.txt`),valid=String(text).match(/Valid\s+(\d{6}Z\s*-\s*\d{6}Z)/i)?.[1]||"",probability=Number(String(text).match(/Probability of Watch Issuance\.\.\.(\d+)\s*percent/i)?.[1]),wfos=String(text).match(/ATTN\.\.\.WFO\.\.\.([^\n]+)/i)?.[1]?.split("...").map((item)=>item.trim()).filter(Boolean)||[];
  const value={number:Number(number),year,areasAffected:spcMesoscaleTextSection(text,"Areas affected",["Concerning"]),concerning:spcMesoscaleTextSection(text,"Concerning",["Valid"]),valid,watchProbability:Number.isFinite(probability)?probability:null,summary:spcMesoscaleTextSection(text,"SUMMARY",["DISCUSSION"]),discussion:spcMesoscaleTextSection(text,"DISCUSSION",["ATTN"]),wfos,peakTornado:String(text).match(/MOST PROBABLE PEAK TORNADO INTENSITY\.\.\.([^\n]+)/i)?.[1]?.trim()||"",peakWind:String(text).match(/MOST PROBABLE PEAK WIND GUST\.\.\.([^\n]+)/i)?.[1]?.trim()||"",peakHail:String(text).match(/MOST PROBABLE PEAK HAIL SIZE\.\.\.([^\n]+)/i)?.[1]?.trim()||"",textUrl:`https://www.spc.noaa.gov/products/md/md${String(number).padStart(4,"0")}.txt`,productUrl:`https://www.spc.noaa.gov/products/md/md${String(number).padStart(4,"0")}.html`};
  spcMesoscaleDetailCache.set(key,{expires:Date.now()+5*60_000,value});return value;
}

async function publicModelCatalog(modelId) {
  const definition = publicModelDefinitions[modelId];
  if (!definition) { const error = new Error("Unknown model"); error.status = 404; throw error; }
  const raw = definition.source === "hrrr" ? await latestHrrrModelCatalog()
    : definition.source === "gfs" ? await latestGfsModelCatalog()
      : definition.source === "ncep" ? await latestNcepModelCatalog()
        : await latestHafsModelCatalog(definition.source);
  let runs = raw.runs || [raw];
  if (definition.domain) runs = runs.filter((run) => run.domain === definition.domain);
  return { definition, runs };
}

function publicModelRunId(definition, run) {
  return definition.source.startsWith("hfs") ? `${run.run}-${run.stormId}` : String(run.run);
}

function publicModelBounds(value) {
  if (Array.isArray(value) && value.length === 4) return value.map(Number);
  if (value && typeof value === "object") return [value.west, value.south, value.east, value.north].map(Number);
  return null;
}

function publicRunBounds(definition, run) {
  return publicModelBounds(run.displayBounds || run.usableGridBounds || run.gridBounds || run.bounds || run.bbox || definition.bounds);
}

function publicModelRunRecord(definition, run) {
  return {
    id: publicModelRunId(definition, run),
    initializationTime: new Date(run.runTime).toISOString(),
    forecastHours: [...new Set(run.forecastHours || [])].sort((a, b) => a - b),
    bounds: publicRunBounds(definition, run),
    ...(run.domain ? { domain: run.domain } : {}),
    ...(run.stormId ? { storm: { id: run.stormId, name: run.stormName }, region: run.region } : {}),
    ...(run.spacing != null ? { gridSpacing: run.spacing } : {}),
    ...(run.generatedAt ? { generatedAt: new Date(run.generatedAt).toISOString() } : {})
  };
}

function publicModelProductDefinitions(definition, run) {
  const definitions = definition.source === "gfs" ? gfsModelProducts : definition.source.startsWith("hfs") ? hafsModelProducts : hrrrModelProducts;
  const advertised = run.products ? new Set(Object.keys(run.products)) : null;
  return Object.entries(definitions).filter(([id, config]) => {
    if (config.internal && definition.source !== "ncep") return false;
    if (definition.source === "ncep") return advertised?.has(id) && NCEP_OPS_OVERLAY_PRODUCTS.has(id);
    if (advertised && !advertised.has(id) && definition.source !== "hrrr") return false;
    return true;
  });
}

function publicModelUnit(config) {
  const text = String(config.legend || "");
  return ["dBZ", "mph", "kt", "m/s", "°F", "°C", "hPa", "J/kg", "m²/s²", "in/hr", "in", "%", "mi", "ft AGL", "° TRUE", "µg/m³", "mg/m²", "0–10"].find((unit) => text.includes(unit)) || null;
}

function publicNumericalGridEncoding(modelId, product, config) {
  const explicit = modelId === "hrrr" ? publicConusGridProducts[product] : null;
  if (explicit) return { sampleType: "uint16", missingValue: 65535, ...explicit };
  const categorical = Boolean(config.categories?.length || config.categoryRamps?.length || config.derivedPrecipType || config.derivedWindDirection || /(?:type|mode|category)/i.test(product));
  const unit = publicModelUnit(config) || "dimensionless";
  const encoding = unit === "dBZ" ? { scale: .1, offset: -100 }
    : ["°F", "°C"].includes(unit) ? { scale: .01, offset: -150 }
      : ["mph", "kt", "m/s"].includes(unit) ? { scale: .01, offset: -200 }
        : unit === "hPa" ? { scale: .1, offset: 800 }
          : unit === "J/kg" ? { scale: .25, offset: -3000 }
            : unit === "m²/s²" ? { scale: .1, offset: -3000 }
              : unit === "in/hr" ? { scale: .0001, offset: 0 }
                : unit === "in" || unit === "mi" ? { scale: .001, offset: 0 }
                  : unit === "%" || unit === "° TRUE" ? { scale: .01, offset: 0 }
                    : unit === "ft AGL" ? { scale: 1, offset: 0 }
                      : ["µg/m³", "mg/m²"].includes(unit) ? { scale: .01, offset: 0 }
                        : { scale: .01, offset: -200 };
  return { sampleType: "uint16", missingValue: 65535, unit, ...encoding, resampling: categorical ? "near" : "bilinear" };
}

function publicHrrrNumericalProduct(id, config) {
  return !id.startsWith("zas") && !/\bEXPERIMENTAL\b/i.test(String(config.title || ""));
}

function publicPressureGridRecord(modelId, definition, run) {
  const hours = [...new Set(run.productForecastHours?.pressure || (definition.source === "hrrr" ? run.forecastHours || [] : []))].sort((a, b) => a - b);
  if (!hours.length || (definition.source !== "hrrr" && !run.products?.pressure)) return null;
  const base = `/v1/models/${modelId}/${encodeURIComponent(publicModelRunId(definition, run))}/pressure/{forecastHour}/grid`;
  if (["hafs-a", "hafs-b"].includes(modelId)) return { forecastHours: hours, gridUrls: { storm: `${base}/storm.bin`, parent: `${base}/parent.bin` } };
  if (modelId === "hrrr") return { forecastHours: hours, gridUrl: `${base}/conus.bin` };
  if (modelId.startsWith("znws-wrf-")) return { forecastHours: hours, gridUrl: `${base}/domain.bin` };
  return null;
}

function publicModelProductRecord(modelId, definition, run, id, config) {
  const hours = (run.productForecastHours?.[id] || run.forecastHours || []).filter((hour) => hour >= (config.minimumHour || 0) && hour <= (config.maximumHour ?? Infinity));
  const palette = (config.stops || []).map(([value, color]) => ({ value, color }));
  const categories = (config.categories || []).map(([label, color], index) => ({ value: index + 1, label, color }));
  const values = palette.map((stop) => Number(stop.value)).filter(Number.isFinite);
  const conusGrid = modelId === "hrrr" && publicHrrrNumericalProduct(id, config) ? publicNumericalGridEncoding(modelId, id, config) : null;
  const wrfGrid = modelId.startsWith("znws-wrf-") ? publicNumericalGridEncoding(modelId, id, config) : null;
  const hafsGrid = ["hafs-a", "hafs-b"].includes(modelId) && (publicHafsGridProducts[id] || id === "refcmslp");
  const hafsBase = `/v1/models/${modelId}/${encodeURIComponent(publicModelRunId(definition, run))}/${encodeURIComponent(id)}/{forecastHour}/grid`;
  const pressureGrid = publicPressureGridRecord(modelId, definition, run);
  return {
    id,
    displayName: String(config.title || run.products?.[id]?.title || id).replace(/^(?:HRRR|GFS|HAFS|ZNWS-WRF|ZASNETWORK WRF)\s+/i, ""),
    unit: publicModelUnit(config), palette: palette.length ? palette : categories,
    displayRange: values.length ? { minimum: Math.min(...values), maximum: Math.max(...values) } : null,
    coverageBounds: publicRunBounds(definition, run),
    sourceProjection: definition.sourceProjection, outputProjection: "EPSG:3857",
    forecastHours: [...new Set(hours)].sort((a, b) => a - b),
    overlayTemplate: `/v1/models/${modelId}/${encodeURIComponent(publicModelRunId(definition, run))}/${encodeURIComponent(id)}/{forecastHour}/overlay.png?bbox={west},{south},{east},{north}&width={width}`,
    ...(conusGrid ? { gridTemplate: `/v1/models/${modelId}/${encodeURIComponent(publicModelRunId(definition, run))}/${encodeURIComponent(id)}/{forecastHour}/grid/conus.bin`, gridWidth: 4096, gridBounds: definition.bounds, gridProjection: "EPSG:3857", gridCompression: "deflate" } : {}),
    ...(wrfGrid ? { gridTemplate: `/v1/models/${modelId}/${encodeURIComponent(publicModelRunId(definition, run))}/${encodeURIComponent(id)}/{forecastHour}/grid/domain.bin`, gridWidth: 2048, gridBounds: publicRunBounds(definition, run), gridProjection: "EPSG:3857", gridCompression: "deflate" } : {}),
    ...(pressureGrid ? { pressureForecastHours: pressureGrid.forecastHours, ...(pressureGrid.gridUrl ? { pressureGridTemplate: pressureGrid.gridUrl } : { pressureGridTemplates: pressureGrid.gridUrls }) } : {}),
    ...(hafsGrid ? { gridTemplate: id === "refcmslp" ? `${hafsBase}/storm.bin?component=refc` : `${hafsBase}/storm.bin`, gridDomains: {
      storm: id === "refcmslp" ? null : `${hafsBase}/storm.bin`,
      parent: id === "refcmslp" ? null : `${hafsBase}/parent.bin`
    }, gridProjection: "EPSG:3857", gridCompression: "deflate", stormGridWidth: 2048, parentGridWidth: 4096,
    ...(id === "refcmslp" ? { gridComponents: {
      reflectivity: { storm: `${hafsBase}/storm.bin?component=refc`, parent: `${hafsBase}/parent.bin?component=refc` },
      pressure: { storm: `${hafsBase}/storm.bin?component=pressure`, parent: `${hafsBase}/parent.bin?component=pressure` }
    }} : {}) } : {})
  };
}

function findPublicModelRun(definition, runs, requestedId) {
  const decoded = decodeURIComponent(requestedId);
  return runs.find((run) => publicModelRunId(definition, run) === decoded || (!definition.source.startsWith("hfs") && (String(run.run) === decoded || String(run.runTime) === decoded)));
}

async function renderPublicModelApiOverlay(modelId, definition, run, product, forecastHour, bbox, width) {
  const [minX, minY] = webMercatorPoint(bbox[0], bbox[1]), [maxX, maxY] = webMercatorPoint(bbox[2], bbox[3]);
  const height = Math.max(64, Math.min(4096, Math.round(width * Math.max(.1, (maxY - minY) / Math.max(1, maxX - minX)))));
  const project = webMercatorMapProjection(bbox, width, height, 0);
  const identity = crypto.createHash("sha256").update(JSON.stringify({ modelId, run: publicModelRunId(definition, run), product, forecastHour, bbox, width, inventory: run.inventoryKey || run.generatedAt || "" })).digest("hex").slice(0, 24);
  const cacheDir = path.join(dataDir, "generated", "public-model-v1"), cachePath = path.join(cacheDir, `${identity}.png`);
  fs.mkdirSync(cacheDir, { recursive: true });
  if (!fs.existsSync(cachePath) || fs.statSync(cachePath).size < 200) {
    const stem = `public-v1-${identity}`;
    const raster = definition.source === "hrrr" ? await renderHrrrModelField(product, run.run, forecastHour, { bbox }, project, stem)
      : definition.source === "gfs" ? await renderGfsModelField(product, run.run, forecastHour, { bbox }, project, stem)
        : definition.source === "ncep" ? await renderNcepModelField(product, run.run, forecastHour, { bbox }, project, stem)
          : await renderHafsModelField(definition.source, run.stormId, "storm", product, run.run, forecastHour, { bbox }, project, stem);
    const match = /^data:image\/png;base64,([A-Za-z0-9+/=]+)$/.exec(raster.dataUri || "");
    if (!match) throw new Error("Model renderer did not return a transparent PNG field");
    fs.writeFileSync(cachePath, await reprojectOpsOverlayPngToWebMercator(Buffer.from(match[1], "base64"), bbox, width, height));
  }
  return { buffer: fs.readFileSync(cachePath), modifiedAt: fs.statSync(cachePath).mtime };
}

const publicConusGridJobs = new Map();
async function renderPublicConusGrid(modelId, definition, run, product, forecastHour) {
  const encoding = hrrrModelProducts[product] && publicHrrrNumericalProduct(product, hrrrModelProducts[product]) ? publicNumericalGridEncoding(modelId, product, hrrrModelProducts[product]) : null;
  if (modelId !== "hrrr" || !encoding) throw Object.assign(new Error("CONUS numerical grid is unavailable"), { status: 404 });
  const bounds = definition.bounds, width = 4096;
  const [minX, minY] = webMercatorPoint(bounds[0], bounds[1]), [maxX, maxY] = webMercatorPoint(bounds[2], bounds[3]);
  const height = Math.round(width * (maxY - minY) / (maxX - minX));
  const identity = crypto.createHash("sha256").update(JSON.stringify({ schema: 1, modelId, run: run.run, product, forecastHour, bounds, width, encoding })).digest("hex").slice(0, 24);
  const cacheDir = path.join(dataDir, "generated", "public-model-grid-v1"), cachePath = path.join(cacheDir, `${identity}.bin`);
  fs.mkdirSync(cacheDir, { recursive: true });
  if (fs.existsSync(cachePath) && fs.statSync(cachePath).size > 200) return { buffer: fs.readFileSync(cachePath), modifiedAt: fs.statSync(cachePath).mtime };
  if (publicConusGridJobs.has(identity)) return publicConusGridJobs.get(identity);
  const job = (async () => {
    const project = webMercatorMapProjection(bounds, width, height, 0), stem = `conus-grid-v1-${identity}`;
    const raster = await renderHrrrModelField(product, run.run, forecastHour, { bbox: bounds }, project, stem);
    const rawPath = path.join(cacheDir, `${identity}.raw`), rawHeaderPath = rawPath.replace(/\.raw$/, ".hdr");
    await runWeatherMapCommand("gdalwarp", ["-overwrite", "-q", "-t_srs", "EPSG:3857", "-te", String(minX), String(minY), String(maxX), String(maxY), "-te_srs", "EPSG:3857", "-ts", String(width), String(height), "-r", encoding.resampling, "-srcnodata", product === "preciptype" ? "0" : "-9999", "-dstnodata", "-9999", "-wo", "UNIFIED_SRC_NODATA=YES", "-ot", "Float32", "-of", "ENVI", "-co", "INTERLEAVE=BSQ", raster.tifPath, rawPath]);
    const floats = fs.readFileSync(rawPath), bytesPerSample = encoding.sampleType === "float32" ? 4 : 2, samples = Buffer.allocUnsafe(width * height * bytesPerSample);
    let physicalMinimum = Infinity, physicalMaximum = -Infinity, missingCount = 0;
    for (let index = 0; index < width * height; index += 1) {
      const value = floats.readFloatLE(index * 4);
      if (!Number.isFinite(value) || value <= -9000 || (product === "preciptype" && value <= 0)) { if (encoding.sampleType === "float32") samples.writeFloatLE(-9999, index * 4); else samples.writeUInt16LE(65535, index * 2); missingCount += 1; continue; }
      if (encoding.sampleType === "float32") { samples.writeFloatLE(value, index * 4); physicalMinimum = Math.min(physicalMinimum, value); physicalMaximum = Math.max(physicalMaximum, value); continue; }
      const raw = Math.max(0, Math.min(65534, Math.round((value - encoding.offset) / encoding.scale)));
      samples.writeUInt16LE(raw, index * 2);
      const reconstructed = raw * encoding.scale + encoding.offset;
      physicalMinimum = Math.min(physicalMinimum, reconstructed); physicalMaximum = Math.max(physicalMaximum, reconstructed);
    }
    const compressed = zlib.deflateSync(samples, { level: 6 });
    const metadata = {
      schemaVersion: 1, model: modelId, run: run.run, product, forecastHour,
      validTime: new Date(Date.parse(run.runTime) + forecastHour * 3_600_000).toISOString(),
      width, height, projection: "EPSG:3857", bounds, mercatorBounds: [minX, minY, maxX, maxY],
      sampleType: encoding.sampleType, byteOrder: "little-endian", scale: encoding.scale, offset: encoding.offset, missingValue: encoding.missingValue,
      unit: encoding.unit, rowOrder: "north-to-south", columnOrder: "west-to-east", resampling: encoding.resampling,
      compression: "deflate", uncompressedBytes: samples.length, physicalMinimum: Number.isFinite(physicalMinimum) ? physicalMinimum : null,
      physicalMaximum: Number.isFinite(physicalMaximum) ? physicalMaximum : null, missingCount,
      ...(encoding.categoryEncoding ? { categoryEncoding: encoding.categoryEncoding } : {})
    };
    const json = Buffer.from(JSON.stringify(metadata)), headerLength = 16 + json.length, header = Buffer.allocUnsafe(16);
    header.write("ZASGRID\0", 0, 8, "ascii"); header.writeUInt16LE(1, 8); header.writeUInt16LE(0xFEFF, 10); header.writeUInt32LE(headerLength, 12);
    const output = Buffer.concat([header, json, compressed]), temporary = `${cachePath}.${process.pid}.${Date.now()}.tmp`;
    fs.writeFileSync(temporary, output); fs.renameSync(temporary, cachePath);
    try { fs.unlinkSync(rawPath); } catch {} try { fs.unlinkSync(rawHeaderPath); } catch {}
    return { buffer: output, modifiedAt: fs.statSync(cachePath).mtime };
  })().finally(() => publicConusGridJobs.delete(identity));
  publicConusGridJobs.set(identity, job); return job;
}

function publicHafsFrameBounds(run, forecastHour, product, domain) {
  const points = run.trackPoints || [], point = points.find((entry) => entry.hour === forecastHour) || points.reduce((best, entry) => !best || Math.abs(entry.hour - forecastHour) < Math.abs(best.hour - forecastHour) ? entry : best, null);
  const center = point || { lon: (run.bbox[0] + run.bbox[2]) / 2, lat: (run.bbox[1] + run.bbox[3]) / 2 };
  if (product === "apcp" && points.length) {
    const lons = points.map((entry) => entry.lon), lats = points.map((entry) => entry.lat), pad = domain === "parent" ? 12 : 6;
    return [Math.max(-180, Math.min(...lons) - pad), Math.max(-75, Math.min(...lats) - pad), Math.min(180, Math.max(...lons) + pad), Math.min(80, Math.max(...lats) + pad)];
  }
  const halfLongitude = domain === "parent" ? 30 : 10;
  const halfLatitude = domain === "parent" ? Math.max(9, Math.min(13, halfLongitude * Math.cos(center.lat * Math.PI / 180) / (1400 / 654))) : 5;
  return [Math.max(-180, center.lon - halfLongitude), Math.max(-75, center.lat - halfLatitude), Math.min(180, center.lon + halfLongitude), Math.min(80, center.lat + halfLatitude)];
}

async function renderPublicWrfGrid(modelId, definition, run, product, config, forecastHour) {
  if (!modelId.startsWith("znws-wrf-") || definition.source !== "ncep") throw Object.assign(new Error("ZNWS-WRF numerical grid is unavailable"), { status: 404 });
  const encoding = publicNumericalGridEncoding(modelId, product, config);
  const bounds = publicRunBounds(definition, run);
  if (!Array.isArray(bounds) || bounds.length !== 4 || !bounds.every(Number.isFinite)) throw new Error("ZNWS-WRF domain bounds are unavailable");
  const width = 2048, [minX, minY] = webMercatorPoint(bounds[0], bounds[1]), [maxX, maxY] = webMercatorPoint(bounds[2], bounds[3]);
  const height = Math.max(256, Math.min(4096, Math.round(width * (maxY - minY) / Math.max(1, maxX - minX))));
  const identity = crypto.createHash("sha256").update(JSON.stringify({ schema: 1, modelId, run: publicModelRunId(definition, run), product, forecastHour, bounds, width, encoding })).digest("hex").slice(0, 24);
  const cacheDir = path.join(dataDir, "generated", "public-model-grid-v1"), cachePath = path.join(cacheDir, `${identity}.bin`);
  fs.mkdirSync(cacheDir, { recursive: true });
  if (fs.existsSync(cachePath) && fs.statSync(cachePath).size > 200) return { buffer: fs.readFileSync(cachePath), modifiedAt: fs.statSync(cachePath).mtime };
  if (publicConusGridJobs.has(identity)) return publicConusGridJobs.get(identity);
  const job = (async () => {
    const project = webMercatorMapProjection(bounds, width, height, 0), stem = `wrf-grid-v1-${identity}`;
    const raster = await renderNcepModelField(product, run.run, forecastHour, { bbox: bounds }, project, stem);
    const rawPath = path.join(cacheDir, `${identity}.raw`);
    await runWeatherMapCommand("gdalwarp", ["-overwrite", "-q", "-t_srs", "EPSG:3857", "-te", String(minX), String(minY), String(maxX), String(maxY), "-te_srs", "EPSG:3857", "-ts", String(width), String(height), "-r", encoding.resampling, "-srcnodata", "-9999", "-dstnodata", "-9999", "-wo", "UNIFIED_SRC_NODATA=YES", "-ot", "Float32", "-of", "ENVI", "-co", "INTERLEAVE=BSQ", raster.tifPath, rawPath]);
    const floats = fs.readFileSync(rawPath), bytesPerSample = encoding.sampleType === "float32" ? 4 : 2, samples = Buffer.allocUnsafe(width * height * bytesPerSample);
    let physicalMinimum = Infinity, physicalMaximum = -Infinity, missingCount = 0;
    for (let index = 0; index < width * height; index += 1) {
      const value = floats.readFloatLE(index * 4);
      if (!Number.isFinite(value) || value <= -9000) { if (encoding.sampleType === "float32") samples.writeFloatLE(-9999, index * 4); else samples.writeUInt16LE(65535, index * 2); missingCount += 1; continue; }
      if (encoding.sampleType === "float32") { samples.writeFloatLE(value, index * 4); physicalMinimum = Math.min(physicalMinimum, value); physicalMaximum = Math.max(physicalMaximum, value); continue; }
      const raw = Math.max(0, Math.min(65534, Math.round((value - encoding.offset) / encoding.scale)));
      samples.writeUInt16LE(raw, index * 2); const reconstructed = raw * encoding.scale + encoding.offset;
      physicalMinimum = Math.min(physicalMinimum, reconstructed); physicalMaximum = Math.max(physicalMaximum, reconstructed);
    }
    const compressed = zlib.deflateSync(samples, { level: 6 }), metadata = {
      schemaVersion: 1, model: modelId, run: publicModelRunId(definition, run), product, domain: run.domain,
      forecastHour, validTime: new Date(Date.parse(run.runTime) + forecastHour * 3_600_000).toISOString(), width, height,
      projection: "EPSG:3857", bounds, mercatorBounds: [minX, minY, maxX, maxY], sampleType: encoding.sampleType, byteOrder: "little-endian",
      scale: encoding.scale, offset: encoding.offset, missingValue: encoding.missingValue, unit: encoding.unit, rowOrder: "north-to-south", columnOrder: "west-to-east",
      resampling: encoding.resampling, compression: "deflate", uncompressedBytes: samples.length,
      physicalMinimum: Number.isFinite(physicalMinimum) ? physicalMinimum : null, physicalMaximum: Number.isFinite(physicalMaximum) ? physicalMaximum : null, missingCount
    };
    const json = Buffer.from(JSON.stringify(metadata)), headerLength = 16 + json.length, header = Buffer.allocUnsafe(16);
    header.write("ZASGRID\0", 0, 8, "ascii"); header.writeUInt16LE(1, 8); header.writeUInt16LE(0xFEFF, 10); header.writeUInt32LE(headerLength, 12);
    const output = Buffer.concat([header, json, compressed]), temporary = `${cachePath}.${process.pid}.${Date.now()}.tmp`;
    fs.writeFileSync(temporary, output); fs.renameSync(temporary, cachePath);
    for (const candidate of [rawPath, rawPath.replace(/\.raw$/, ".hdr"), `${rawPath}.aux.xml`]) try { fs.unlinkSync(candidate); } catch {}
    return { buffer: output, modifiedAt: fs.statSync(cachePath).mtime };
  })().finally(() => publicConusGridJobs.delete(identity));
  publicConusGridJobs.set(identity, job); return job;
}

async function renderPublicHafsGrid(modelId, definition, run, requestedProduct, forecastHour, domain, component = "") {
  if (!["hafs-a", "hafs-b"].includes(modelId) || !["storm", "parent"].includes(domain)) throw Object.assign(new Error("Invalid HAFS numerical grid"), { status: 404 });
  const product = requestedProduct === "refcmslp" ? (component === "pressure" ? "pressure" : "refc") : requestedProduct;
  const encoding = publicHafsGridProducts[product];
  if (!encoding) throw Object.assign(new Error("HAFS numerical product is unavailable"), { status: 404 });
  const bounds = publicHafsFrameBounds(run, forecastHour, requestedProduct, domain), width = domain === "storm" ? 2048 : 4096;
  const [minX, minY] = webMercatorPoint(bounds[0], bounds[1]), [maxX, maxY] = webMercatorPoint(bounds[2], bounds[3]);
  const height = Math.max(256, Math.min(4096, Math.round(width * (maxY - minY) / Math.max(1, maxX - minX))));
  const identity = crypto.createHash("sha256").update(JSON.stringify({ schema: 1, modelId, run: publicModelRunId(definition, run), requestedProduct, product, component, forecastHour, domain, bounds, width, encoding })).digest("hex").slice(0, 24);
  const cacheDir = path.join(dataDir, "generated", "public-model-grid-v1"), cachePath = path.join(cacheDir, `${identity}.bin`);
  fs.mkdirSync(cacheDir, { recursive: true });
  if (fs.existsSync(cachePath) && fs.statSync(cachePath).size > 200) return { buffer: fs.readFileSync(cachePath), modifiedAt: fs.statSync(cachePath).mtime };
  if (publicConusGridJobs.has(identity)) return publicConusGridJobs.get(identity);
  const job = (async () => {
    const project = webMercatorMapProjection(bounds, width, height, 0), stem = `hafs-grid-v1-${identity}`;
    const raster = await renderHafsModelField(definition.source, run.stormId, domain, product, run.run, forecastHour, { bbox: bounds }, project, stem);
    const rawPath = path.join(cacheDir, `${identity}.raw`);
    await runWeatherMapCommand("gdalwarp", ["-overwrite", "-q", "-t_srs", "EPSG:3857", "-te", String(minX), String(minY), String(maxX), String(maxY), "-te_srs", "EPSG:3857", "-ts", String(width), String(height), "-r", encoding.resampling, "-srcnodata", "-9999", "-dstnodata", "-9999", "-wo", "UNIFIED_SRC_NODATA=YES", "-ot", "Float32", "-of", "ENVI", "-co", "INTERLEAVE=BSQ", raster.tifPath, rawPath]);
    const floats = fs.readFileSync(rawPath), samples = Buffer.allocUnsafe(width * height * 2);
    let physicalMinimum = Infinity, physicalMaximum = -Infinity, missingCount = 0;
    for (let index = 0; index < width * height; index += 1) {
      const value = floats.readFloatLE(index * 4);
      if (!Number.isFinite(value) || value <= -9000) { samples.writeUInt16LE(65535, index * 2); missingCount += 1; continue; }
      const raw = Math.max(0, Math.min(65534, Math.round((value - encoding.offset) / encoding.scale)));
      samples.writeUInt16LE(raw, index * 2); const reconstructed = raw * encoding.scale + encoding.offset;
      physicalMinimum = Math.min(physicalMinimum, reconstructed); physicalMaximum = Math.max(physicalMaximum, reconstructed);
    }
    const compressed = zlib.deflateSync(samples, { level: 6 }), metadata = {
      schemaVersion: 1, model: modelId, run: publicModelRunId(definition, run), sourceRun: run.run, storm: { id: run.stormId, name: run.stormName },
      product: requestedProduct, component: product, domain, forecastHour, validTime: new Date(Date.parse(run.runTime) + forecastHour * 3_600_000).toISOString(),
      width, height, projection: "EPSG:3857", bounds, mercatorBounds: [minX, minY, maxX, maxY], sampleType: "uint16", byteOrder: "little-endian",
      scale: encoding.scale, offset: encoding.offset, missingValue: 65535, unit: encoding.unit, rowOrder: "north-to-south", columnOrder: "west-to-east",
      resampling: encoding.resampling, compression: "deflate", uncompressedBytes: samples.length,
      physicalMinimum: Number.isFinite(physicalMinimum) ? physicalMinimum : null, physicalMaximum: Number.isFinite(physicalMaximum) ? physicalMaximum : null, missingCount
    };
    const json = Buffer.from(JSON.stringify(metadata)), headerLength = 16 + json.length, header = Buffer.allocUnsafe(16);
    header.write("ZASGRID\0", 0, 8, "ascii"); header.writeUInt16LE(1, 8); header.writeUInt16LE(0xFEFF, 10); header.writeUInt32LE(headerLength, 12);
    const output = Buffer.concat([header, json, compressed]), temporary = `${cachePath}.${process.pid}.${Date.now()}.tmp`;
    fs.writeFileSync(temporary, output); fs.renameSync(temporary, cachePath);
    for (const candidate of [rawPath, rawPath.replace(/\.raw$/, ".hdr"), `${rawPath}.aux.xml`]) try { fs.unlinkSync(candidate); } catch {}
    return { buffer: output, modifiedAt: fs.statSync(cachePath).mtime };
  })().finally(() => publicConusGridJobs.delete(identity));
  publicConusGridJobs.set(identity, job); return job;
}

async function handlePublicModelV1(request, requestUrl, response) {
  if (!["GET", "HEAD"].includes(request.method) || !requestUrl.pathname.startsWith("/v1/")) return false;
  if (requestUrl.pathname === "/v1/openapi.json") {
    const file = path.join(__dirname, "models-openapi.json"), stat = fs.statSync(file);
    sendPublicModelApi(request, response, 200, fs.readFileSync(file), { contentType: "application/json; charset=utf-8", modifiedAt: stat.mtime, cacheControl: "public, max-age=300" }); return true;
  }
  if (requestUrl.pathname === "/v1/models") {
    const models = Object.entries(publicModelDefinitions).map(([id, definition]) => ({ id, displayName: definition.name, runsUrl: `/v1/models/${id}/runs` }));
    sendPublicModelApi(request, response, 200, { schemaVersion: publicModelApiSchemaVersion, models }); return true;
  }
  const parts = requestUrl.pathname.split("/").filter(Boolean);
  if (parts[0] !== "v1" || parts[1] !== "models" || !parts[2]) return false;
  try {
    const modelId = decodeURIComponent(parts[2]), { definition, runs } = await publicModelCatalog(modelId);
    if (parts.length === 4 && parts[3] === "runs") {
      sendPublicModelApi(request, response, 200, { schemaVersion: publicModelApiSchemaVersion, model: modelId, runs: runs.map((run) => publicModelRunRecord(definition, run)) }); return true;
    }
    const run = parts[3] ? findPublicModelRun(definition, runs, parts[3]) : null;
    if (!run) throw Object.assign(new Error("Model run not found"), { status: 404 });
    const products = publicModelProductDefinitions(definition, run);
    if (parts.length === 5 && parts[4] === "products") {
      sendPublicModelApi(request, response, 200, { schemaVersion: publicModelApiSchemaVersion, model: modelId, run: publicModelRunRecord(definition, run), products: products.map(([id, config]) => publicModelProductRecord(modelId, definition, run, id, config)) }); return true;
    }
    const productId = decodeURIComponent(parts[4] || ""), productEntry = products.find(([id]) => id === productId);
    if (!productEntry) throw Object.assign(new Error("Model product not found"), { status: 404 });
    const product = publicModelProductRecord(modelId, definition, run, productEntry[0], productEntry[1]);
    if (parts.length === 6 && parts[5] === "frames") {
      const initialized = Date.parse(run.runTime);
      const frames = product.forecastHours.map((forecastHour) => ({ forecastHour, validTime: new Date(initialized + forecastHour * 3_600_000).toISOString(), overlayUrl: product.overlayTemplate.replace("{forecastHour}", encodeURIComponent(forecastHour)), ...(product.gridTemplate ? { gridUrl: product.gridTemplate.replace("{forecastHour}", encodeURIComponent(forecastHour)) } : {}), ...(product.gridDomains ? { gridUrls: Object.fromEntries(Object.entries(product.gridDomains).filter(([, value]) => value).map(([domain, value]) => [domain, value.replace("{forecastHour}", encodeURIComponent(forecastHour))])) } : {}), ...(product.gridComponents ? { gridComponents: Object.fromEntries(Object.entries(product.gridComponents).map(([componentName, domains]) => [componentName, Object.fromEntries(Object.entries(domains).map(([domain, value]) => [domain, value.replace("{forecastHour}", encodeURIComponent(forecastHour))]))])) } : {}), ...(product.pressureForecastHours?.includes(forecastHour) && product.pressureGridTemplate ? { pressureGridUrl: product.pressureGridTemplate.replace("{forecastHour}", encodeURIComponent(forecastHour)) } : {}), ...(product.pressureForecastHours?.includes(forecastHour) && product.pressureGridTemplates ? { pressureGridUrls: Object.fromEntries(Object.entries(product.pressureGridTemplates).map(([domain, value]) => [domain, value.replace("{forecastHour}", encodeURIComponent(forecastHour))])) } : {}) }));
      sendPublicModelApi(request, response, 200, { schemaVersion: publicModelApiSchemaVersion, model: modelId, run: publicModelRunRecord(definition, run), product, frames }); return true;
    }
    if (parts.length === 7 && parts[6] === "overlay.png") {
      const forecastHour = Number(parts[5]);
      if (!product.forecastHours.includes(forecastHour)) throw Object.assign(new Error("Forecast frame not found"), { status: 404 });
      const bbox = String(requestUrl.searchParams.get("bbox") || "").split(",").map(Number), width = Number(requestUrl.searchParams.get("width") || 0);
      if (bbox.length !== 4 || !bbox.every(Number.isFinite) || bbox[0] >= bbox[2] || bbox[1] >= bbox[3] || bbox[0] < -180 || bbox[2] > 180 || bbox[1] < -85 || bbox[3] > 85 || !Number.isInteger(width) || width < 64 || width > 4096) throw Object.assign(new Error("bbox must be west,south,east,north and width must be 64–4096"), { status: 400 });
      const rendered = await renderPublicModelApiOverlay(modelId, definition, run, productId, forecastHour, bbox, width);
      sendPublicModelApi(request, response, 200, rendered.buffer, { contentType: "image/png", modifiedAt: rendered.modifiedAt, cacheControl: "public, max-age=31536000, immutable" }); return true;
    }
    if (parts.length === 8 && parts[6] === "grid" && parts[7] === "conus.bin") {
      const forecastHour = Number(parts[5]);
      if (!product.forecastHours.includes(forecastHour)) throw Object.assign(new Error("Forecast frame not found"), { status: 404 });
      const rendered = await renderPublicConusGrid(modelId, definition, run, productId, forecastHour);
      sendPublicModelApi(request, response, 200, rendered.buffer, { contentType: "application/vnd.zasnet.model-grid", modifiedAt: rendered.modifiedAt, cacheControl: "public, max-age=31536000, immutable" }); return true;
    }
    if (parts.length === 8 && parts[6] === "grid" && parts[7] === "domain.bin") {
      const forecastHour = Number(parts[5]);
      if (!modelId.startsWith("znws-wrf-") || !product.forecastHours.includes(forecastHour)) throw Object.assign(new Error("Forecast numerical frame not found"), { status: 404 });
      const rendered = await renderPublicWrfGrid(modelId, definition, run, productId, productEntry[1], forecastHour);
      sendPublicModelApi(request, response, 200, rendered.buffer, { contentType: "application/vnd.zasnet.model-grid", modifiedAt: rendered.modifiedAt, cacheControl: "public, max-age=31536000, immutable" }); return true;
    }
    if (parts.length === 8 && parts[6] === "grid" && ["storm.bin", "parent.bin"].includes(parts[7])) {
      const forecastHour = Number(parts[5]), domain = parts[7].replace(".bin", ""), component = String(requestUrl.searchParams.get("component") || "");
      if (!product.forecastHours.includes(forecastHour)) throw Object.assign(new Error("Forecast frame not found"), { status: 404 });
      const rendered = await renderPublicHafsGrid(modelId, definition, run, productId, forecastHour, domain, component);
      sendPublicModelApi(request, response, 200, rendered.buffer, { contentType: "application/vnd.zasnet.model-grid", modifiedAt: rendered.modifiedAt, cacheControl: "public, max-age=31536000, immutable" }); return true;
    }
    throw Object.assign(new Error("Model API resource not found"), { status: 404 });
  } catch (error) {
    sendPublicModelApi(request, response, Number(error.status) || 502, { schemaVersion: publicModelApiSchemaVersion, error: error.message || "Model API unavailable" }, { cacheControl: "no-store" }); return true;
  }
}

async function handleApi(request, response) {
  const session = getSession(request);
  const requestUrl = new URL(request.url || "/", `http://${request.headers.host || "localhost"}`);
  if (!publicServerMode) syncTemporaryMapRegions();

  if (await handlePublicModelV1(request, requestUrl, response)) return true;

  if (request.method === "OPTIONS" && (requestUrl.pathname.startsWith("/api/public/") || requestUrl.pathname.startsWith("/v1/"))) {
    response.writeHead(204, {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, HEAD, OPTIONS",
      "Access-Control-Allow-Headers": "Accept, Content-Type",
      "Access-Control-Max-Age": "86400"
    });
    response.end();
    return true;
  }

  // Webpage OIDC (ops) — no NPM header forwarding required
  if (request.method === "GET" && requestUrl.pathname === "/auth/login") {
    return handleOidcLogin(request, response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/auth/callback") {
    return handleOidcCallback(request, response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/auth/logout") {
    return handleOidcLogout(request, response);
  }

  // Always allow session (UI needs it even when logged out)
  if (request.method === "GET" && requestUrl.pathname === "/api/session") {
    const { _idToken, ...publicSession } = session;
    sendJson(response, 200, {
      ...publicSession,
      canViewAccessAudit: canViewAccessAudit(session),
      canAdministerHazardTemplates: canAdministerHazardTemplates(session)
    });
    return true;
  }

  // Electron/native workstations exchange their bearer credential once for the
  // normal signed session cookie. The bearer token never reaches app.js.
  if (request.method === "POST" && requestUrl.pathname === "/api/desktop/session") {
    const authorization = String(getHeader(request, "authorization") || "");
    const match = authorization.match(/^Bearer\s+(hive_native_[A-Za-z0-9_-]{32,})$/i);
    const workstation = match ? nativeWorkstationFromToken(match[1]) : null;
    if (!workstation) {
      try { recordAccessEvent(request, { authenticated: false, username: "desktop-workstation", displayName: "Desktop Workstation", groups: [], via: "workstation" }, "desktop-workstation-auth-failed"); } catch { /* preserve response */ }
      sendJson(response, 401, { error: "Workstation credential is invalid, disabled, or revoked", authMethod: "workstation" });
      return true;
    }
    let requestedWfo = "";
    try {
      const payload = JSON.parse((await readRequestBody(request)) || "{}");
      requestedWfo = String(payload.wfo || "").trim().toUpperCase().slice(0, 8);
    } catch { /* optional body */ }
    if (requestedWfo && workstation.wfos.length && !workstation.wfos.includes(requestedWfo) && !workstation.wfos.includes("ALL")) {
      try { recordAccessEvent(request, { ...workstation, authenticated: false }, "desktop-workstation-wfo-denied", { warningWfo: requestedWfo }); } catch { /* preserve response */ }
      sendJson(response, 403, { error: "Workstation is not authorized for the requested WFO", authMethod: "workstation", wfos: workstation.wfos });
      return true;
    }
    const sessionPayload = {
      u: workstation.username,
      n: workstation.displayName,
      sub: workstation.workstationId,
      g: workstation.groups.slice(0, 24),
      via: "workstation",
      workstation_id: workstation.workstationId,
      workstation_name: workstation.workstationName,
      workstation_wfo: requestedWfo || workstation.workstationWfo,
      workstation_wfos: workstation.wfos,
      exp: Math.floor(Date.now() / 1000) + sessionTtlSeconds
    };
    setCookie(response, sessionCookieName, signPayload(sessionPayload), { maxAge: sessionTtlSeconds });
    try { recordAccessEvent(request, { ...workstation, authenticated: true }, "desktop-workstation-session", { warningWfo: requestedWfo || workstation.workstationWfo }); } catch { /* session remains valid */ }
    sendJson(response, 200, {
      authenticated: true,
      authMethod: "workstation",
      workstation: { id: workstation.workstationId, name: workstation.workstationName, wfos: workstation.wfos },
      expiresAt: new Date((Date.now() + sessionTtlSeconds * 1000)).toISOString()
    });
    return true;
  }

  if (request.method === "POST" && requestUrl.pathname === "/api/native/enroll") {
    const peer = String(getHeader(request, "x-forwarded-for") || request.socket?.remoteAddress || "unknown").split(",")[0].trim();
    const now = Date.now();
    const recent = (nativeEnrollmentAttempts.get(peer) || []).filter((time) => now - time < 10 * 60_000);
    if (recent.length >= 20) {
      sendJson(response, 429, { error: "Too many enrollment attempts; try again later" });
      return true;
    }
    recent.push(now);
    nativeEnrollmentAttempts.set(peer, recent);
    try {
      const payload = JSON.parse((await readRequestBody(request)) || "{}");
      const code = String(payload.code || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
      const requestedName = String(payload.deviceName || "").trim().replace(/[\u0000-\u001f\u007f]/g, " ").slice(0, 80);
      if (code.length < 10) throw new Error("Enter the complete enrollment code");
      const store = loadNativeWorkstations();
      store.pending = store.pending.filter((entry) => Number(entry.expiresAt) > now);
      const codeHash = nativeSecretHash(code);
      const pendingIndex = store.pending.findIndex((entry) => {
        if (typeof entry.codeHash !== "string" || entry.codeHash.length !== 64) return false;
        return crypto.timingSafeEqual(Buffer.from(entry.codeHash, "hex"), Buffer.from(codeHash, "hex"));
      });
      if (pendingIndex < 0) {
        saveNativeWorkstations(store);
        sendJson(response, 403, { error: "Enrollment code is invalid or expired" });
        return true;
      }
      const pending = store.pending.splice(pendingIndex, 1)[0];
      const deviceId = `native-${crypto.randomBytes(9).toString("base64url")}`;
      const token = `hive_native_${crypto.randomBytes(32).toString("base64url")}`;
      const enrolledAt = new Date().toISOString();
      const device = {
        id: deviceId,
        name: requestedName || pending.name || "Hive Native Workstation",
        wfo: pending.wfo || "",
        wfos: Array.isArray(pending.wfos) ? pending.wfos : pending.wfo ? [pending.wfo] : [],
        tokenHash: nativeSecretHash(token),
        createdAt: enrolledAt,
        createdBy: pending.createdBy,
        lastSeenAt: enrolledAt,
        revokedAt: null
      };
      store.devices.push(device);
      saveNativeWorkstations(store);
      try { recordAccessEvent(request, { authenticated: true, username: `workstation:${deviceId}`, displayName: device.name, uid: deviceId, groups: ["hive-native-workstation"], via: "native-device" }, "native-workstation-enrolled"); } catch { /* enrollment remains valid */ }
      sendJson(response, 201, { token, device: { id: device.id, name: device.name, createdAt: device.createdAt } });
    } catch (error) {
      sendJson(response, 400, { error: error.message || "Invalid enrollment request" });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/public/map-regions.json") {
    const store = loadTemporaryMapRegions({ activeOnly: true });
    sendJson(response, 200, { updatedAt: store.updatedAt, regions: store.regions });
    return true;
  }

  // Ops-only gate when OIDC is configured + require auth
  if (
    authentikRequireAuth &&
    oidcEnabled &&
    !session.authenticated &&
    !isPublicUnauthenticatedPath(requestUrl.pathname, request)
  ) {
    sendJson(response, 401, {
      error: "Authentication required",
      loginUrl: "/auth/login",
      logoutUrl: "/auth/logout",
      hint: "Open /auth/login to sign in with Authentik (OIDC)",
      headersPresent: session.headersPresent,
      sso: session.sso
    });
    return true;
  }

  // AWIPS OUP adapter: preview first; publishes only when AWIPS_PUBLISH_ENABLED=true.
  if (request.method === "POST" && requestUrl.pathname === "/api/awips/products") {
    try {
      const payload = JSON.parse((await readRequestBody(request)) || "{}");
      if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
        sendJson(response, 400, { error: "Expected a JSON object" });
        return true;
      }
      if (typeof payload.rawText !== "string" || !payload.rawText.trim()) {
        sendJson(response, 400, { error: "rawText must be a non-empty string" });
        return true;
      }
      if (payload.receivedAt !== undefined && (!Number.isFinite(Date.parse(String(payload.receivedAt))))) {
        sendJson(response, 400, { error: "receivedAt must be a valid ISO-8601 timestamp" });
        return true;
      }
      if (payload.source !== undefined && String(payload.source).toLowerCase() !== "edex") {
        sendJson(response, 400, { error: "source must be edex" });
        return true;
      }
      const preview = parseAwipsProduct({
        rawText: payload.rawText,
        receivedAt: payload.receivedAt,
        source: payload.source || "edex",
        site: payload.site,
        dataDir,
        formatProductId: formatProductIdPublic
      });
      const publication = await attemptAwipsPublication(preview, {
        publishEnabled: awipsPublishEnabled,
        publishEvent: async (event) => publishGfeWarningEvent(event, session, request, { requestPath: "/api/awips/products" })
      });
      const responsePayload = {
        accepted: true,
        preview,
        published: Boolean(publication.published)
      };
      if (publication.published) {
        if (publication.publishedResult?.distribution) {
          responsePayload.distribution = publication.publishedResult.distribution;
        }
        if (publication.publishedResult?.updatedAt) {
          responsePayload.updatedAt = publication.publishedResult.updatedAt;
        }
      } else if (publication.reason && publication.reason !== "disabled" && publication.reason !== "unsupported-product" && publication.reason !== "unmappable-product" && publication.reason !== "publish-function-missing") {
        responsePayload.publicationError = publication.error || "AWIPS publication failed";
      }
      sendJson(response, 200, responsePayload);
    } catch (error) {
      const status = /JSON|rawText|receivedAt|source|Unsupported|no WMO|8 MB/i.test(String(error.message || "")) ? 422 : 400;
      sendJson(response, status, { accepted: false, published: false, error: error.message || "Unable to parse AWIPS product" });
    }
    return true;
  }

  if (requestUrl.pathname === "/ncep") {
    response.writeHead(308, { Location: `/ncep/${requestUrl.search}`, "Cache-Control": "no-store" });
    response.end();
    return true;
  }
  if (requestUrl.pathname.startsWith("/ncep/")) {
    return proxyNcepRequest(request, requestUrl, response);
  }

  const nativeBasemapMatch = requestUrl.pathname.match(/^\/api\/native\/basemap\/(\d+)\/(\d+)\/(\d+)\.png$/);
  if (request.method === "GET" && nativeBasemapMatch) {
    const zoom = Number(nativeBasemapMatch[1]);
    const tileX = Number(nativeBasemapMatch[2]);
    const tileY = Number(nativeBasemapMatch[3]);
    const limit = 2 ** zoom;
    if (!Number.isInteger(zoom) || zoom < 0 || zoom > 18 || !Number.isInteger(tileX) || !Number.isInteger(tileY) || tileX < 0 || tileY < 0 || tileX >= limit || tileY >= limit) {
      sendJson(response, 400, { error: "Invalid native basemap tile" });
      return true;
    }
    return proxyHttpsGet(`https://a.basemaps.cartocdn.com/light_all/${zoom}/${tileX}/${tileY}.png`, response, {
      cacheControl: "private, max-age=86400"
    });
  }

  // Some WRF dashboard builds construct approval URLs dynamically as
  // root-relative `/api/admin/...` paths. Bridge only these two operator
  // actions so POST method, body, content type, and upstream response pass
  // through unchanged instead of falling into the local static-file 404.
  if (
    request.method === "POST" &&
    /^\/api\/admin\/requests\/[^/]+\/(?:approve|deny)$/.test(requestUrl.pathname)
  ) {
    const proxyUrl = new URL(requestUrl);
    proxyUrl.pathname = `/ncep${requestUrl.pathname}`;
    return proxyNcepRequest(request, proxyUrl, response);
  }

  if (request.method === "GET" && requestUrl.pathname.startsWith("/api/public/outlooks/spc/static/")) {
    return handlePublicSpcOutlookImage(requestUrl, response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/models/hrrr/latest.json") {
    return handlePublicHrrrModelCatalog(response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/models/gfs/latest.json") {
    return handlePublicGfsModelCatalog(response);
  }
  if (request.method === "GET" && ["/api/public/models/native-latest.png", "/api/public/models/native-latest.webp"].includes(requestUrl.pathname)) {
    return handleNativeLatestModelImage(request, requestUrl, response);
  }
  if(request.method==="GET"&&["/api/public/models/hfsa/latest.json","/api/public/models/hfsb/latest.json"].includes(requestUrl.pathname))return handlePublicHafsModelCatalog(requestUrl.pathname.includes("hfsb")?"hfsb":"hfsa",response);
  if (request.method === "GET" && ["/api/ops/models/overlay.png", "/api/ops/models/overlay.svg"].includes(requestUrl.pathname)) {
    return handleOpsModelOverlay(requestUrl, response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/models/ncep/latest.json") {
    return handlePublicNcepModelCatalog(response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/models/status.json") {
    return handlePublicModelStatus(response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/models/operations-update.json") {
    sendJson(response, 200, await buildPublicWrfOperationsUpdate());
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/models/ncep/product-legends.json") {
    sendJson(response, 200, { products: publicWrfProductLegends(), generatedAt: new Date().toISOString() });
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/models/operations-map.svg") {
    const update = await buildPublicWrfOperationsUpdate();
    response.writeHead(200, { "Content-Type": "image/svg+xml; charset=utf-8", "Cache-Control": "no-store" });
    response.end(renderPublicWrfOperationsMapSvg(update.visible ? update.sectors : []));
    return true;
  }
  if(request.method==="GET"&&requestUrl.pathname==="/api/public/criteria-map.svg"){
    try{
      const hazard=String(requestUrl.searchParams.get("hazard")||""),metric=String(requestUrl.searchParams.get("metric")||"");
      const svg=renderPublicCriteriaMapSvg(hazard,metric);
      response.writeHead(200,{"Content-Type":"image/svg+xml; charset=utf-8","Cache-Control":"no-store, no-cache, must-revalidate, max-age=0"});response.end(svg);
    }catch(error){sendJson(response,Number(error.status)||400,{error:error.message});}
    return true;
  }
  if(request.method==="GET"&&requestUrl.pathname==="/api/public/criteria-map.png"){
    try{
      const hazard=String(requestUrl.searchParams.get("hazard")||""),metric=String(requestUrl.searchParams.get("metric")||""),png=await renderPublicCriteriaMapPng(hazard,metric);
      response.writeHead(200,{"Content-Type":"image/png","Content-Length":png.length,"Cache-Control":"no-store, no-cache, must-revalidate, max-age=0"});response.end(png);
    }catch(error){sendJson(response,Number(error.status)||400,{error:error.message});}
    return true;
  }
  if (request.method === "GET" && ["/api/public/models/hrrr/composite.svg", "/api/public/models/hrrr/map.svg", "/api/public/models/hrrr/map.webp"].includes(requestUrl.pathname)) {
    return handlePublicHrrrModelImage(request, requestUrl, response);
  }
  if (request.method === "GET" && ["/api/public/models/gfs/map.svg", "/api/public/models/gfs/map.webp"].includes(requestUrl.pathname)) {
    return handlePublicGfsModelImage(request, requestUrl, response);
  }
  if(request.method==="GET"&&["/api/public/models/hfsa/map.webp","/api/public/models/hfsb/map.webp"].includes(requestUrl.pathname))return handlePublicHafsModelImage(requestUrl.pathname.includes("hfsb")?"hfsb":"hfsa",request,requestUrl,response);
  if (request.method === "GET" && ["/api/public/models/ncep/map.svg", "/api/public/models/ncep/map.webp"].includes(requestUrl.pathname)) {
    return handlePublicNcepModelImage(request,requestUrl,response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/maps/ndfd-times.json") {
    return handlePublicNdfdTimes(requestUrl, response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/maps/ndfd-value.json") {
    return handlePublicNdfdValue(requestUrl, response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/maps/value.json") {
    return handlePublicWeatherMapValue(requestUrl, response);
  }
  if (request.method === "GET" && requestUrl.pathname.startsWith("/api/public/maps/static/") && requestUrl.pathname.endsWith(".status.json")) {
    return handlePublicWeatherMapStatus(requestUrl, response);
  }
  if (request.method === "GET" && requestUrl.pathname.startsWith("/api/public/maps/static/")) {
    return handlePublicWpcMapImage(requestUrl, response);
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/public/location-search") {
    const query = String(requestUrl.searchParams.get("q") || "").trim();
    if (query.length < 2) {
      sendJson(response, 400, { error: "Enter a ZIP code or city name" });
      return true;
    }
    try {
      sendJson(response, 200, { query, results: await searchPublicLocations(query) });
    } catch (error) {
      sendJson(response, 502, { error: "Location search is temporarily unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/system/health") {
    sendJson(response, 200, await buildSystemHealth());
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/system/model-retention") {
    try {
      sendJson(response, 200, JSON.parse(fs.readFileSync(path.join(dataDir, "model-retention-status.json"), "utf8")));
    } catch {
      sendJson(response, 200, { generatedAt: null, policy: { retainedRuns: 3 }, sources: { hrrr: [], gfs: [], wrf: [] }, totalBytes: 0 });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/system/model-prewarm") {
    try {
      sendJson(response, 200, JSON.parse(fs.readFileSync(modelPrewarmStatusFile, "utf8")));
    } catch {
      sendJson(response, 200, { running: false, total: 0, queued: 0, processed: 0, failed: 0, deferred: 0, cooldowns: 0, updatedAt: null });
    }
    return true;
  }

  if (request.method === "POST" && requestUrl.pathname === "/api/hydrography/named-rivers") {
    try {
      const payload = JSON.parse(await readRequestBody(request));
      if (!validAdvisoryPolygon(payload.geometry)) {
        sendJson(response, 400, { error: "A valid advisory Polygon or MultiPolygon is required" });
        return true;
      }
      const names = await queryNamedThreeDhpRivers(payload.geometry);
      sendJson(response, 200, { names, source: "USGS 3D Hydrography Program" });
    } catch (error) {
      sendJson(response, 502, { error: "Named river lookup is temporarily unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/hydrography/flowlines") {
    const bbox = String(requestUrl.searchParams.get("bbox") || "").split(",").map(Number);
    const minOrder = Math.max(1, Math.min(6, Number(requestUrl.searchParams.get("minOrder")) || 3));
    if (bbox.length !== 4 || !bbox.every(Number.isFinite) ||
        bbox[0] < -180 || bbox[2] > 180 || bbox[1] < -90 || bbox[3] > 90 ||
        bbox[0] >= bbox[2] || bbox[1] >= bbox[3]) {
      sendJson(response, 400, { error: "A valid west,south,east,north bbox is required" });
      return true;
    }
    try {
      const dataset = requestUrl.searchParams.get("dataset") === "small" ? "small" : "detail";
      const flowlines = dataset === "small"
        ? await queryNhdSmallScaleFlowlines(bbox)
        : await queryThreeDhpFlowlines(bbox, minOrder);
      response.writeHead(200, {
        "Content-Type": "application/geo+json; charset=utf-8",
        "Cache-Control": "public, max-age=300"
      });
      response.end(JSON.stringify(flowlines));
    } catch (error) {
      sendJson(response, 502, { error: "River and stream layer is temporarily unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/access/audit") {
    if (!canViewAccessAudit(session)) {
      try { recordAccessEvent(request, session, "audit-access-denied", { page: requestUrl.pathname }); } catch { /* preserve denial */ }
      sendJson(response, 403, { error: "Access audit permission required" });
      return true;
    }
    const limit = Math.min(1000, Math.max(1, Number(requestUrl.searchParams.get("limit")) || 250));
    sendJson(response, 200, { entries: readAccessAudit(limit), limit });
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/access/audit/warning-text") {
    if (!canViewAccessAudit(session)) {
      try { recordAccessEvent(request, session, "audit-access-denied", { page: requestUrl.pathname }); } catch { /* preserve denial */ }
      sendJson(response, 403, { error: "Access audit permission required" });
      return true;
    }
    const productId = auditText(requestUrl.searchParams.get("productId"), 160);
    const action = auditText(requestUrl.searchParams.get("action"), 20).toUpperCase();
    const entries = loadWarningAuditLog().entries || [];
    const exact = entries.find((entry) => String(entry.productId || "") === productId && (!action || String(entry.action || "").toUpperCase() === action));
    const fallback = entries.find((entry) => String(entry.productId || "") === productId);
    const productEntries = [
      ...(loadPublicAlerts().warnings || []),
      ...(loadOpsProducts().warnings || [])
    ];
    const productExact = productEntries.find((entry) => String(entry.productId || "") === productId && (!action || String(entry.action || "").toUpperCase() === action));
    const productFallback = productEntries.find((entry) => String(entry.productId || "") === productId);
    const warning = exact || fallback || productExact || productFallback;
    if (!warning?.text) {
      response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
      response.end("Stored warning text was not found.\n");
      return true;
    }
    response.writeHead(200, {
      "Content-Type": "text/plain; charset=utf-8",
      "Content-Disposition": `inline; filename="${String(productId || "warning").replace(/[^A-Z0-9_-]/gi, "")}.txt"`,
      "Cache-Control": "no-store, max-age=0",
      "X-Content-Type-Options": "nosniff"
    });
    response.end(`${String(warning.text).trim()}\n`);
    return true;
  }

  if (request.method === "POST" && requestUrl.pathname === "/api/access/acknowledge") {
    try {
      const recordedAt = recordAccessAcknowledgement(request, session);
      sendJson(response, 201, { recorded: true, recordedAt });
    } catch (error) {
      console.error("[access-audit] Could not record acknowledgement:", error.message);
      sendJson(response, 500, { error: "Could not record access acknowledgement" });
    }
    return true;
  }

  if (request.method === "POST" && requestUrl.pathname === "/api/access/activity") {
    try {
      const payload = JSON.parse((await readRequestBody(request)) || "{}");
      const allowedEvents = new Set(["page-view", "tool-open", "heartbeat", "page-exit"]);
      const event = allowedEvents.has(payload.event) ? payload.event : "activity";
      const recordedAt = recordAccessEvent(request, session, event, payload);
      sendJson(response, 201, { recorded: true, recordedAt });
    } catch (error) {
      console.error("[access-audit] Could not record activity:", error.message);
      sendJson(response, 400, { error: "Could not record access activity" });
    }
    return true;
  }

  if (request.method === "POST" && requestUrl.pathname === "/api/radar/cache") {
    return handleRadarCacheRequest(request, response);
  }

  if (request.method === "POST" && requestUrl.pathname === "/api/radar/product") {
    return handleRadarProductRequest(request, response);
  }

  // MRMS MESH must be registered *before* the generic /api/radar/ catch-all
  if (request.method === "GET" && requestUrl.pathname.startsWith("/api/radar/mesh")) {
    return handleMrmsMeshApi(requestUrl, response);
  }

  if (
    request.method === "GET" &&
    requestUrl.pathname.startsWith("/api/radar/") &&
    requestUrl.pathname !== "/api/radar/stations"
  ) {
    return handleRadarRequest(requestUrl, response);
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/lightning/glm/latest") {
    try {
      const satellite = requestUrl.searchParams.get("satellite") === "west" ? "west" : "east";
      sendJson(response, 200, await ensureLatestGlmFlashes(satellite));
    } catch (error) {
      sendJson(response, 502, { error: "GLM lightning unavailable", detail: error.message });
    }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/lightning/glm/fed") {
    try {
      const satellite = requestUrl.searchParams.get("satellite") === "west" ? "west" : "east";
      const minutes = [1, 5, 15].includes(Number(requestUrl.searchParams.get("minutes"))) ? Number(requestUrl.searchParams.get("minutes")) : 5;
      sendJson(response, 200, await ensureLatestGlmFlashes(satellite, minutes, `fed-${minutes}`));
    } catch (error) {
      sendJson(response, 502, { error: "GLM flash density unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/observations/surface") {
    const bbox = String(requestUrl.searchParams.get("bbox") || "");
    if (!/^-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?$/.test(bbox)) {
      sendJson(response, 400, { error: "Invalid observation bounding box" });
      return true;
    }
    try {
      const upstream = JSON.parse(await fetchText(`https://aviationweather.gov/api/data/metar?bbox=${encodeURIComponent(bbox)}&format=geojson&hours=2`));
      const seen = new Set();
      upstream.features = (upstream.features || []).filter((feature) => {
        const id = feature?.properties?.id;
        if (!id || seen.has(id)) return false;
        seen.add(id);
        const properties = feature.properties || {};
        properties.tempF = Number.isFinite(Number(properties.temp)) ? Math.round(Number(properties.temp) * 9 / 5 + 32) : null;
        properties.dewpF = Number.isFinite(Number(properties.dewp)) ? Math.round(Number(properties.dewp) * 9 / 5 + 32) : null;
        const raw = String(properties.rawOb || properties.rawob || "");
        const precipValue = (pattern) => {
          const match = raw.match(pattern);
          return match ? Number(match[1]) / 100 : null;
        };
        properties.precip1h = precipValue(/(?:^|\s)P(\d{4})(?=\s|$)/);
        properties.precip3or6 = precipValue(/(?:^|\s)6(\d{4})(?=\s|$)/);
        properties.precip24h = precipValue(/(?:^|\s)7(\d{4})(?=\s|$)/);
        const observationHour = new Date(properties.obsTime || properties.reportTime || 0).getUTCHours();
        properties.precipPeriod = [0, 6, 12, 18].includes(observationHour) ? 6 : [3, 9, 15, 21].includes(observationHour) ? 3 : null;
        return true;
      });
      sendJson(response, 200, upstream);
    } catch (error) {
      sendJson(response, 502, { error: "Surface observations unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/radar/stations") {
    try {
      sendJson(response, 200, await ensureRadarShelterTemperatures());
    } catch (error) {
      if (radarStationsCache) sendJson(response, 200, radarStationsCache);
      else sendJson(response, 502, { error: "Radar stations unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && ["/api/observations/river-gauges", "/api/observations/storm-reports"].includes(requestUrl.pathname)) {
    const bbox = String(requestUrl.searchParams.get("bbox") || "");
    if (!/^-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?$/.test(bbox)) {
      sendJson(response, 400, { error: "Invalid observation bounding box" });
      return true;
    }
    const [south, west, north, east] = bbox.split(",").map(Number);
    if (south >= north || west >= east || south < -90 || north > 90 || west < -180 || east > 180) {
      sendJson(response, 400, { error: "Invalid observation bounding box" });
      return true;
    }
    const isGauge = requestUrl.pathname.endsWith("river-gauges");
    try {
      if (isGauge) {
        const service =
          "https://mapservices.weather.noaa.gov/eventdriven/rest/services/water/riv_gauges/MapServer/0/query";
        const params = new URLSearchParams({
          where: "1=1",
          geometry: `${west},${south},${east},${north}`,
          geometryType: "esriGeometryEnvelope",
          inSR: "4326",
          spatialRel: "esriSpatialRelIntersects",
          outFields: "*",
          returnGeometry: "true",
          outSR: "4326",
          f: "geojson"
        });
        sendJson(response, 200, JSON.parse(await fetchText(`${service}?${params.toString()}`)));
      } else {
        // IEM first (same feed GR / many ops tools use) — NOAA MapServer can lag or omit.
        sendJson(response, 200, await fetchStormReportsGeoJson(south, west, north, east));
      }
    } catch (error) {
      sendJson(response, 502, {
        error: isGauge ? "River gauges unavailable" : "Local storm reports unavailable",
        detail: error.message
      });
    }
    return true;
  }

  const hydroGaugeMatch = request.method === "GET" && requestUrl.pathname.match(/^\/api\/hydro\/gauges\/([A-Za-z0-9]{3,10})$/);
  if (hydroGaugeMatch) {
    const lid = hydroGaugeMatch[1].toUpperCase();
    try {
      const base = `https://api.water.noaa.gov/nwps/v1/gauges/${encodeURIComponent(lid)}`;
      const [metadata, forecastBlock] = await Promise.all([
        fetchText(base).then(JSON.parse),
        fetchText(`${base}/stageflow/forecast`).then(JSON.parse)
      ]);
      const valid = (value) => Number.isFinite(Number(value)) && Number(value) > -900;
      const series = (block) => (Array.isArray(block?.data) ? block.data : [])
        .filter((item) => valid(item?.primary) && Number.isFinite(new Date(item.validTime).getTime()));
      const forecastSeries = series(forecastBlock);
      const metadataObserved = metadata?.status?.observed;
      const observed = valid(metadataObserved?.primary) ? { primary: Number(metadataObserved.primary), validTime: metadataObserved.validTime } : null;
      const crest = forecastSeries.reduce((best, item) => !best || Number(item.primary) > Number(best.primary) ? item : best, null);
      const firstForecast = forecastSeries[0] || null;
      const lastForecast = forecastSeries.at(-1) || null;
      const trendDelta = observed && firstForecast ? Number(firstForecast.primary) - Number(observed.primary)
        : 0;
      const categories = metadata?.flood?.categories || {};
      const impacts = Array.isArray(metadata?.flood?.impacts) ? metadata.flood.impacts
        .filter((impact) => valid(impact?.stage ?? impact?.value))
        .map((impact) => ({ stage: Number(impact.stage ?? impact.value), text: String(impact.description || impact.text || "").trim() }))
        .filter((impact) => impact.text)
        .slice(0, 30) : [];
      sendJson(response, 200, {
        lid, name: metadata?.name || lid, county: metadata?.county || "",
        state: metadata?.state?.abbreviation || "", wfo: metadata?.wfo?.abbreviation || "",
        rfc: metadata?.rfc?.abbreviation || "", latitude: metadata?.latitude, longitude: metadata?.longitude,
        units: metadata?.status?.observed?.primaryUnit || forecastBlock?.primaryUnits || metadata?.flood?.stageUnits || "",
        observed: observed ? { value: Number(observed.primary), time: observed.validTime } : null,
        forecast: firstForecast ? {
          value: Number(firstForecast.primary), time: firstForecast.validTime,
          endValue: Number(lastForecast.primary), endTime: lastForecast.validTime,
          crest: crest ? Number(crest.primary) : null, crestTime: crest?.validTime || null,
          issuedTime: forecastBlock?.issuedTime || null
        } : null,
        trend: Math.abs(trendDelta) < 0.05 ? "steady" : trendDelta > 0 ? "rising" : "falling",
        floodCategory: metadata?.status?.forecast?.floodCategory || metadata?.status?.observed?.floodCategory || "not_defined",
        thresholds: Object.fromEntries(Object.entries(categories).map(([key, value]) => [key, valid(value?.stage) ? Number(value.stage) : null])),
        impacts, forecastReliability: metadata?.forecastReliability || "",
        source: "NOAA/NWPS", fetchedAt: new Date().toISOString()
      });
    } catch (error) {
      sendJson(response, 502, { error: "NWPS gauge detail unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/satellite/goes/latest") {
    const satellite = requestUrl.searchParams.get("satellite") === "west" ? "west" : "east";
    const sector = String(requestUrl.searchParams.get("sector") || "conus").toLowerCase();
    const product = String(requestUrl.searchParams.get("product") || "").toLowerCase();
    const display = requestUrl.searchParams.get("display") === "cloud" ? "cloud" : "full";
    const band = Math.min(16, Math.max(1, Number(requestUrl.searchParams.get("band")) || 13));
    if (!["conus", "full", "m1", "m2"].includes(sector)) {
      sendJson(response, 400, { error: "Invalid GOES sector" });
      return true;
    }
    try {
      sendJson(response, 200, product === "geocolor"
        ? await ensureLatestGoesGeocolor(satellite, sector, display)
        : await ensureLatestGoesFrame(satellite, sector, band, display));
    } catch (error) {
      sendJson(response, 502, { error: "Native GOES render unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/satellite/goes/frames") {
    const satellite = requestUrl.searchParams.get("satellite") === "west" ? "west" : "east";
    const sector = String(requestUrl.searchParams.get("sector") || "conus").toLowerCase();
    const product = String(requestUrl.searchParams.get("product") || "geocolor").toLowerCase();
    const band = Math.min(16, Math.max(1, Number(requestUrl.searchParams.get("band")) || 13));
    const count = Math.max(3, Math.min(60, Number(requestUrl.searchParams.get("count")) || 6));
    const durationMinutes = Math.max(15, Math.min(360, Number(requestUrl.searchParams.get("durationMinutes")) || 120));
    const display = requestUrl.searchParams.get("display") === "cloud" ? "cloud" : "full";
    if (!["conus", "full", "m1", "m2"].includes(sector)) {
      sendJson(response, 400, { error: "Invalid GOES sector" });
      return true;
    }
    try {
      const progressive = requestUrl.searchParams.get("progressive") === "1" && product !== "geocolor";
      const result = progressive
        ? await progressiveGoesFrameInventory(satellite, sector, band, count, durationMinutes, display)
        : product === "geocolor"
        ? await ensureRecentGoesGeocolorFrames(satellite, sector, count, durationMinutes, display)
        : await ensureRecentGoesFrames(satellite, sector, band, count, durationMinutes, display);
      sendJson(response, 200, { ...result, provider: "NOAA AWS", generatedAt: new Date().toISOString() });
    } catch (error) {
      sendJson(response, 502, { error: "NOAA AWS GOES loop unavailable", detail: error.message });
    }
    return true;
  }

  const ndfdTileMatch = requestUrl.pathname.match(/^\/api\/forecast\/ndfd\/(temperature|apparent|humidity|maximum|minimum)\/(\d+)\/(\d+)\/(\d+)$/);
  if (request.method === "GET" && requestUrl.pathname === "/api/public/forecast") {
    return handlePublicPointForecast(requestUrl, response);
  }
  if (request.method === "GET" && ndfdTileMatch) {
    return proxyNdfdForecastTile(ndfdTileMatch[1], ndfdTileMatch[2], ndfdTileMatch[3], ndfdTileMatch[4], requestUrl.searchParams.get("hours"), response);
  }
  const ndfdValueMatch = requestUrl.pathname.match(/^\/api\/forecast\/ndfd\/(temperature|apparent|humidity|maximum|minimum)\/value$/);
  if (request.method === "GET" && ndfdValueMatch) {
    return identifyNdfdForecast(ndfdValueMatch[1], requestUrl, response);
  }

  if (request.method === "GET" && requestUrl.pathname.startsWith("/api/spc/outlook/")) {
    const outlookLayers = {
      "day1-cat": 1,
      "day1-torn-sig": 2,
      "day1-torn": 3,
      "day1-hail-sig": 4,
      "day1-hail": 5,
      "day1-wind-sig": 6,
      "day1-wind": 7,
      "day2-cat": 9,
      "day2-torn-sig": 10,
      "day2-torn": 11,
      "day2-hail-sig": 12,
      "day2-hail": 13,
      "day2-wind-sig": 14,
      "day2-wind": 15,
      "day3-cat": 17,
      "day3-severe-sig": 18,
      "day3-prob": 19,
      day1: 1
    };
    const key = requestUrl.pathname.slice("/api/spc/outlook/".length);
    const layerId = outlookLayers[key];
    if (!layerId) {
      sendJson(response, 404, { error: "Unknown SPC outlook layer" });
      return true;
    }
    try {
      const upstream = `https://mapservices.weather.noaa.gov/vector/rest/services/outlooks/SPC_wx_outlks/FeatureServer/${layerId}/query?where=1%3D1&outFields=*&returnGeometry=true&outSR=4326&f=geojson`;
      const outlook = await fetchJson(upstream);
      sendJson(response, 200, outlook);
    } catch (error) {
      sendJson(response, 502, { error: `SPC outlook ${key} unavailable`, detail: error.message });
    }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/spc/fire-outlook") {
    const day = Math.max(1, Math.min(8, Number(requestUrl.searchParams.get("day")) || 1));
    const layers = day === 1 ? [1, 2] : day === 2 ? [4, 5] : [7 + (day - 3) * 3, 8 + (day - 3) * 3];
    try {
      const query = "where=1%3D1&outFields=*&returnGeometry=true&outSR=4326&f=geojson";
      const payloads = await Promise.all(layers.map((layer) => fetchJson(`https://mapservices.weather.noaa.gov/vector/rest/services/fire_weather/SPC_firewx/MapServer/${layer}/query?${query}`)));
      const features = payloads.flatMap((payload, index) => (payload.features || []).map((feature) => ({
        ...feature,
        properties: { ...(feature.properties || {}), fireType: index === 0 ? (day <= 2 ? "wind" : "dry-thunder") : (day <= 2 ? "dry-thunder" : "wind"), outlookDay: day }
      })));
      sendJson(response, 200, { type: "FeatureCollection", features });
    } catch (error) {
      sendJson(response, 502, { error: `SPC fire outlook Day ${day} unavailable`, detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/discussions/spc") {
    try {
      const query = "where=1%3D1&outFields=*&returnGeometry=true&outSR=4326&f=geojson";
      const data = await fetchJson(`https://mapservices.weather.noaa.gov/vector/rest/services/outlooks/spc_mesoscale_discussion/MapServer/0/query?${query}`);
      const features=await mapWithConcurrency(data.features||[],3,async(feature)=>{
        const properties=feature.properties||{},number=String(properties.name||"").match(/MD\s*(\d+)/i)?.[1],fileDate=Number(properties.idp_filedate),year=Number.isFinite(fileDate)?new Date(fileDate).getUTCFullYear():new Date().getUTCFullYear();
        if(!number)return feature;
        try{return {...feature,properties:{...properties,detail:await loadSpcMesoscaleDetail(number,year)}};}catch(error){return {...feature,properties:{...properties,detailError:String(error.message||error).slice(0,180)}};}
      });
      data.features=features;
      sendJson(response, 200, data);
    } catch (error) {
      sendJson(response, 502, { error: "SPC mesoscale discussions unavailable", detail: error.message });
    }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/discussions/wpc") {
    try {
      const cacheBuster = Date.now();
      const indexHtml = await fetchText(`https://www.wpc.ncep.noaa.gov/metwatch/metwatch_mpd.php?_=${cacheBuster}`);
      const listedLinks = [...indexHtml.matchAll(/metwatch_mpd_multi\.php\?md=(\d+)&(?:amp;)?yr=(\d{4})/gi)]
        .map((match) => ({ number: match[1], year: match[2] }))
        .filter((item, index, all) => all.findIndex((other) => other.number === item.number && other.year === item.year) === index)
        .slice(0, 12);
      // WPC's active index can lag a newly issued MPD. Probe the next few
      // sequence numbers so new discussions appear without waiting on its CDN.
      const newest = Math.max(0, ...listedLinks.map((item) => Number(item.number) || 0));
      const currentYear = String(new Date().getUTCFullYear());
      const links = [...listedLinks];
      for (let offset = 1; newest && offset <= 5; offset += 1) {
        links.push({ number: String(newest + offset).padStart(4, "0"), year: currentYear });
      }
      const features = [];
      for (const { number, year } of links) {
        const url = `https://www.wpc.ncep.noaa.gov/metwatch/metwatch_mpd_multi.php?md=${number}&yr=${year}`;
        let html;
        try {
          // WPC's product endpoint can return a title-only page when an
          // unrecognized cache-busting query parameter is present.
          html = await fetchText(url);
        } catch {
          try {
            html = await fetchText(`https://origin-east-www-wpc.woc.noaa.gov/metwatch/metwatch_mpd_multi.php?md=${number}&yr=${year}`);
          } catch {
            continue;
          }
        }
        const normalizeMpdHtml = (value) => {
          const productBlock = value.match(/<pre\b[^>]*>([\s\S]*?)<\/pre>/i)?.[1] || value;
          return productBlock.replace(/<[^>]+>/g, " ").replace(/&nbsp;|&#160;/gi, " ").replace(/&amp;/gi, "&").replace(/\s+/g, " ").trim();
        };
        let plain = normalizeMpdHtml(html);
        let productNumber = plain.match(/Mesoscale Precipitation Discussion:?\s*#?(\d{4})/i)?.[1];
        let coordMatch = plain.match(/LAT\.\.\.LON\s+((?:\d{8}\s*){3,})/i);
        if (productNumber !== String(number).padStart(4, "0") || !coordMatch) {
          try {
            const fallbackUrl = `https://origin-east-www-wpc.woc.noaa.gov/metwatch/metwatch_mpd_multi.php?md=${number}&yr=${year}`;
            plain = normalizeMpdHtml(await fetchText(fallbackUrl));
            productNumber = plain.match(/Mesoscale Precipitation Discussion:?\s*#?(\d{4})/i)?.[1];
            coordMatch = plain.match(/LAT\.\.\.LON\s+((?:\d{8}\s*){3,})/i);
          } catch { /* primary result is checked below */ }
        }
        if (productNumber !== String(number).padStart(4, "0")) continue;
        if (!coordMatch) continue;
        const coordinates = [...coordMatch[1].matchAll(/(\d{4})(\d{4})/g)].map((match) => {
          const latitude = Number(match[1]) / 100;
          const encodedLongitude = Number(match[2]) / 100;
          // WPC omits the leading 1 for longitudes west of 100 degrees.
          // For example, 31310089 represents 31.31 N, 100.89 W.
          const longitude = encodedLongitude < 50 ? encodedLongitude + 100 : encodedLongitude;
          return [-longitude, latitude];
        });
        if (coordinates.length < 3) continue;
        coordinates.push([...coordinates[0]]);
        const concern = plain.match(/Concerning\.\.\.([\s\S]*?)\s+Valid\s+/i)?.[1]?.trim() || "Heavy rainfall";
        const valid = plain.match(/Valid\s+(\d{6}Z\s*-\s*\d{6}Z)/i)?.[1] || "";
        const summary = plain.match(/Summary\.\.\.([\s\S]*?)\s+Discussion\.\.\./i)?.[1]?.trim() || "";
        features.push({ type: "Feature", properties: { number, year, concern, valid, summary, url }, geometry: { type: "Polygon", coordinates: [coordinates] } });
      }
      sendJson(response, 200, { type: "FeatureCollection", features });
    } catch (error) {
      sendJson(response, 502, { error: "WPC mesoscale precipitation discussions unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/features") {
    return handleFeatureRequest(requestUrl, response);
  }

  if (requestUrl.pathname === "/api/dss/locations") {
    const store = loadDssLocations();
    const username = String(session.username || "local-operator");
    const fresh = (Array.isArray(store[username]) ? store[username] : []).filter((item) =>
      !item.expiresAt || new Date(item.expiresAt).getTime() > Date.now()
    );
    store[username] = fresh;
    if (request.method === "GET") {
      saveDssLocations(store);
      sendJson(response, 200, { locations: fresh });
      return true;
    }
    if (request.method === "PUT") {
      try {
        const value = JSON.parse(await readRequestBody(request) || "{}");
        const existing = value.id ? fresh.find((item) => item.id === value.id) : null;
        const cleaned = cleanDssLocation(value, existing);
        if (!cleaned) throw new Error("Name and valid coordinates are required");
        store[username] = existing
          ? fresh.map((item) => item.id === existing.id ? cleaned : item)
          : [...fresh, cleaned];
        saveDssLocations(store);
        sendJson(response, 200, { location: cleaned, locations: store[username] });
      } catch (error) {
        sendJson(response, 400, { error: "Invalid DSS location", detail: error.message });
      }
      return true;
    }
    if (request.method === "DELETE") {
      const id = String(requestUrl.searchParams.get("id") || "");
      store[username] = fresh.filter((item) => item.id !== id);
      saveDssLocations(store);
      sendJson(response, 200, { locations: store[username] });
      return true;
    }
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/nhc/guidance/catalog") {
    try {
      if (Date.now() - nhcGuidanceCatalogCache.at > 5 * 60_000) {
        const html = await fetchText("https://ftp.nhc.noaa.gov/atcf/aid_public/");
        const year = new Date().getUTCFullYear();
        const ids = [...html.matchAll(new RegExp(`a((?:al|ep|cp)\\d{2}${year})\\.dat\\.gz`, "gi"))].map((match) => match[1].toLowerCase());
        nhcGuidanceCatalogCache = { at: Date.now(), storms: [...new Set(ids)].sort() };
      }
      sendJson(response, 200, { storms: nhcGuidanceCatalogCache.storms, updatedAt: new Date(nhcGuidanceCatalogCache.at).toISOString() });
    } catch (error) {
      sendJson(response, 502, { error: "NHC guidance catalog unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/nhc/official") {
    try {
      const current = await fetchJson("https://www.nhc.noaa.gov/CurrentStorms.json");
      const storms = Array.isArray(current.activeStorms) ? current.activeStorms : [];
      if (requestUrl.searchParams.get("catalog") === "1") {
        sendJson(response, 200, { storms: storms.map((storm) => ({ id: storm.id, name: storm.name, classification: storm.classification, intensity: storm.intensity, advisory: storm.publicAdvisory?.advNum, updatedAt: storm.lastUpdate })) });
        return true;
      }
      const stormId = String(requestUrl.searchParams.get("storm") || storms[0]?.id || "").toLowerCase();
      const storm = storms.find((item) => String(item.id).toLowerCase() === stormId);
      if (!storm) throw new Error("The selected storm is not in NHC CurrentStorms");
      const product = String(requestUrl.searchParams.get("product") || "cone");
      const urls = {
        cone: storm.trackCone?.kmzFile,
        track: storm.forecastTrack?.kmzFile,
        radii: storm.forecastWindRadiiGIS?.kmzFile,
        warnings: storm.windWatchesWarnings?.kmzFile,
        history: storm.bestTrackGIS?.kmzFile,
        "arrival-earliest": storm.earliestArrivalTimeTSWindsGIS?.kmzFile,
        "arrival-likely": storm.mostLikelyTimeTSWindsGIS?.kmzFile
      };
      const url = urls[product];
      if (!url) throw new Error(`${product} is not available for ${storm.name || storm.id}`);
      const data = await kmzToGeoJson(url, { product, stormId: storm.id, stormName: storm.name, advisory: storm.publicAdvisory?.advNum || "" });
      sendJson(response, 200, { ...data, storm: { id: storm.id, name: storm.name, advisory: storm.publicAdvisory?.advNum, updatedAt: storm.lastUpdate }, product });
    } catch (error) {
      sendJson(response, 502, { error: "Official NHC GIS data unavailable", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/nhc/guidance") {
    const storm = String(requestUrl.searchParams.get("storm") || "").toLowerCase();
    if (!/^(al|ep|cp)\d{2}\d{4}$/.test(storm)) { sendJson(response, 400, { error: "Valid ATCF storm ID required" }); return true; }
    try {
      const cached = nhcGuidanceCache.get(storm);
      if (cached && Date.now() - cached.at < 5 * 60_000) { sendJson(response, 200, cached.data); return true; }
      const compressed = await fetchBuffer(`https://ftp.nhc.noaa.gov/atcf/aid_public/a${storm}.dat.gz`);
      const data = parseAtcfGuidance(zlib.gunzipSync(compressed).toString("utf8"), storm);
      nhcGuidanceCache.set(storm, { at: Date.now(), data });
      sendJson(response, 200, data);
    } catch (error) {
      sendJson(response, 502, { error: "NHC model guidance unavailable", detail: error.message });
    }
    return true;
  }

  if (requestUrl.pathname === "/api/nhc/forecasts") {
    // Shared tropical desk — every authenticated ops user sees the same list.
    const store = loadNhcForecasts();
    const username = String(session.username || session.displayName || "local-operator");
    const forecasts = Array.isArray(store.forecasts) ? store.forecasts : [];
    if (request.method === "GET") {
      sendJson(response, 200, { forecasts, shared: true });
      return true;
    }
    if (request.method === "PUT") {
      try {
        const value = JSON.parse(await readRequestBody(request) || "{}");
        const existing = value.id
          ? forecasts.find((item) => item.id === value.id)
          : forecasts.find(
              (item) =>
                item.name === String(value.name || "").trim().toUpperCase() &&
                String(item.advisory) === String(Number(value.advisory) || 1)
            );
        const cleaned = cleanNhcForecast(value, existing, username);
        if (!cleaned) throw new Error("Storm name, OBS, and at least one valid forecast position are required");
        store.forecasts = existing
          ? forecasts.map((item) => (item.id === existing.id ? cleaned : item))
          : [cleaned, ...forecasts].slice(0, 100);
        saveNhcForecasts(store);
        sendJson(response, 200, { forecast: cleaned, forecasts: store.forecasts, shared: true });
      } catch (error) {
        sendJson(response, 400, { error: "Invalid NHC forecast", detail: error.message });
      }
      return true;
    }
    if (request.method === "DELETE") {
      const id = String(requestUrl.searchParams.get("id") || "");
      store.forecasts = forecasts.filter((item) => item.id !== id);
      saveNhcForecasts(store);
      sendJson(response, 200, { forecasts: store.forecasts, shared: true });
      return true;
    }
  }

  // Ops map snapshot upload (PNG for Mattermost) — authenticated
  if (requestUrl.pathname === "/api/ops/map-snapshot") {
    if (request.method === "POST" || request.method === "PUT") {
      try {
        const value = JSON.parse((await readRequestBody(request)) || "{}");
        const id = String(value.id || value.warningId || value.productId || "").trim();
        if (!id) {
          sendJson(response, 400, { error: "Expected id (warning/watch id)" });
          return true;
        }
        let png = null;
        if (typeof value.imageBase64 === "string" && value.imageBase64) {
          const raw = value.imageBase64.replace(/^data:image\/png;base64,/, "").replace(/\s/g, "");
          png = Buffer.from(raw, "base64");
        } else if (typeof value.dataUrl === "string" && value.dataUrl.startsWith("data:image/")) {
          const raw = value.dataUrl.replace(/^data:image\/\w+;base64,/, "");
          png = Buffer.from(raw, "base64");
        }
        if (!png || png.length < 100) {
          sendJson(response, 400, { error: "Expected imageBase64 or dataUrl PNG" });
          return true;
        }
        // PNG magic bytes
        if (png[0] !== 0x89 || png[1] !== 0x50) {
          sendJson(response, 400, { error: "Payload is not a PNG image" });
          return true;
        }
        const saved = saveMapSnapshotPng(id, png);
        sendJson(response, 200, {
          ok: true,
          id: saved.id,
          bytes: saved.bytes,
          url: saved.url
        });
      } catch (error) {
        sendJson(response, 400, { error: "Invalid map snapshot", detail: error.message });
      }
      return true;
    }
  }

  // SPC desk ↔ local WFO watch coordination (draft watches)
  if (requestUrl.pathname === "/api/spc/coordination") {
    const username = String(session.username || session.displayName || "local-operator");
    const displayName = String(session.displayName || session.username || username);
    if (request.method === "GET") {
      const store = loadSpcCoordination();
      const drafts = freshSpcCoordinationDrafts(store);
      if (drafts.length !== (store.drafts || []).length) {
        saveSpcCoordination({ drafts });
      }
      const wfoFilter = normalizeSpcWfoCode(requestUrl.searchParams.get("wfo") || "");
      const filtered = wfoFilter
        ? drafts.filter((d) => Array.isArray(d.wfos) && d.wfos.includes(wfoFilter))
        : drafts;
      sendJson(response, 200, {
        updatedAt: store.updatedAt,
        drafts: filtered,
        count: filtered.length
      });
      return true;
    }
    if (request.method === "PUT") {
      try {
        const value = JSON.parse((await readRequestBody(request)) || "{}");
        const store = loadSpcCoordination();
        let drafts = freshSpcCoordinationDrafts(store);
        const existing = value.id ? drafts.find((d) => d.id === value.id) : null;
        // One active drafting package per SPC session — replace older from same session
        if (!existing && value.sessionId) {
          drafts = drafts.filter((d) => d.sessionId !== String(value.sessionId));
        }
        const cleaned = cleanSpcCoordinationDraft(value, existing, username, displayName);
        if (!cleaned) {
          sendJson(response, 400, { error: "Expected product and at least one WFO in the watch box" });
          return true;
        }
        cleaned.status = "drafting";
        drafts = existing
          ? drafts.map((d) => (d.id === existing.id ? cleaned : d))
          : [cleaned, ...drafts];
        const saved = saveSpcCoordination({ drafts: drafts.slice(0, 20) });
        sendJson(response, 200, { draft: cleaned, drafts: saved.drafts, updatedAt: saved.updatedAt });
      } catch (error) {
        sendJson(response, 400, { error: "Invalid SPC coordination payload", detail: error.message });
      }
      return true;
    }
    if (request.method === "DELETE") {
      const id = String(requestUrl.searchParams.get("id") || "");
      const sessionId = String(requestUrl.searchParams.get("sessionId") || "");
      const store = loadSpcCoordination();
      let drafts = Array.isArray(store.drafts) ? store.drafts : [];
      if (id) {
        drafts = drafts.filter((d) => d.id !== id);
      } else if (sessionId) {
        drafts = drafts.filter((d) => d.sessionId !== sessionId);
      } else {
        sendJson(response, 400, { error: "Expected id or sessionId" });
        return true;
      }
      const saved = saveSpcCoordination({ drafts: freshSpcCoordinationDrafts({ drafts }) });
      sendJson(response, 200, { drafts: saved.drafts, updatedAt: saved.updatedAt, cleared: true });
      return true;
    }
  }

  if (request.method === "POST" && requestUrl.pathname === "/api/spc/coordination/respond") {
    try {
      const value = JSON.parse((await readRequestBody(request)) || "{}");
      const draftId = String(value.id || value.draftId || "").slice(0, 80);
      const wfo = normalizeSpcWfoCode(value.wfo);
      const wantInclude = value.wantInclude === true || value.include === true || value.yes === true
        ? true
        : value.wantInclude === false || value.include === false || value.no === true
          ? false
          : null;
      if (!draftId || !wfo || wantInclude === null) {
        sendJson(response, 400, { error: "Expected draft id, wfo, and wantInclude true/false" });
        return true;
      }
      const store = loadSpcCoordination();
      const drafts = freshSpcCoordinationDrafts(store);
      const draft = drafts.find((d) => d.id === draftId);
      if (!draft) {
        sendJson(response, 404, { error: "Coordination draft not found or no longer active" });
        return true;
      }
      if (!Array.isArray(draft.wfos) || !draft.wfos.includes(wfo)) {
        sendJson(response, 400, { error: `${wfo} is not in this watch draft` });
        return true;
      }
      const username = String(session.username || session.displayName || "local-operator").slice(0, 80);
      const displayName = String(session.displayName || session.username || username).slice(0, 80);
      draft.responses = draft.responses && typeof draft.responses === "object" ? draft.responses : {};
      draft.responses[wfo] = {
        wantInclude,
        username,
        displayName,
        at: new Date().toISOString()
      };
      draft.updatedAt = new Date().toISOString();
      // Do NOT change draft.wfoInclude — SPC desk retains final yes/no.
      const saved = saveSpcCoordination({
        drafts: drafts.map((d) => (d.id === draft.id ? draft : d))
      });
      sendJson(response, 200, {
        draft,
        drafts: saved.drafts,
        advisory: true,
        message: "WFO preference recorded. SPC desk has final include/exclude authority."
      });
    } catch (error) {
      sendJson(response, 400, { error: "Invalid WFO coordination response", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/bootstrap-state") {
    const allPreferences = loadAllPreferences();
    const ops = loadOpsProducts();
    const publicAlerts = loadPublicAlerts();
    const gfe = loadGfeProducts();
    sendJson(response, 200, {
      username: session.username,
      preferences: allPreferences[session.username] || {},
      opsProducts: ops.warnings || [],
      publicAlerts: publicAlerts.warnings || [],
      gfeEvents: gfe.events || []
    });
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/ops/warning-stream") {
    response.writeHead(200, {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      "Connection": "keep-alive",
      "X-Accel-Buffering": "no"
    });
    response.write("retry: 1500\n\n");
    let lastStamp = "";
    const sendStamp = () => {
      let stamp = "missing";
      try {
        const publicStat = fs.statSync(publicAlertsFile);
        const opsStat = fs.statSync(opsProductsFile);
        stamp = `${publicStat.mtimeMs}:${publicStat.size}:${opsStat.mtimeMs}:${opsStat.size}`;
      } catch { /* the next write will produce a new stamp */ }
      if (stamp === lastStamp) return;
      lastStamp = stamp;
      response.write(`event: warnings\ndata: ${JSON.stringify({ stamp, at: new Date().toISOString() })}\n\n`);
    };
    sendStamp();
    const changeTimer = setInterval(sendStamp, 750);
    const keepaliveTimer = setInterval(() => response.write(": keepalive\n\n"), 15_000);
    const close = () => {
      clearInterval(changeTimer);
      clearInterval(keepaliveTimer);
    };
    request.once("close", close);
    response.once("close", close);
    return true;
  }

  if (requestUrl.pathname === "/api/preferences") {
    const allPreferences = loadAllPreferences();

    if (request.method === "GET") {
      sendJson(response, 200, allPreferences[session.username] || {});
      return true;
    }

    if (request.method === "PUT") {
      try {
        const body = await readRequestBody(request);
        const nextPreferences = JSON.parse(body || "{}");
        // Optimistic concurrency: client sends the updatedAt it last loaded/saved.
        // If another tab/machine wrote first, return 409 with the server copy.
        const forceOverwrite = Boolean(nextPreferences.forceOverwrite);
        const baseUpdatedAt = nextPreferences.baseUpdatedAt
          ? String(nextPreferences.baseUpdatedAt)
          : "";
        delete nextPreferences.forceOverwrite;
        delete nextPreferences.baseUpdatedAt;
        // Never trust client-supplied updatedAt as the document stamp
        delete nextPreferences.updatedAt;

        const current = allPreferences[session.username] || {};
        const currentAt = current.updatedAt ? String(current.updatedAt) : "";
        if (
          !forceOverwrite &&
          baseUpdatedAt &&
          currentAt &&
          currentAt !== baseUpdatedAt &&
          new Date(currentAt).getTime() > new Date(baseUpdatedAt).getTime()
        ) {
          sendJson(response, 409, {
            error: "Preferences were updated in another session",
            conflict: true,
            preferences: current
          });
          return true;
        }

        allPreferences[session.username] = {
          ...current,
          ...nextPreferences,
          updatedAt: new Date().toISOString()
        };
        saveAllPreferences(allPreferences);
        sendJson(response, 200, allPreferences[session.username]);
      } catch {
        sendJson(response, 400, {
          error: "Invalid preference payload"
        });
      }

      return true;
    }
  }

  if (request.method === "PUT" && requestUrl.pathname === "/api/preferences/primary-wfo") {
    try {
      const body = JSON.parse((await readRequestBody(request)) || "{}");
      const wfo = String(body.wfo || "").trim().replace(/^K/i, "").toUpperCase();
      if (!/^[A-Z0-9]{3}$/.test(wfo)) {
        sendJson(response, 400, { error: "Expected a three-character WFO" });
        return true;
      }
      const allPreferences = loadAllPreferences();
      allPreferences[session.username] = {
        ...(allPreferences[session.username] || {}),
        primaryWfo: wfo,
        updatedAt: new Date().toISOString()
      };
      saveAllPreferences(allPreferences);
      sendJson(response, 200, { primaryWfo: wfo });
    } catch {
      sendJson(response, 400, { error: "Could not save primary WFO" });
    }
    return true;
  }

  if (requestUrl.pathname === "/api/preferences/client-state") {
    const allPreferences = loadAllPreferences();
    if (request.method === "GET") {
      const state = allPreferences[session.username]?.clientState;
      sendJson(response, 200, state && typeof state === "object" ? state : { values: {}, updatedAt: 0 });
      return true;
    }
    if (request.method === "PUT") {
      try {
        const body = JSON.parse((await readRequestBody(request)) || "{}");
        const incoming = body.values && typeof body.values === "object" && !Array.isArray(body.values) ? body.values : {};
        const values = {};
        for (const [key, value] of Object.entries(incoming).slice(0, 300)) {
          if (!/^zncave-[A-Za-z0-9:_-]{1,180}$/.test(key) || key === "zncave-draft-session-id") continue;
          values[key] = String(value).slice(0, 1_500_000);
        }
        const current = allPreferences[session.username]?.clientState;
        const requestedAt = Math.max(0, Number(body.updatedAt) || Date.now());
        if (current && Number(current.updatedAt) > requestedAt) {
          sendJson(response, 409, current);
          return true;
        }
        const clientState = { values, updatedAt: requestedAt };
        allPreferences[session.username] = {
          ...(allPreferences[session.username] || {}),
          clientState,
          updatedAt: new Date().toISOString()
        };
        saveAllPreferences(allPreferences);
        sendJson(response, 200, clientState);
      } catch (error) {
        sendJson(response, 400, { error: "Could not save user client state", detail: error.message });
      }
      return true;
    }
  }

  if (requestUrl.pathname === "/api/warnings/audit") {
    if (request.method === "GET") {
      const store = loadWarningAuditLog();
      sendJson(response, 200, {
        updatedAt: store.updatedAt,
        entries: (store.entries || []).slice(0, 200)
      });
      return true;
    }

    if (request.method === "POST") {
      try {
        const body = await readRequestBody(request);
        const payload = JSON.parse(body || "{}");
        if (!payload || typeof payload !== "object" || !payload.entry) {
          sendJson(response, 400, { error: "Expected { entry: {...} }" });
          return true;
        }
        const auditedEntry = {
          ...payload.entry,
          operator: payload.entry.operator || session.displayName || session.username || "Local Operator",
          operatorUsername: session.username || "local-operator"
        };
        const store = appendWarningAuditEntry(auditedEntry);
        try {
          recordAccessEvent(request, session, "warning-issued", {
            productId: auditedEntry.productId,
            warningProduct: auditedEntry.product,
            warningAction: auditedEntry.action,
            warningWfo: auditedEntry.wfo,
            practice: Boolean(auditedEntry.practice),
            page: "/"
          });
        } catch (auditError) {
          console.error("[access-audit] Could not record warning issuance:", auditError.message);
        }
        sendJson(response, 200, {
          updatedAt: store.updatedAt,
          entries: (store.entries || []).slice(0, 200)
        });
      } catch (error) {
        sendJson(response, 400, {
          error: "Invalid warning audit payload",
          detail: error.message
        });
      }
      return true;
    }

    if (request.method === "DELETE") {
      const store = saveWarningAuditLog([]);
      sendJson(response, 200, store);
      return true;
    }
  }

  if (requestUrl.pathname === "/api/ops/admin/native-workstations") {
    if (!canAdministerHazardTemplates(session)) {
      sendJson(response, 403, { error: "Operations administrator permission required" });
      return true;
    }
    const publicDevice = (device) => ({
      id: device.id,
      name: device.name,
      wfo: device.wfo || (Array.isArray(device.wfos) ? device.wfos[0] : "") || "",
      wfos: Array.isArray(device.wfos) ? device.wfos : device.wfo ? [device.wfo] : [],
      enabled: device.enabled !== false,
      createdAt: device.createdAt,
      createdBy: device.createdBy,
      lastSeenAt: device.lastSeenAt || null,
      revokedAt: device.revokedAt || null
    });
    if (request.method === "GET") {
      const store = loadNativeWorkstations();
      const now = Date.now();
      store.pending = store.pending.filter((entry) => Number(entry.expiresAt) > now);
      saveNativeWorkstations(store);
      sendJson(response, 200, {
        updatedAt: store.updatedAt,
        devices: store.devices.map(publicDevice),
        pending: store.pending.map((entry) => ({ id: entry.id, name: entry.name, createdAt: entry.createdAt, createdBy: entry.createdBy, expiresAt: entry.expiresAt }))
      });
      return true;
    }
    if (request.method === "POST") {
      try {
        const payload = JSON.parse((await readRequestBody(request)) || "{}");
        const name = String(payload.name || "").trim().replace(/[\u0000-\u001f\u007f]/g, " ").slice(0, 80);
        if (name.length < 2) throw new Error("Enter a workstation name");
        const wfos = String(payload.wfo || payload.wfos || "").split(",").map((value) => value.trim().toUpperCase()).filter((value) => /^[A-Z0-9]{3,8}$/.test(value)).slice(0, 12);
        const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
        const random = crypto.randomBytes(12);
        const rawCode = [...random].map((byte) => alphabet[byte % alphabet.length]).join("");
        const code = rawCode.match(/.{1,4}/g).join("-");
        const now = Date.now();
        const store = loadNativeWorkstations();
        store.pending = store.pending.filter((entry) => Number(entry.expiresAt) > now);
        const pending = {
          id: `enroll-${crypto.randomBytes(8).toString("base64url")}`,
          name,
          wfo: wfos[0] || "",
          wfos,
          codeHash: nativeSecretHash(rawCode),
          createdAt: new Date(now).toISOString(),
          createdBy: session.username,
          expiresAt: now + 15 * 60_000
        };
        store.pending.push(pending);
        saveNativeWorkstations(store);
        try { recordAccessEvent(request, session, "native-enrollment-created", { tool: name }); } catch { /* code remains valid */ }
        sendJson(response, 201, { code, pending: { id: pending.id, name, createdAt: pending.createdAt, createdBy: pending.createdBy, expiresAt: pending.expiresAt } });
      } catch (error) {
        sendJson(response, 400, { error: error.message || "Invalid workstation enrollment" });
      }
      return true;
    }
    if (request.method === "DELETE") {
      const id = String(requestUrl.searchParams.get("id") || "").slice(0, 100);
      const store = loadNativeWorkstations();
      const pendingIndex = store.pending.findIndex((entry) => entry.id === id);
      if (pendingIndex >= 0) {
        store.pending.splice(pendingIndex, 1);
      } else {
        const device = store.devices.find((entry) => entry.id === id);
        if (!device) {
          sendJson(response, 404, { error: "Workstation or enrollment not found" });
          return true;
        }
        device.revokedAt = new Date().toISOString();
        device.revokedBy = session.username;
      }
      saveNativeWorkstations(store);
      try { recordAccessEvent(request, session, "native-workstation-revoked", { tool: id }); } catch { /* revocation remains valid */ }
      sendJson(response, 200, { revoked: true, id });
      return true;
    }
    sendJson(response, 405, { error: "Method not allowed" });
    return true;
  }

  if (requestUrl.pathname === "/api/ops/admin/hazard-templates") {
    if (request.method === "GET") {
      sendJson(response, 200, loadHazardTemplates());
      return true;
    }
    if (request.method === "PUT") {
      if (!canAdministerHazardTemplates(session)) {
        sendJson(response, 403, { error: "Hazard template administrator permission required" });
        return true;
      }
      try {
        const payload = JSON.parse((await readRequestBody(request)) || "{}");
        const saved = saveHazardTemplates(cleanHazardTemplates(payload.templates), session);
        try { recordAccessEvent(request, session, "hazard-templates-updated", { page: "/admin" }); } catch { /* save remains valid */ }
        sendJson(response, 200, saved);
      } catch (error) {
        sendJson(response, 400, { error: "Invalid hazard templates payload", detail: error.message });
      }
      return true;
    }
    sendJson(response, 405, { error: "Method not allowed" });
    return true;
  }

  if (requestUrl.pathname === "/api/wfo-automation/config") {
    if (!session.authenticated) { sendJson(response, 401, { error: "SSO authentication required" }); return true; }
    if (request.method === "GET") { sendJson(response, 200, loadWfoAutomation()); return true; }
    if (request.method === "PUT") {
      if (!canAdministerHazardTemplates(session)) { sendJson(response, 403, { error: "Automation administrator permission required" }); return true; }
      try {
        const payload = JSON.parse((await readRequestBody(request)) || "{}");
        for (const office of payload.offices || []) {
          const criteria = office.criteria || {};
          if (Number(criteria.extremeHeatF) <= Number(criteria.heatAdvisoryF)) { sendJson(response, 400, { error: `${office.wfo || "Office"}: Extreme Heat threshold must be above Heat Advisory` }); return true; }
          if (Number(criteria.highWindMph) <= Number(criteria.windAdvisoryMph)) { sendJson(response, 400, { error: `${office.wfo || "Office"}: High Wind threshold must be above Wind Advisory` }); return true; }
          if (Number(criteria.extremeColdF) >= Number(criteria.freezeWarningF)) { sendJson(response, 400, { error: `${office.wfo || "Office"}: Extreme Cold threshold must be below Freeze Warning` }); return true; }
        }
        if ((payload.offices || []).some((office) => office.mode === "issue" && !office.autoIssueAuthorized)) {
          sendJson(response, 400, { error: "Auto-issue mode requires explicit administrator authorization for every office" }); return true;
        }
        const saved = saveWfoAutomation(payload, session, payload.emergencyStop ? "emergency-stop-enabled" : "configuration-saved");
        try { recordAccessEvent(request, session, "wfo-automation-configured", { offices: saved.offices.map((item) => item.wfo), emergencyStop: saved.emergencyStop }); } catch { /* save remains valid */ }
        sendJson(response, 200, saved);
      } catch (error) { sendJson(response, 400, { error: "Invalid automation configuration", detail: error.message }); }
      return true;
    }
    sendJson(response, 405, { error: "Method not allowed" }); return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/wfo-automation/profile") {
    if (!session.authenticated) { sendJson(response, 401, { error: "SSO authentication required" }); return true; }
    const wfo = String(requestUrl.searchParams.get("wfo") || "").toUpperCase();
    if (!/^[A-Z0-9]{3}$/.test(wfo)) { sendJson(response, 400, { error: "Valid WFO required" }); return true; }
    sendJson(response, 200, { wfo, ...automationCriteriaProfile(wfo), verifiedLocalProfile: false, nationalStandard: true });
    return true;
  }

  if (requestUrl.pathname === "/api/wfo-automation/ignored") {
    if (!session.authenticated) { sendJson(response, 401, { error: "SSO authentication required" }); return true; }
    if (request.method === "GET") { const state = loadWfoAutomation(); sendJson(response, 200, { ignoredOffices: state.ignoredOffices || [] }); return true; }
    if (request.method === "PUT") {
      if (!canAdministerHazardTemplates(session)) { sendJson(response, 403, { error: "Automation administrator permission required" }); return true; }
      try { const payload = JSON.parse((await readRequestBody(request)) || "{}"); const state = loadWfoAutomation(); state.ignoredOffices = [...new Set((payload.ignoredOffices || []).map((item) => String(item).toUpperCase()).filter((item) => /^[A-Z0-9]{3}$/.test(item)))]; state.updatedAt = new Date().toISOString(); state.updatedBy = session.username; state.history = [{ at: state.updatedAt, by: session.username, action: "manned-office-list-updated" }, ...(state.history || [])].slice(0, 300); fs.writeFileSync(wfoAutomationFile, JSON.stringify(state, null, 2)); sendJson(response, 200, state); }
      catch (error) { sendJson(response, 400, { error: "Invalid manned-office list", detail: error.message }); }
      return true;
    }
    sendJson(response, 405, { error: "Method not allowed" }); return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/wfo-automation/sectors") {
    if (!session.authenticated) { sendJson(response, 401, { error: "SSO authentication required" }); return true; }
    const collection = JSON.parse(fs.readFileSync(path.join(dataDir, "generated", "awips", "cwa.geojson"), "utf8"));
    const assignments = {};
    for (const feature of collection.features || []) { const code=String(feature.properties?.CWA||feature.properties?.WFO||"").toUpperCase(), state=String(feature.properties?.ST||"").toUpperCase(); if(code) assignments[code]=sectorForOffice(code,state).id; }
    sendJson(response, 200, { sectors: automationSectorProfiles, assignments, officeProfiles: wfoAutomationCriteriaProfiles }); return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/wfo-automation/monitor") {
    if (!session.authenticated) { sendJson(response, 401, { error: "SSO authentication required" }); return true; }
    try { const stored=JSON.parse(fs.readFileSync(wfoMonitorResultsFile,"utf8"));sendJson(response, 200, { ...stored, ...wfoMonitorProgress, results:wfoMonitorRunning?[]:stored.results, running:wfoMonitorRunning, bulkGuidance:wfoNdfdBulkStatus, autoDrafts:loadWfoAutoDrafts().drafts.filter((draft)=>["confirmed","issuing","issue-failed"].includes(draft.status)||(draft.status==="issued"&&Date.now()-Date.parse(draft.issuedAt||0)<24*60*60_000)).slice(-200) }); }
    catch { sendJson(response, 200, { mode:"monitor-only", ...wfoMonitorProgress, running:wfoMonitorRunning, completedAt:null, officeCount:0, candidateCount:0, results:[] }); }
    return true;
  }

  const autoDraftMatch=requestUrl.pathname.match(/^\/api\/wfo-automation\/drafts\/(auto-[A-Za-z0-9-]+)$/);
  if(autoDraftMatch){
    if(!session.authenticated){sendJson(response,401,{error:"SSO authentication required"});return true;}
    if(request.method!=="PATCH"){sendJson(response,405,{error:"Method not allowed"});return true;}
    if(!canAdministerHazardTemplates(session)){sendJson(response,403,{error:"Automation administrator permission required"});return true;}
    try{
      const payload=JSON.parse((await readRequestBody(request))||"{}"),decision=String(payload.decision||"").toLowerCase();
      if(!["approve","reject","issue"].includes(decision))throw new Error("Decision must be approve, reject, or issue");
      const store=loadWfoAutoDrafts(),draft=store.drafts.find((item)=>item.id===autoDraftMatch[1]);
      if(!draft) {sendJson(response,404,{error:"Auto-draft not found"});return true;}
      if(decision==="issue"&&draft.status!=="approved"){sendJson(response,409,{error:"The draft must be approved before live issuance",draft});return true;}
      if(decision!=="issue"&&draft.status!=="pending-review"){sendJson(response,409,{error:`Draft is already ${draft.status}`,draft});return true;}
      if(decision==="approve"){
        await validateAutomatedDraftSafety(draft);
      }
      if(decision==="issue"){
        if(wfoAutoDraftIssuing.has(draft.id)){sendJson(response,409,{error:"This draft is already being issued"});return true;}
        wfoAutoDraftIssuing.add(draft.id);
        try{
          const nwsDetail=await validateAutomatedDraftSafety(draft),event=buildAutomatedGfeEvent(draft,nwsDetail),published=await publishAutomatedGfeEvent(event,session,request);
          draft.status="issued";draft.issuedAt=new Date().toISOString();draft.issuedBy=String(session.username||"operator").slice(0,80);draft.issuedEventId=event.id;draft.liveIssuance=true;saveWfoAutoDrafts(store.drafts);
          try{recordAccessEvent(request,session,"wfo-auto-draft-issued",{page:"/wfo",draftId:draft.id,eventId:event.id,wfo:draft.wfo,zone:draft.zoneCode,hazard:draft.hazard});}catch{/* issuance remains saved */}
          sendJson(response,200,{draft,event:published.event,distribution:published.distribution,message:`${draft.hazard} issued live for ${draft.zoneCode}. Public maps and Mattermost distribution were processed.`});
        }finally{wfoAutoDraftIssuing.delete(draft.id);}
        return true;
      }
      draft.status=decision==="approve"?"approved":"rejected";draft.decidedAt=new Date().toISOString();draft.decidedBy=String(session.username||"operator").slice(0,80);draft.decisionNote=String(payload.note||"").slice(0,500);draft.liveIssuance=false;
      saveWfoAutoDrafts(store.drafts);try{recordAccessEvent(request,session,`wfo-auto-draft-${decision}d`,{page:"/wfo",draftId:draft.id,wfo:draft.wfo,zone:draft.zoneCode,hazard:draft.hazard});}catch{/* decision remains saved */}
      sendJson(response,200,{draft,message:decision==="approve"?"Draft approved and staged for Hazard Services issuance. No live product was transmitted.":"Draft rejected."});
    }catch(error){sendJson(response,400,{error:error.message});}
    return true;
  }

  if (request.method === "POST" && requestUrl.pathname === "/api/wfo-automation/evaluate") {
    if (!session.authenticated) { sendJson(response, 401, { error: "SSO authentication required" }); return true; }
    try {
      const payload = JSON.parse((await readRequestBody(request)) || "{}");
      const office = cleanWfoAutomationOffice(payload.office);
      if (!office) { sendJson(response, 400, { error: "A valid three-character WFO is required" }); return true; }
      const wantsFire = office.products.some((item) => ["RFW", "FWW"].includes(item));
      const wantsPublic = office.products.some((item) => ["NPW", "WSW", "CFW", "AQA"].includes(item));
      office.zones = [...(wantsFire ? zonesForWfo(office.wfo, "fire") : []), ...(wantsPublic ? zonesForWfo(office.wfo, "public") : [])];
      if (!office.zones.length) { sendJson(response, 404, { error: `No applicable AWIPS zones were found for ${office.wfo}` }); return true; }
      const results = await mapWithConcurrency(office.zones, 8, async (zone) => {
        try { return await evaluateFireZone(zone, office, wfoNdfdBulkZoneIndex.get(`${zone.zoneType}:${zone.code}`)); }
        catch (error) { return { code: zone.code, qualifies: false, qualifyingHours: 0, recommendation: `Data unavailable: ${error.message}` }; }
      });
      const activeByZone = await activeNwsAlertsByZone(office.zones);
      const activeOwnAlerts = activeOwnAutomationAlerts();
      results.forEach((result) => {
        result.activeNwsAlerts = activeByZone.get(result.code) || [];
        result.candidateActions = reconcileAutomationCandidates(result.possibleAlerts, { wfo:office.wfo, zone:result.code }, activeOwnAlerts);
        result.activeOwnAlerts = result.candidateActions.flatMap((candidate) => candidate.existing || []).filter((alert,index,list) => list.findIndex((item) => item.id === alert.id) === index);
        result.newCandidates = result.candidateActions.filter((candidate) => !candidate.blocked).map((candidate) => candidate.hazard);
        result.duplicateBlocked = result.candidateActions.filter((candidate) => candidate.blocked).length;
        if (result.duplicateBlocked) result.recommendation = `ZASNET ACTIVE — NEW BLOCKED: ${result.candidateActions.filter((candidate)=>candidate.blocked).map((candidate)=>candidate.hazard).join(", ")} · ${result.recommendation}`;
        if (result.activeNwsAlerts.length) {
          result.recommendation = `ACTIVE NWS: ${result.activeNwsAlerts.join(", ")} · ${result.recommendation}`;
        }
      });
      const current = loadWfoAutomation();
      current.history = [{ at: new Date().toISOString(), by: String(session.username || "operator").slice(0, 80), wfo: office.wfo, action: `forecast-evaluated (${results.filter((item) => item.qualifies).length}/${results.length} qualifying)` }, ...(current.history || [])].slice(0, 300);
      current.updatedAt = new Date().toISOString();
      fs.writeFileSync(wfoAutomationFile, JSON.stringify(current, null, 2));
      sendJson(response, 200, { wfo: office.wfo, evaluatedAt: current.updatedAt, results, history: current.history });
    } catch (error) { sendJson(response, 400, { error: "Could not evaluate forecast zones", detail: error.message }); }
    return true;
  }

  if (requestUrl.pathname === "/api/ops/admin/map-regions") {
    if (!canAdministerHazardTemplates(session)) {
      sendJson(response, 403, { error: "Administrator permission required" });
      return true;
    }
    if (request.method === "GET") {
      sendJson(response, 200, loadTemporaryMapRegions());
      return true;
    }
    if (request.method === "PUT") {
      try {
        const payload = JSON.parse((await readRequestBody(request)) || "{}");
        const saved = saveTemporaryMapRegions(cleanTemporaryMapRegions(payload.regions), session);
        try { recordAccessEvent(request, session, "temporary-map-regions-updated", { page: "/admin" }); } catch { /* save remains valid */ }
        sendJson(response, 200, saved);
      } catch (error) {
        sendJson(response, 400, { error: "Invalid temporary map regions", detail: error.message });
      }
      return true;
    }
    sendJson(response, 405, { error: "Method not allowed" });
    return true;
  }

  if (requestUrl.pathname === "/api/ops/admin/wrf-operations-update") {
    if (!canAdministerHazardTemplates(session)) {
      sendJson(response, 403, { error: "Administrator permission required" });
      return true;
    }
    if (request.method === "GET") {
      sendJson(response, 200, await buildPublicWrfOperationsUpdate({ includeDraft: true }));
      return true;
    }
    if (request.method === "PUT") {
      try {
        const payload = JSON.parse((await readRequestBody(request)) || "{}");
        saveWrfOperationsUpdate(payload, session);
        sendJson(response, 200, await buildPublicWrfOperationsUpdate({ includeDraft: true }));
      } catch (error) {
        sendJson(response, 400, { error: "Invalid WRF operations update", detail: error.message });
      }
      return true;
    }
    sendJson(response, 405, { error: "Method not allowed" });
    return true;
  }

  if (requestUrl.pathname === "/api/ops/admin/ncep-forecast-integration") {
    if (!canAdministerHazardTemplates(session)) {
      sendJson(response, 403, { error: "Administrator permission required" });
      return true;
    }
    if (request.method !== "GET") {
      sendJson(response, 405, { error: "Forecast submissions are not activated" });
      return true;
    }
    if(requestUrl.searchParams.get("refresh")==="1"){
      ncepCapabilitiesCache={expires:0,value:null};
      ncepProductsCache={expires:0,value:null};
      ncepHrrrRunsCache={expires:0,value:[]};
    }
    let capabilities=null,readiness=null,availableRuns=[];
    try{
      [capabilities,readiness]=await Promise.all([getNcepForecastCapabilities(),getNcepProductReadiness()]);
      availableRuns=await getNcepHrrrRuns(capabilities);
    }catch(error){sendJson(response,502,{error:"WRF capabilities unavailable",detail:error.message});return true;}
    sendJson(response, 200, {
      prepared: true,
      submissionsEnabled: ncepForecastSubmissionsEnabled,
      apiKeyConfigured: Boolean(ncepForecastApiKey),
      apiBase: ncepForecastApiBase.toString(),
      domains: Object.keys(capabilities.domains||{}),
      intervals: [...ncepForecastIntervals],
      spacings: [...ncepForecastSpacings],
      forecastHours: [...ncepForecastHours],
      frequencies: ["once","hourly","scheduled"],
      products: readiness.products||capabilities.products||[],
      packages: readiness.packages||[],
      availableRuns,
      capabilities,
      statuses: [...ncepForecastStatuses],
      submissionRouteExposed: true,
      note: ncepForecastSubmissionsEnabled ? "Approval-queue submissions are enabled. Every request remains pending until approved in the NCEP dashboard." : "Forecast submission is configured but not enabled."
    });
    return true;
  }

  if (requestUrl.pathname === "/api/ops/admin/ncep-forecast-requests") {
    if (!canAdministerHazardTemplates(session)) {
      sendJson(response,403,{error:"Administrator permission required"});return true;
    }
    if(request.method==="GET"){
      const recurring=loadTrackedNcepForecastRequests()
        .filter((entry)=>entry.frequency==="hourly"||entry.frequency==="scheduled")
        .sort((a,b)=>Date.parse(b.submittedAt||0)-Date.parse(a.submittedAt||0));
      const requests=await Promise.all(recurring.map(async(entry)=>{
        try{
          const result=await ncepForecastApiRequest(`requests/${safeNcepForecastRequestId(entry.requestId)}`);
          const normalized=normalizeNcepForecastStatus(result.payload);
          return {...entry,...result.payload,...normalized};
        }catch(error){return {...entry,error:error.message};}
      }));
      sendJson(response,200,{requests});
      return true;
    }
    if(request.method!=="POST"){sendJson(response,405,{error:"Method not allowed"});return true;}
    try{
      const payload=JSON.parse((await readRequestBody(request))||"{}"),regionId=String(payload.regionId||"");
      const region=loadTemporaryMapRegions({activeOnly:true}).regions.find((entry)=>entry.id===regionId);
      if(!region) throw new Error("Select and publish an active temporary region first");
      const assignedDomains=Array.isArray(region.domains)&&region.domains.length?region.domains:[region.domain].filter(Boolean);
      const selectedDomain=String(payload.domain||region.domain||"").toUpperCase();
      if(!ncepForecastDomains.has(selectedDomain)||!assignedDomains.includes(selectedDomain)) throw new Error("Choose one of the domains assigned to this temporary region");
      const frequency=String(payload.frequency||"once").toLowerCase();
      const requestBody={
        external_id:String(payload.externalId||"").slice(0,120),
        name:String(payload.name||region.label).trim().slice(0,160),
        domain:selectedDomain,
        frequency,
        initialization:String(payload.initialization||"").toUpperCase(),
        physics_preset:String(payload.physicsPreset||"OPERATIONAL"),
        spacing:Number(payload.spacing),
        interval:Number(payload.interval),
        products:Array.isArray(payload.products)?payload.products.map(String):[],
        packages:Array.isArray(payload.packages)?payload.packages.map(String):[]
      };
      if(payload.boundsConfirmed!==true) throw new Error("Confirm the drawn domain bounds before submitting");
      const [west,south,east,north]=Array.isArray(region.bbox)?region.bbox.map(Number):[];
      const submittedBounds=payload.bounds&&typeof payload.bounds==="object"?[payload.bounds.west,payload.bounds.south,payload.bounds.east,payload.bounds.north].map(Number):[];
      if(submittedBounds.length!==4||submittedBounds.some((value,index)=>!Number.isFinite(value)||Math.abs(value-[west,south,east,north][index])>0.000001)) throw new Error("The drawn domain changed; publish the mesoscale zone and confirm its coordinates again");
      requestBody.bounds={west,south,east,north};
      const expandedDisplayBbox=expandWeatherMapBboxToFrame([west,south,east,north],1400,654);
      const displayCenter=[(west+east)/2,(south+north)/2],displayWidth=Math.min(30,(expandedDisplayBbox[2]-expandedDisplayBbox[0])*1.000002),displayHeight=Math.min(24,(expandedDisplayBbox[3]-expandedDisplayBbox[1])*1.000002);
      const displayBbox=[displayCenter[0]-displayWidth/2,displayCenter[1]-displayHeight/2,displayCenter[0]+displayWidth/2,displayCenter[1]+displayHeight/2];
      const displayBounds={west:displayBbox[0],south:displayBbox[1],east:displayBbox[2],north:displayBbox[3]};
      const submittedDisplay=payload.displayBounds&&typeof payload.displayBounds==="object"?[payload.displayBounds.west,payload.displayBounds.south,payload.displayBounds.east,payload.displayBounds.north].map(Number):[];
      if(submittedDisplay.length!==4||submittedDisplay.some((value,index)=>!Number.isFinite(value)||Math.abs(value-displayBbox[index])>0.000001))throw new Error("The displayed map viewport changed; reload the admin page and confirm the coordinates again");
      requestBody.display_bounds=displayBounds;
      if(frequency!=="once"){
        requestBody.schedule_start=String(payload.scheduleStart||"");
        requestBody.schedule_end=String(payload.scheduleEnd||"");
        requestBody.forecast_hours=Number(payload.forecastHours);
        requestBody.cadence_hours=Number(payload.cadenceHours);
      }else{
        requestBody.cycle=String(payload.cycle||"latest");
        requestBody.coverage_start=String(payload.coverageStart||"");
        requestBody.coverage_end=String(payload.coverageEnd||"");
      }
      const [capabilities,readiness]=await Promise.all([getNcepForecastCapabilities(),getNcepProductReadiness()]);
      assertNcepCapabilitySelection(capabilities,requestBody,readiness);
      const result=await submitNcepForecastRequest(requestBody,{regionId:region.id});
      trackNcepForecastRequest({requestId:result.requestId,externalId:result.externalId,status:result.status,regionId:region.id,name:requestBody.name,domain:selectedDomain,bounds:region.bbox,displayBounds,frequency,initialization:requestBody.initialization,physicsPreset:requestBody.physics_preset||"OPERATIONAL",spacing:requestBody.spacing,products:requestBody.products,packages:requestBody.packages,cadenceHours:requestBody.cadence_hours,cycle:requestBody.cycle,coverageStart:requestBody.coverage_start,coverageEnd:requestBody.coverage_end,scheduleStart:requestBody.schedule_start,scheduleEnd:requestBody.schedule_end,forecastHours:requestBody.forecast_hours,interval:requestBody.interval,submittedAt:new Date().toISOString()});
      try{recordAccessEvent(request,session,"ncep-forecast-requested",{page:"/admin",regionId:region.id,domain:selectedDomain,requestId:result.requestId});}catch{/* submission remains valid */}
      sendJson(response,202,{...result,region:{id:region.id,label:region.label,domain:selectedDomain,bbox:region.bbox,displayBounds}});
    }catch(error){
      const upstreamStatus=Number(error.status)||0,status=upstreamStatus===401||upstreamStatus===403?upstreamStatus:upstreamStatus===409||upstreamStatus===429?upstreamStatus:upstreamStatus>=500?502:400;
      sendJson(response,status,{error:error.message,detail:error.payload||undefined});
    }
    return true;
  }

  const ncepRequestMatch=requestUrl.pathname.match(/^\/api\/ops\/admin\/ncep-forecast-requests\/(req-[A-Za-z0-9_-]{1,100})(\/products)?$/);
  if(ncepRequestMatch){
    if(!canAdministerHazardTemplates(session)){sendJson(response,403,{error:"Administrator permission required"});return true;}
    try{
      if(request.method==="GET"){
        if(ncepRequestMatch[2])sendJson(response,200,await getNcepForecastRequestProducts(ncepRequestMatch[1]));
        else{
          const result=await ncepForecastApiRequest(`requests/${safeNcepForecastRequestId(ncepRequestMatch[1])}`),normalized=normalizeNcepForecastStatus(result.payload);
          trackNcepForecastRequest({requestId:ncepRequestMatch[1],status:normalized.status,nextRunAt:normalized.nextRunAt});
          sendJson(response,200,{...result.payload,...normalized});
        }
      }else if(request.method==="PATCH"&&!ncepRequestMatch[2]){
        const payload=JSON.parse((await readRequestBody(request))||"{}");
        const badRequest=(message)=>Object.assign(new Error(message),{status:400});
        const cleanBounds=(value,label)=>{
          if(!value||typeof value!=="object")throw badRequest(`${label} is required`);
          const bounds={west:Number(value.west),south:Number(value.south),east:Number(value.east),north:Number(value.north)};
          if(Object.values(bounds).some((number)=>!Number.isFinite(number)))throw badRequest(`${label} must contain numeric north, south, east, and west values`);
          if(bounds.west < -180||bounds.east > 180||bounds.south < -90||bounds.north > 90||bounds.west>=bounds.east||bounds.south>=bounds.north)throw badRequest(`${label} contains invalid coordinates`);
          return bounds;
        };
        const bounds=cleanBounds(payload.bounds,"bounds"),body={bounds};
        if(payload.display_bounds){
          const displayBounds=cleanBounds(payload.display_bounds,"display_bounds");
          if(displayBounds.west>bounds.west||displayBounds.east<bounds.east||displayBounds.south>bounds.south||displayBounds.north<bounds.north)throw badRequest("display_bounds must fully contain bounds");
          body.display_bounds=displayBounds;
        }
        const result=await ncepForecastApiRequest(`requests/${safeNcepForecastRequestId(ncepRequestMatch[1])}`,{method:"PATCH",body,retries:0});
        const tracked=loadTrackedNcepForecastRequests().find((entry)=>entry.requestId===ncepRequestMatch[1])||{};
        trackNcepForecastRequest({...tracked,requestId:ncepRequestMatch[1],bounds:[bounds.west,bounds.south,bounds.east,bounds.north],displayBounds:body.display_bounds||bounds});
        try{recordAccessEvent(request,session,"ncep-schedule-bounds-amended",{page:"/admin",requestId:ncepRequestMatch[1],bounds});}catch{/* amendment remains valid */}
        sendJson(response,result.status,{...result.payload});
      }else sendJson(response,405,{error:"Method not allowed"});
    }catch(error){
      const upstreamStatus=Number(error.status)||0;sendJson(response,upstreamStatus>=400&&upstreamStatus<500?upstreamStatus:(error instanceof SyntaxError?400:502),{error:error.message,detail:error.payload||undefined});
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/ops/admin/map-base.svg") {
    if (!canAdministerHazardTemplates(session)) {
      sendJson(response, 403, { error: "Administrator permission required" });
      return true;
    }
    response.writeHead(200, { "Content-Type": "image/svg+xml; charset=utf-8", "Cache-Control": "private, max-age=86400" });
    response.end(renderAdminMapBaseSvg());
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/native/hazard/zone-at") {
    const wfo = String(requestUrl.searchParams.get("wfo") || "").replace(/^K/i, "").toUpperCase();
    const type = ["county", "public", "fire", "marine"].includes(requestUrl.searchParams.get("type")) ? requestUrl.searchParams.get("type") : "public";
    const lat = Number(requestUrl.searchParams.get("lat"));
    const lon = Number(requestUrl.searchParams.get("lon"));
    if (!/^[A-Z0-9]{3}$/.test(wfo) || !Number.isFinite(lat) || !Number.isFinite(lon)) {
      sendJson(response, 400, { error: "Expected WFO, zone type, latitude, and longitude" });
      return true;
    }
    zonesForWfo(wfo, type);
    const fileKey = type === "public" ? "public-zones" : type === "marine" ? "marine-zones" : type === "county" ? "counties" : "fire-zones";
    const feature = (wfoZoneCaches.get(fileKey) || []).find((candidate) =>
      String(candidate.properties?.CWA || candidate.properties?.WFO || "").toUpperCase() === wfo && pointInGeometry([lon, lat], candidate.geometry)
    );
    if (!feature) {
      sendJson(response, 404, { error: "No matching zone at this map location" });
      return true;
    }
    const rings = [];
    const collectRings = (value) => {
      if (!Array.isArray(value)) return;
      if (value.length >= 3 && Array.isArray(value[0]) && Number.isFinite(Number(value[0][0])) && Number.isFinite(Number(value[0][1]))) {
        rings.push(value);
        return;
      }
      value.forEach(collectRings);
    };
    collectRings(feature.geometry?.coordinates);
    const ring = rings.sort((a, b) => b.length - a.length)[0] || [];
    const step = Math.max(1, Math.ceil(ring.length / 180));
    const outline = ring.filter((_, index) => index % step === 0).map((point) => [Number(point[1]), Number(point[0])]);
    if (outline.length && (outline[0][0] !== outline.at(-1)[0] || outline[0][1] !== outline.at(-1)[1])) outline.push(outline[0]);
    const code = zoneFeatureCode(feature, type);
    const name = String(feature.properties?.COUNTYNAME || feature.properties?.NAME || feature.properties?.SHORTNAME || code);
    const active = [...(loadOpsProducts().warnings || []), ...(loadGfeProducts().events || [])];
    const conflicts = active.filter((item) => item?.status !== "cancelled" && item?.status !== "expired" && [item.zoneIds, item.zones?.map((zone) => zone?.id)].flat(2).filter(Boolean).includes(code)).slice(0, 8).map((item) => ({ id: item.id, name: item.productName || item.hazardName || item.product || item.hazardCode }));
    sendJson(response, 200, { wfo, type, code, name, outline, conflicts });
    return true;
  }

  if (requestUrl.pathname === "/api/gfe/products") {
    if (request.method === "GET") {
      const store = loadGfeProducts();
      sendJson(response, 200, { updatedAt: store.updatedAt, events: store.events || [] });
      return true;
    }
    if (request.method === "PUT") {
      try {
        const payload = JSON.parse((await readRequestBody(request)) || "{}");
        const event = payload.event;
        if (!event || !event.id || !event.wfo || !event.hazardCode || !event.etn) {
          sendJson(response, 400, { error: "Expected a GFE event with id, WFO, hazard code, and ETN" });
          return true;
        }
        if (!sessionAllowsWorkstationWfo(session, event.wfo)) {
          sendJson(response, 403, { error: "Workstation is not authorized for this WFO" });
          return true;
        }
        const result = await publishGfeWarningEvent(event, session, request, { requestPath: "/api/gfe/products" });
        sendJson(response, 200, { event: result.event, updatedAt: result.updatedAt, distribution: result.distribution });
      } catch (error) {
        sendJson(response, 400, { error: "Invalid GFE event payload", detail: error.message });
      }
      return true;
    }
  }

  if (requestUrl.pathname === "/api/ops/warning-locks") {
    const now = Date.now();
    for (const [id, lock] of warningEditLocks) {
      if (!lock || lock.expiresAt <= now) warningEditLocks.delete(id);
    }
    const warningId = String(requestUrl.searchParams.get("warningId") || "").slice(0, 160);
    if (request.method === "GET") {
      const locks = warningId ? [warningEditLocks.get(warningId)].filter(Boolean) : [...warningEditLocks.values()];
      sendJson(response, 200, { locks });
      return true;
    }
    if (request.method === "POST") {
      try {
        const payload = JSON.parse((await readRequestBody(request)) || "{}");
        const id = String(payload.warningId || "").slice(0, 160);
        const sessionId = String(payload.sessionId || "").slice(0, 80);
        const warningWfo = String(payload.wfo || "").toUpperCase().slice(0, 8);
        const operatingWfo = String(payload.operatingWfo || "").toUpperCase().slice(0, 8);
        const mutualAid = Boolean(payload.mutualAid);
        if (!id || !sessionId || !warningWfo || !sessionAllowsWorkstationWfo(session, warningWfo) || (operatingWfo !== warningWfo && !mutualAid)) {
          sendJson(response, 403, { error: "This warning belongs to another WFO; enable Mutual Aid to edit it" });
          return true;
        }
        const existing = warningEditLocks.get(id);
        const sameOwner = existing && existing.username === session.username && existing.sessionId === sessionId;
        if (existing && !sameOwner) {
          sendJson(response, 423, { error: "Warning is locked for editing", lock: existing });
          return true;
        }
        const lock = { warningId: id, wfo: warningWfo, username: session.username, operator: session.displayName || session.username, sessionId, acquiredAt: sameOwner ? existing.acquiredAt : new Date(now).toISOString(), expiresAt: now + warningEditLockMs };
        warningEditLocks.set(id, lock);
        sendJson(response, 200, { lock });
      } catch (error) {
        sendJson(response, 400, { error: "Invalid warning lock payload", detail: error.message });
      }
      return true;
    }
    if (request.method === "DELETE") {
      const existing = warningEditLocks.get(warningId);
      const sessionId = String(requestUrl.searchParams.get("sessionId") || "");
      if (existing && existing.username === session.username && existing.sessionId === sessionId) warningEditLocks.delete(warningId);
      sendJson(response, 200, { released: !warningEditLocks.has(warningId) });
      return true;
    }
  }

  if (requestUrl.pathname === "/api/ops/products") {
    if (request.method === "GET") {
      const store = loadOpsProducts();
      const scope = requestUrl.searchParams.get("scope") || "";
      const activeOnly = scope === "active" || scope === "active-spc";
      const warnings = activeOnly
        ? (store.warnings || []).filter((warning) => warning?.status === "active" && (!warning.expiresAt || Date.parse(warning.expiresAt) > Date.now())).filter((warning) => scope !== "active-spc" || warning?.kind === "spc-watch")
        : store.warnings || [];
      sendJson(response, 200, {
        updatedAt: store.updatedAt,
        warnings,
        count: warnings.length
      });
      return true;
    }

    if (request.method === "PUT") {
      try {
        const body = await readRequestBody(request);
        const payload = JSON.parse(body || "{}");
        const warnings = Array.isArray(payload.warnings)
          ? payload.warnings
          : Array.isArray(payload)
            ? payload
            : null;
        if (!warnings) {
          sendJson(response, 400, { error: "Expected { warnings: [...] }" });
          return true;
        }
        if (session.via === "workstation" && warnings.some((warning) => !sessionAllowsWorkstationWfo(session, warning?.wfo || warning?.office))) {
          sendJson(response, 403, { error: "Workstation is not authorized for one or more warning WFOs" });
          return true;
        }
        const merged = mergeProductStore(loadOpsProducts(), warnings, { retentionHours: 72 });
        const saved = saveOpsProducts({ warnings: merged });
        sendJson(response, 200, {
          updatedAt: saved.updatedAt,
          count: saved.warnings.length,
          merged: true
        });
      } catch (error) {
        sendJson(response, 400, { error: "Invalid ops products payload", detail: error.message });
      }
      return true;
    }
  }

  // Allocate SPC watch numbers on the server so a page refresh, a different
  // operator, or an empty active-watch list can never restart the sequence.
  if (request.method === "POST" && requestUrl.pathname === "/api/spc/watch-number") {
    const watchNumber = reserveNextSpcWatchNumber();
    sendJson(response, 200, { watchNumber, label: String(watchNumber).padStart(4, "0") });
    return true;
  }

  // WarnGen ETN sequence: always derived from server history (ops + public + GFE).
  // GET peeks previous/next without consuming; POST reserves the next number.
  if (requestUrl.pathname === "/api/ops/next-etn") {
    if (request.method === "GET") {
      const wfo = requestUrl.searchParams.get("wfo") || "";
      const product = requestUrl.searchParams.get("product") || "";
      sendJson(response, 200, peekWarningEtn(wfo, product));
      return true;
    }
    if (request.method === "POST") {
      try {
        const body = await readRequestBody(request);
        const payload = JSON.parse(body || "{}");
        const allocated = reserveNextWarningEtn(payload.wfo, payload.product);
        console.info(
          `[etn] reserved ${allocated.wfo} ${allocated.product} ${allocated.label} (previous ${String(allocated.previous).padStart(4, "0")})`
        );
        sendJson(response, 200, allocated);
      } catch (error) {
        sendJson(response, 400, { error: "Unable to allocate ETN", detail: error.message });
      }
      return true;
    }
  }

  if (requestUrl.pathname === "/api/ops/drafts") {
    if (request.method === "GET") {
      const drafts = freshOpsDrafts(loadOpsDrafts());
      const saved = saveOpsDrafts(drafts);
      sendJson(response, 200, {
        updatedAt: saved.updatedAt,
        drafts: saved.drafts,
        count: saved.drafts.length
      });
      return true;
    }

    if (request.method === "PUT") {
      try {
        const body = await readRequestBody(request);
        const payload = JSON.parse(body || "{}");
        const draft = cleanOpsDraftForStore(payload.draft || payload);
        if (!draft) {
          sendJson(response, 400, { error: "Expected a draft with sessionId and geometry" });
          return true;
        }
        const bySession = new Map();
        freshOpsDrafts(loadOpsDrafts()).forEach((item) => bySession.set(item.sessionId, item));
        bySession.set(draft.sessionId, draft);
        const saved = saveOpsDrafts([...bySession.values()]);
        sendJson(response, 200, {
          updatedAt: saved.updatedAt,
          count: saved.drafts.length,
          draft
        });
      } catch (error) {
        sendJson(response, 400, { error: "Invalid ops draft payload", detail: error.message });
      }
      return true;
    }

    if (request.method === "DELETE") {
      try {
        let sessionId = requestUrl.searchParams.get("sessionId") || "";
        if (!sessionId) {
          const body = await readRequestBody(request);
          if (body) {
            const payload = JSON.parse(body);
            sessionId = payload.sessionId || "";
          }
        }
        if (!sessionId) {
          sendJson(response, 400, { error: "Expected sessionId" });
          return true;
        }
        const drafts = freshOpsDrafts(loadOpsDrafts()).filter((draft) => draft.sessionId !== sessionId);
        const saved = saveOpsDrafts(drafts);
        sendJson(response, 200, {
          updatedAt: saved.updatedAt,
          count: saved.drafts.length,
          cleared: sessionId
        });
      } catch (error) {
        sendJson(response, 400, { error: "Invalid ops draft delete", detail: error.message });
      }
      return true;
    }
  }

  // ── Public alerts map API ──────────────────────────────────────────────
  if (request.method === "GET" && requestUrl.pathname === "/api/public/tropics") {
    return proxyHttpsGet("https://www.nhc.noaa.gov/CurrentStorms.json", response, { cacheControl: "public, max-age=300, stale-while-revalidate=300" });
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/tropics/basemap") {
    sendJson(response, 200, loadPublicTropicsMapBase());
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/tropics/graphics") {
    try {
      const requestedView = String(requestUrl.searchParams.get("view") || "overview").toLowerCase();
      const upstreamPaths = {
        overview: "/v1/satellite/tropical/overview/nhc/frames",
        atlantic: "/v1/satellite/tropical/outlook/atlantic/frames",
        "east-pacific": "/v1/satellite/tropical/outlook/east-pacific/frames",
        "west-pacific": "/v1/satellite/tropical/outlook/west-pacific/frames"
      };
      const upstreamPath = upstreamPaths[requestedView];
      if (!upstreamPath) { sendJson(response, 400, { error:"Invalid tropical graphics view" }); return true; }
      const manifest = await fetchJson(`https://internal.zasnetwx.com${upstreamPath}`);
      const frames = (manifest.frames || []).slice(0, 12).map((frame) => ({
        ...frame,
        sourceImageUrl: frame.imageUrl,
        imageUrl: `/api/public/tropics/graphics/source.webp?url=${encodeURIComponent(frame.imageUrl)}`
      }));
      response.setHeader("Cache-Control", "public, max-age=30, stale-while-revalidate=90");
      sendJson(response, 200, { ...manifest, frames });
    } catch (error) { sendJson(response, 502, { error:"Tropical operational graphic unavailable", detail:error.message }); }
    return true;
  }
  if (["GET", "HEAD"].includes(request.method) && requestUrl.pathname === "/api/public/tropics/graphics/source.webp") {
    try {
      const source = new URL(String(requestUrl.searchParams.get("url") || ""));
      const validPath = /^\/api\/v1\/satellite\/tropical\/(?:overview\/nhc|outlook\/(?:atlantic|east-pacific|west-pacific))\/[A-Za-z0-9_-]+\/graphic\.webp$/.test(source.pathname);
      if (source.protocol !== "https:" || source.hostname !== "internal.zasnetwx.com" || !validPath) {
        sendJson(response, 400, { error:"Invalid tropical graphic URL" }); return true;
      }
      return proxyHttpsGet(source.toString(), response, { cacheControl:"public, max-age=31536000, immutable", contentType:"image/webp" });
    } catch (error) { sendJson(response, 400, { error:"Invalid tropical graphic URL", detail:error.message }); }
    return true;
  }
  if (["GET", "HEAD"].includes(request.method) && ["/api/public/tropics/outlook", "/api/public/tropics/outlook/"].includes(requestUrl.pathname)) {
    try {
      const requestedBasin = String(requestUrl.searchParams.get("basin") || "").trim().toLowerCase();
      if (requestedBasin && !["atlantic", "pacific"].includes(requestedBasin)) {
        sendPublicModelApi(request, response, 400, {
          error: "Invalid tropical outlook basin",
          detail: "basin must be atlantic or pacific"
        }, { cacheControl: "no-store" });
        return true;
      }
      const outlook = await nhcFormationOutlookGeoJson();
      const basinMatches = (feature) => !requestedBasin || (requestedBasin === "pacific"
        ? /pacific/i.test(String(feature?.properties?.BASIN || ""))
        : /atlantic/i.test(String(feature?.properties?.BASIN || "")));
      const filterCollection = (collection) => ({
        type: "FeatureCollection",
        features: (collection?.features || []).filter(basinMatches)
      });
      const payload = {
        schemaVersion: "1.0.0",
        basin: requestedBasin || "all",
        areas: filterCollection(outlook.areas),
        lines: filterCollection(outlook.lines),
        points: filterCollection(outlook.points),
        outlookCounts: requestedBasin
          ? { [requestedBasin]: Number(outlook.outlookCounts?.[requestedBasin]) || 0 }
          : outlook.outlookCounts,
        updatedAt: outlook.updatedAt
      };
      sendPublicModelApi(request, response, 200, payload, {
        contentType: "application/json; charset=utf-8",
        modifiedAt: outlook.updatedAt,
        cacheControl: "public, max-age=300, stale-while-revalidate=300"
      });
    } catch (error) {
      sendPublicModelApi(request, response, 502, {
        error: "Tropical formation outlook unavailable",
        detail: error.message
      }, { cacheControl: "no-store" });
    }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/tropics/map.svg") {
    try {
      const basin = requestUrl.searchParams.get("basin") === "pacific" ? "pacific" : "atlantic";
      const svg = await renderPublicTropicsSvg(basin);
      response.writeHead(200, { "Content-Type": "image/svg+xml; charset=utf-8", "Cache-Control": "public, max-age=120" });
      response.end(rethemePublicMapSvg(svg));
    } catch (error) { sendJson(response, 502, { error: "NHC tropical map unavailable", detail: error.message }); }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/tropics/storm") {
    try {
      const current = await fetchJson("https://www.nhc.noaa.gov/CurrentStorms.json");
      const id = String(requestUrl.searchParams.get("id") || "").toLowerCase();
      const storm = (current.activeStorms || []).find((item) => String(item.id).toLowerCase() === id);
      if (!storm) { sendJson(response, 404, { error: "Active NHC storm not found" }); return true; }
      const [cone, track, windAdvisories, surgeAdvisories] = await Promise.all([
        storm.trackCone?.kmzFile ? kmzToGeoJson(storm.trackCone.kmzFile, { stormId: storm.id, stormName: storm.name }) : { type: "FeatureCollection", features: [] },
        storm.forecastTrack?.kmzFile ? kmzToGeoJson(storm.forecastTrack.kmzFile, { stormId: storm.id, stormName: storm.name }) : { type: "FeatureCollection", features: [] },
        storm.windWatchesWarnings?.kmzFile ? kmzToGeoJson(storm.windWatchesWarnings.kmzFile, { stormId: storm.id, stormName: storm.name, advisorySource:"wind" }).catch(() => ({ type:"FeatureCollection", features:[] })) : { type:"FeatureCollection", features:[] },
        storm.stormSurgeWatchWarningGIS?.kmlFile ? fetchText(storm.stormSurgeWatchWarningGIS.kmlFile).then((kml) => kmlToGeoJson(kml, { stormId:storm.id, stormName:storm.name, advisorySource:"surge" })).catch(() => ({ type:"FeatureCollection", features:[] })) : { type:"FeatureCollection", features:[] }
      ]);
      sendJson(response, 200, { storm, cone, track, advisories:{ wind:windAdvisories, surge:surgeAdvisories } });
    } catch (error) { sendJson(response, 502, { error: "Official NHC cone unavailable", detail: error.message }); }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/tropics/storm-graphics/frames") {
    try {
      const id = String(requestUrl.searchParams.get("id") || "").toLowerCase();
      const product = String(requestUrl.searchParams.get("product") || "forecast_cone").toLowerCase();
      const allowedProducts = new Set(["forecast_cone", "track_guidance", "intensity", "storm_history"]);
      if (!/^[a-z]{2}\d{6}$/.test(id) || !allowedProducts.has(product)) {
        sendJson(response, 400, { error:"Invalid tropical storm graphic request" }); return true;
      }
      const manifest = await fetchJson(`https://internal.zasnetwx.com/api/v1/satellite/tropical/${encodeURIComponent(id)}/frames?product=${encodeURIComponent(product)}`);
      const frames = (manifest.frames || []).slice(0, 24).map((frame) => ({
        ...frame,
        sourceImageUrl: frame.imageUrl,
        imageUrl: `/api/public/tropics/storm-graphics/source.webp?url=${encodeURIComponent(frame.imageUrl)}`
      }));
      response.setHeader("Cache-Control", "public, max-age=30, stale-while-revalidate=90");
      sendJson(response, 200, { ...manifest, frames });
    } catch (error) { sendJson(response, 502, { error:"Tropical storm graphic unavailable", detail:error.message }); }
    return true;
  }
  if (["GET", "HEAD"].includes(request.method) && requestUrl.pathname === "/api/public/tropics/storm-graphics/source.webp") {
    try {
      const source = new URL(String(requestUrl.searchParams.get("url") || ""));
      const validPath = /^\/api\/v1\/satellite\/tropical\/[a-z]{2}\d{6}\/(?:forecast_cone|track_guidance|intensity|storm_history)\/(?:nhc-gis|nhc-atcf)\/[A-Za-z0-9_-]+\/graphic\.webp$/.test(source.pathname);
      if (source.protocol !== "https:" || source.hostname !== "internal.zasnetwx.com" || !validPath) {
        sendJson(response, 400, { error:"Invalid tropical storm graphic URL" }); return true;
      }
      return proxyHttpsGet(source.toString(), response, { cacheControl:"public, max-age=31536000, immutable", contentType:"image/webp" });
    } catch (error) { sendJson(response, 400, { error:"Invalid tropical storm graphic URL", detail:error.message }); }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/alert-map.svg") {
    return handlePublicAlertGraphic(requestUrl, response, request);
  }
  const publicAlertTextMatch = requestUrl.pathname.match(/^\/api\/public\/alerts\/(.+)\.txt$/);
  if (request.method === "GET" && publicAlertTextMatch) {
    const id = decodeURIComponent(publicAlertTextMatch[1]);
    const warning = (loadPublicAlerts().warnings || []).find((item) => item?.id === id);
    if (!warning?.text) {
      response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
      response.end("Warning text was not found.\n");
      return true;
    }
    const productId = String(warning.productId || `${warning.wfo || "ZWS"}${warning.product || ""}${warning.etn ? String(warning.etn).padStart(4, "0") : ""}`).replace(/[^A-Z0-9_-]/gi, "");
    response.writeHead(200, {
      "Content-Type": "text/plain; charset=utf-8",
      "Content-Disposition": `inline; filename="${productId || "warning"}.txt"`,
      "Cache-Control": "no-store, max-age=0",
      "Access-Control-Allow-Origin": "*",
      "X-Content-Type-Options": "nosniff"
    });
    response.end(`${warning.text.trim()}\n`);
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/public/wfo") {
    const code = String(requestUrl.searchParams.get("code") || "").replace(/^K/i, "").toUpperCase();
    const search = String(requestUrl.searchParams.get("q") || "").trim().toLowerCase();
    if (search && !code) {
      const matches = loadPublicCwaGeometry().filter((item) => {
        const p = item.properties || {};
        return [p.CWA, p.WFO, p.CITY, p.CITYSTATE, p.ST].some((value) => String(value || "").toLowerCase().includes(search));
      }).slice(0, 8).map((item) => {
        const p = item.properties || {};
        return { code: String(p.CWA || p.WFO || ""), city: p.CITY || "", state: p.ST || "", cityState: p.CITYSTATE || "" };
      });
      sendJson(response, 200, { matches });
      return true;
    }
    const feature = /^[A-Z0-9]{3}$/.test(code)
      ? loadPublicCwaGeometry().find((item) => String(item.properties?.CWA || item.properties?.WFO || "").toUpperCase() === code)
      : null;
    if (!feature) {
      sendJson(response, 404, { error: "Unknown WFO" });
      return true;
    }
    const props = feature.properties || {};
    sendJson(response, 200, { code, city: props.CITY || "", state: props.ST || "", cityState: props.CITYSTATE || code });
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/public/summary") {
    const live = dedupeLiveProducts(livePublicWarnings(loadPublicAlerts()));
    const byProduct = {};
    const offices = new Set();
    live.forEach((product) => {
      const name = publicProductDisplayName(product.product, product.productName);
      byProduct[name] = (byProduct[name] || 0) + 1;
      (product.counties || []).forEach((area) => {
        const cwa = String(area?.cwa || area?.CWA || "").replace(/^K/i, "").toUpperCase();
        if (/^[A-Z0-9]{3}$/.test(cwa)) offices.add(cwa);
      });
      const issuer = String(product.wfo || "").replace(/^K/i, "").toUpperCase();
      if (/^[A-Z0-9]{3}$/.test(issuer) && issuer !== "SPC") offices.add(issuer);
    });
    sendPublicJson(response, 200, { updatedAt: loadPublicAlerts().updatedAt || null, total: live.length, offices: offices.size, products: byProduct }, "application/json; charset=utf-8");
    return true;
  }

  const activeAlertScopeMatch = requestUrl.pathname.match(/^\/api\/public\/alerts\/active\/(area|zone)\/([^/]+)$/);
  if (activeAlertScopeMatch) requestUrl.searchParams.set(activeAlertScopeMatch[1], decodeURIComponent(activeAlertScopeMatch[2]));
  if (request.method === "GET" && (["/api/public/alerts/active", "/api/public/alerts/active/count"].includes(requestUrl.pathname) || activeAlertScopeMatch)) {
    const payload = weatherGovAlertsResponse(requestUrl, request);
    if (requestUrl.pathname.endsWith("/count")) {
      const counts = {};
      payload.features.forEach((feature) => { counts[feature.properties.event] = (counts[feature.properties.event] || 0) + 1; });
      sendPublicJson(response, 200, { total: payload.features.length, events: counts }, "application/json; charset=utf-8");
    } else {
      sendPublicJson(response, 200, payload);
    }
    return true;
  }

  const publicAlertJsonMatch = requestUrl.pathname.match(/^\/api\/public\/alerts\/([^/]+)$/);
  if (request.method === "GET" && publicAlertJsonMatch) {
    const id = decodeURIComponent(publicAlertJsonMatch[1]);
    const host = request.headers.host || `localhost:${port}`;
    const proto = getHeader(request, "x-forwarded-proto") || "http";
    const warning = dedupeLiveProducts(livePublicWarnings(loadPublicAlerts())).find((item) => {
      const feature = weatherGovAlertFeature(item, `${proto}://${host}`);
      return item.id === id || feature.properties.productId === id;
    });
    if (!warning) sendPublicJson(response, 404, { title: "Not Found", status: 404, detail: "Alert was not found or is no longer active." }, "application/problem+json; charset=utf-8");
    else sendPublicJson(response, 200, weatherGovAlertFeature(warning, `${proto}://${host}`));
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/public/alerts") {
    const store = loadPublicAlerts();
    const format = (requestUrl.searchParams.get("format") || "json").toLowerCase();
    const wfo = String(requestUrl.searchParams.get("wfo") || "").replace(/^K/i, "").toUpperCase();
    // Catalog: ~50KB product index for public map drawers (no geometries/text).
    if (format === "catalog" || format === "index") {
      sendPublicJson(response, 200, publicAlertsCatalog(store, { wfo }), "application/json; charset=utf-8");
      return true;
    }
    if (format === "geojson") {
      const includeText = requestUrl.searchParams.get("text") !== "0";
      const geojson = publicAlertsGeoJson(store, { includeText });
      // Filter without mutating the shared cache object.
      if (/^[A-Z0-9]{3}$/.test(wfo)) {
        sendPublicJson(response, 200, {
          ...geojson,
          features: geojson.features.filter((feature) => publicAlertFeatureMatchesWfo(feature, wfo))
        });
        return true;
      }
      sendPublicJson(response, 200, geojson);
      return true;
    }
    const live = livePublicWarnings(store);
    sendPublicJson(response, 200, {
      updatedAt: store.updatedAt,
      warnings: live,
      count: live.length
    }, "application/json; charset=utf-8");
    return true;
  }

  // Public map snapshots for Mattermost (no auth — Mattermost server fetches image_url)
  const snapshotMatch = requestUrl.pathname.match(/^\/api\/public\/snapshots\/([^/]+)\.png$/i);
  if ((request.method === "GET" || request.method === "HEAD") && snapshotMatch) {
    const safe = mapSnapshotFileId(decodeURIComponent(snapshotMatch[1]));
    const filePath = safe ? path.join(mapSnapshotsDir, `${safe}.png`) : null;
    if (!filePath || !fs.existsSync(filePath)) {
      response.writeHead(404, {
        "Content-Type": "text/plain; charset=utf-8",
        "Cache-Control": "no-store"
      });
      if (request.method !== "HEAD") response.end("Snapshot not found\n");
      else response.end();
      return true;
    }
    const stat = fs.statSync(filePath);
    response.writeHead(200, {
      "Content-Type": "image/png",
      "Content-Length": stat.size,
      "Cache-Control": "public, max-age=300",
      "Access-Control-Allow-Origin": "*"
    });
    if (request.method === "HEAD") {
      response.end();
      return true;
    }
    fs.createReadStream(filePath).pipe(response);
    return true;
  }

  // COD-style Warnings Server — GRLevel often HEAD-checks files before GET
  if (
    (request.method === "GET" || request.method === "HEAD") &&
    (requestUrl.pathname === "/warnings" || requestUrl.pathname.startsWith("/warnings/"))
  ) {
    return handleWarningsServerRequest(request, requestUrl, response);
  }

  // GRLevelX placefiles — TimeRange-animated by default (radar scrub / loop).
  // Prefer separate feeds: /placefile/warnings (outlines) + /placefile/watches (shaded).
  if (
    request.method === "GET" &&
    (requestUrl.pathname === "/api/public/placefile" ||
      requestUrl.pathname === "/api/public/placefile/animated" ||
      requestUrl.pathname === "/api/public/placefile/warnings" ||
      requestUrl.pathname === "/api/public/placefile/watches" ||
      requestUrl.pathname === "/placefile/warnings.txt" ||
      requestUrl.pathname === "/placefile/warnings" ||
      requestUrl.pathname === "/placefile/warnings_animated.txt" ||
      requestUrl.pathname === "/placefile/watches.txt" ||
      requestUrl.pathname === "/placefile/watches")
  ) {
    const store = loadPublicAlerts();
    const hostHeader = request.headers.host || `localhost:${port}`;
    const proto =
      getHeader(request, "x-forwarded-proto") ||
      (requestUrl.protocol ? requestUrl.protocol.replace(":", "") : "http");
    const baseUrl = `${proto}://${hostHeader}`;
    const mode = (requestUrl.searchParams.get("mode") || "animated").toLowerCase();
    const animated = mode !== "live" && !requestUrl.pathname.endsWith("/live");
    const hoursBack = Math.min(48, Math.max(1, Number(requestUrl.searchParams.get("hours") || 12)));
    const pathLower = requestUrl.pathname.toLowerCase();
    let productFilter = "all";
    if (pathLower.includes("watch")) {
      productFilter = "watches";
    } else if (pathLower.includes("warning")) {
      productFilter = "warnings";
    } else {
      // Query override: ?type=watches|warnings|all
      const typeParam = (requestUrl.searchParams.get("type") || "").toLowerCase();
      if (typeParam === "watches" || typeParam === "watch") {
        productFilter = "watches";
      } else if (typeParam === "warnings" || typeParam === "warning") {
        productFilter = "warnings";
      }
    }
    const body = buildGrlevelPlacefile(store, {
      baseUrl,
      animated,
      hoursBack,
      productFilter
    });
    console.log(
      `[placefile] GET ${requestUrl.pathname}${requestUrl.search || ""} -> 200 ${Buffer.byteLength(body)}b ` +
        `filter=${productFilter} mode=${animated ? "animated" : "live"} ` +
        `ua="${String(request.headers["user-agent"] || "").replace(/\s+/g, " ").slice(0, 80)}"`
    );
    response.writeHead(200, {
      "Content-Type": "text/plain; charset=utf-8",
      ...warningsServerNoCacheHeaders
    });
    response.end(body);
    return true;
  }

  if (request.method === "PUT" && requestUrl.pathname === "/api/public/alerts") {
    try {
      const body = await readRequestBody(request);
      const payload = JSON.parse(body || "{}");
      const warnings = Array.isArray(payload.warnings)
        ? payload.warnings
        : Array.isArray(payload)
          ? payload
          : null;
      if (!warnings) {
        sendJson(response, 400, { error: "Expected { warnings: [...] }" });
        return true;
      }
      if (session.via === "workstation" && warnings.some((warning) => !sessionAllowsWorkstationWfo(session, warning?.wfo || warning?.office))) {
        sendJson(response, 403, { error: "Workstation is not authorized for one or more warning WFOs" });
        return true;
      }
      // Optional: only score these ids on the distribution receipt (just-issued products).
      // Prevents old inventory still in the client list from failing the receipt.
      const focusIds = Array.isArray(payload.focusIds)
        ? payload.focusIds.map((id) => String(id || "").trim()).filter(Boolean).slice(0, 20)
        : [];
      // Retry failed Mattermost: re-post focused products even when lifecycle did not change.
      const forceNotifyMattermost = payload.notifyMattermost === true || payload.forceNotify === true;
      // Strip huge transient fields; keep map/placefile fields for warnings + SPC watches
      const cleaned = warnings
        .filter((w) => w && w.id && !w.practice)
        .map((w) => {
          const timeline = Array.isArray(w.timeline)
            ? w.timeline
                .filter((s) => s && (s.polygon || s.displayGeometry))
                .slice(-40)
                .map((s) => ({
                  validFrom: s.validFrom,
                  validTo: s.validTo,
                  action: s.action,
                  polygon: s.polygon,
                  location: s.location,
                  locationPhrase: s.locationPhrase,
                  expiresAt: s.expiresAt
                }))
            : [];
          const bulletinHistory = Array.isArray(w.bulletinHistory)
            ? w.bulletinHistory
                .filter((b) => b && b.text)
                .slice(-80)
                .map((b) => ({
                  validFrom: b.validFrom,
                  validTo: b.validTo,
                  action: b.action,
                  text: b.text,
                  polygon: b.polygon || w.polygon,
                  location: b.location,
                  locationPhrase: b.locationPhrase,
                  expiresAt: b.expiresAt,
                  updatedAt: b.updatedAt
                }))
            : [];
          return {
            id: w.id,
            kind: w.kind || (w.product === "TOA" || w.product === "SVA" ? "spc-watch" : "warning"),
            product: w.product,
            productId: w.productId,
            watchNumber: w.watchNumber,
            stormType: w.stormType,
            polygon: w.polygon,
            displayGeometry: w.displayGeometry || null,
            counties: w.counties,
            zones: w.zones,
            places: (w.places || []).slice(0, 40),
            location: w.location,
            locationPhrase: w.locationPhrase,
            locationOverride: w.locationOverride,
            lineStart: w.lineStart || null,
            lineEnd: w.lineEnd || null,
            lineTrace: Array.isArray(w.lineTrace) ? w.lineTrace.slice(0, 100) : [],
            projectedLineTrace: Array.isArray(w.projectedLineTrace) ? w.projectedLineTrace.slice(0, 100) : [],
            lineStartPhrase: w.lineStartPhrase || "",
            lineEndPhrase: w.lineEndPhrase || "",
            motion1: w.motion1 || null,
            motion2: w.motion2 || null,
            motion: w.motion,
            motionOverride: w.motionOverride,
            basis: w.basis,
            windId: w.windId,
            hailId: w.hailId,
            tornadoes: w.tornadoes,
            intenseTornadoes: w.intenseTornadoes,
            veryLargeHail: w.veryLargeHail,
            significantWind: w.significantWind,
            pds: w.pds,
            validMinutes: w.validMinutes,
            validHours: w.validHours,
            ctas: w.ctas,
            ffw: w.ffw,
            tor: w.tor,
            sps: w.sps,
            text: w.text,
            wfo: w.wfo,
            office: w.office,
            etn: w.etn,
            action: w.action,
            status: w.status,
            issuedAt: w.issuedAt,
            expiresAt: w.expiresAt,
            segment: w.segment,
            color: w.color,
            timeline,
            bulletinHistory,
            updatedAt: w.updatedAt || w.issuedAt || ""
          };
        });

      // MERGE by id — never let one browser's partial localStorage wipe another
      // session's live watch/warning. Client upserts what it knows; server keeps
      // other still-active products not present in this payload.
      const existing = loadPublicAlerts();
      const existingById = new Map((existing.warnings || []).filter((w) => w?.id).map((w) => [w.id, w]));
      const lifecycleChanged = cleaned.filter((warning) =>
        warningIsFreshForNotification(warning) &&
        warningLifecycleSignature(existingById.get(warning.id)) !== warningLifecycleSignature(warning)
      );
      const byId = new Map();
      (existing.warnings || []).forEach((w) => {
        if (w && w.id && isLivePublicWarning(w)) {
          byId.set(w.id, w);
        }
      });
      cleaned.forEach((w) => {
        // Client is authoritative for ids it sends (including CAN/EXP)
        const existing = byId.get(w.id);
        byId.set(w.id, {
          ...w,
          bulletinHistory: mergeBulletinHistories(existing && existing.bulletinHistory, w.bulletinHistory)
        });
      });
      // Keep active + recently cancelled (for GRLevel archive / TimeRange + COD server)
      const retentionMs = warningsServerRetentionHours * 3600_000;
      const nowMs = Date.now();
      const merged = [...byId.values()].filter((w) => {
        if (!w || !w.id) {
          return false;
        }
        if (w.status === "active") {
          if (w.expiresAt && new Date(w.expiresAt).getTime() < nowMs) {
            // Treat as expired but keep a few hours for archive
            const exp = new Date(w.expiresAt).getTime();
            return nowMs - exp < retentionMs;
          }
          return true;
        }
        if (w.status === "cancelled" || w.status === "expired") {
          const t = new Date(w.updatedAt || w.expiresAt || 0).getTime();
          return Number.isFinite(t) && nowMs - t < retentionMs;
        }
        return false;
      });

      const saved = savePublicAlerts({ warnings: merged });
      const warningsServerSync = saved._warningsServerSync || { ok: true, detail: "Synced" };
      delete saved._warningsServerSync;

      // Normal path: only lifecycle changes within the freshness window.
      // Retry path (notifyMattermost + focusIds): re-post those products even if
      // already stored (same signature) so "Retry failed" can finish Mattermost.
      let mattermostTargets = lifecycleChanged;
      if (forceNotifyMattermost && focusIds.length) {
        const savedById = new Map((saved.warnings || []).filter((w) => w?.id).map((w) => [w.id, w]));
        const cleanedById = new Map(cleaned.filter((w) => w?.id).map((w) => [w.id, w]));
        const forced = [];
        const seen = new Set();
        focusIds.forEach((id) => {
          if (seen.has(id)) return;
          const w = cleanedById.get(id) || savedById.get(id);
          if (!w || w.practice) return;
          seen.add(id);
          forced.push(w);
        });
        if (forced.length) {
          mattermostTargets = forced;
        }
      }

      let mattermostResults = [];
      if (mattermostNotificationsEnabled && mattermostTargets.length) {
        mattermostResults = await Promise.allSettled(
          mattermostTargets.map((warning) => postWarningToMattermost(warning))
        );
      }
      const distribution = buildAlertsDistributionReceipt({
        saved,
        cleaned,
        changedWarnings: mattermostTargets,
        focusIds,
        mattermostResults,
        warningsServerSync,
        forceNotify: forceNotifyMattermost
      });
      sendJson(response, 200, {
        updatedAt: saved.updatedAt,
        count: livePublicWarnings(saved).length,
        merged: true,
        warningsServer: "/warnings/",
        distribution
      });
    } catch (error) {
      sendJson(response, 400, { error: "Invalid public alerts payload", detail: error.message });
    }
    return true;
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/public/radar-wms") {
    return proxyNoaaRadarWms(requestUrl, response);
  }
  if (request.method === "GET" && ["/api/weather/surface-analysis", "/api/public/surface-analysis"].includes(requestUrl.pathname)) {
    return proxyNoaaSurfaceAnalysis(requestUrl, response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/weather/smoke") {
    return proxyNoaaSmoke(requestUrl, response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/weather/wpc-qpf72") {
    const qpfLayers = { "6": 7, "48": 8, "72": 9, "120": 10, "168": 11 };
    const period = String(requestUrl.searchParams.get("period") || "72");
    const layer = qpfLayers[period] || 9;
    try {
      let cached = wpcQpfCache.get(period);
      if (!cached || cached.expires <= Date.now()) {
        const query = new URLSearchParams({
          where: "1=1", outFields: "qpf,units,valid_time,issue_time,start_time,end_time",
          outSR: "4326", returnGeometry: "true", geometryPrecision: "3",
          maxAllowableOffset: "0.01", f: "geojson"
        });
        const pending = fetchJson(`https://mapservices.weather.noaa.gov/vector/rest/services/precip/wpc_qpf/MapServer/${layer}/query?${query}`);
        cached = { expires: Date.now() + wpcQpfCacheMs, pending };
        wpcQpfCache.set(period, cached);
        pending.then((payload) => { cached.payload = payload; delete cached.pending; }).catch(() => wpcQpfCache.delete(period));
      }
      sendJson(response, 200, cached.payload || await cached.pending);
    } catch (error) {
      sendJson(response, 502, { error: "WPC QPF unavailable", detail: error.message });
    }
    return true;
  }
  if (request.method === "GET" && ["/api/weather/wpc-ero", "/api/public/wpc-ero"].includes(requestUrl.pathname)) {
    const day = Math.max(1, Math.min(5, Number(requestUrl.searchParams.get("day")) || 1));
    try {
      let cached = wpcEroCache.get(day);
      if (!cached || cached.expires <= Date.now()) {
        const query = new URLSearchParams({
          where: "1=1", outFields: "product,valid_time,outlook,issue_time,start_time,end_time,dn,snippet",
          outSR: "4326", returnGeometry: "true", geometryPrecision: "3",
          maxAllowableOffset: "0.01", f: "geojson"
        });
        const pending = fetchJson(`https://mapservices.weather.noaa.gov/vector/rest/services/hazards/wpc_precip_hazards/MapServer/${day - 1}/query?${query}`);
        cached = { expires: Date.now() + 5 * 60_000, pending };
        wpcEroCache.set(day, cached);
        pending.then((payload) => { cached.payload = payload; delete cached.pending; }).catch(() => wpcEroCache.delete(day));
      }
      sendJson(response, 200, cached.payload || await cached.pending);
    } catch (error) {
      sendJson(response, 502, { error: "WPC ERO unavailable", detail: error.message });
    }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/weather/satellite-loop-catalog") {
    sendJson(response, 200, {
      products: satLoopProductIds().map((id) => ({
        id,
        label: SAT_LOOP_CATALOG[id].label,
        group: SAT_LOOP_CATALOG[id].group,
        tileScheme: SAT_LOOP_CATALOG[id].tileScheme,
        realEarth: SAT_LOOP_CATALOG[id].realEarth || null
      }))
    });
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/satellite/m2-ir-frames") {
    try {
      const payload = await fetchJson("https://level2.nexrad.info/v1/satellite/goes/meso/goes-19-m2/infrared/frames");
      response.setHeader("Cache-Control", "public, max-age=15, stale-while-revalidate=60");
      sendJson(response, 200, payload);
    } catch (error) {
      sendJson(response, 502, { error: "GOES-19 M2 frame list unavailable", detail: error.message });
    }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/satellite/storm-ir-frames") {
    const view = requestUrl.searchParams.get("satellite") === "west" ? "goes-18" : "goes-19";
    try {
      const payload = await fetchJson(`https://level2.nexrad.info/v1/satellite/goes/full-disk/${view}/frames`);
      response.setHeader("Cache-Control", "public, max-age=30, stale-while-revalidate=90");
      sendJson(response, 200, payload);
    } catch (error) {
      sendJson(response, 502, { error: `${view.toUpperCase()} full-disk frame list unavailable`, detail:error.message });
    }
    return true;
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/tropics/storm-satellite/frames") {
    try {
      const id = String(requestUrl.searchParams.get("id") || "").toLowerCase();
      if (!/^[a-z]{2}\d{6}$/i.test(id)) { sendJson(response, 400, { error:"Invalid tropical storm id" }); return true; }
      const product = ["infrared","clean_ir","shortwave_ir","water_vapor","upper_water_vapor","visible","geocolor"].includes(requestUrl.searchParams.get("product")) ? requestUrl.searchParams.get("product") : "infrared";
      const requestedSource = String(requestUrl.searchParams.get("source") || "best_available");
      const source = /^(?:best_available|goes-(?:18|19)-(?:m1|m2|full-disk)|composite)$/.test(requestedSource) ? requestedSource : "best_available";
      const duration = Math.max(30, Math.min(180, Number(requestUrl.searchParams.get("duration")) || 30));
      const manifest = await fetchJson(`https://internal.zasnetwx.com/api/v1/satellite/tropical/${encodeURIComponent(id)}/frames?product=${encodeURIComponent(product)}&source=${encodeURIComponent(source)}&duration=${duration}`);
      response.setHeader("Cache-Control", "public, max-age=20, stale-while-revalidate=60");
      const publicManifest = { ...manifest, frames:(manifest.frames || []).map((frame) => ({ ...frame, sourceImageUrl:frame.imageUrl, imageUrl:`/api/public/tropics/storm-satellite/source.webp?url=${encodeURIComponent(frame.imageUrl)}` })) };
      sendJson(response, 200, publicManifest);
    } catch (error) { sendJson(response, 502, { error:"Storm satellite graphics unavailable", detail:error.message }); }
    return true;
  }
  if (["GET","HEAD"].includes(request.method) && requestUrl.pathname === "/api/public/tropics/storm-satellite/source.webp") {
    try {
      const source = new URL(String(requestUrl.searchParams.get("url") || ""));
      if (source.protocol !== "https:" || source.hostname !== "internal.zasnetwx.com" || !/^\/api\/v1\/satellite\/tropical\/[a-z]{2}\d{6}\/(?:infrared|clean_ir|shortwave_ir|water_vapor|upper_water_vapor|visible|geocolor)\/(?:goes-(?:18|19)-(?:m1|m2|full-disk)|composite)\/[A-Za-z0-9_-]+\/(?:image|graphic)\.webp$/.test(source.pathname)) {
        sendJson(response, 400, { error:"Invalid tropical satellite image URL" }); return true;
      }
      return proxyHttpsGet(source.toString(), response, { cacheControl:"public, max-age=31536000, immutable", contentType:"image/webp" });
    } catch (error) { sendJson(response, 400, { error:"Invalid tropical satellite image URL", detail:error.message }); }
    return true;
  }
  if (["GET","HEAD"].includes(request.method) && requestUrl.pathname === "/api/public/tropics/storm-satellite/frame.webp") {
    try {
      const id = String(requestUrl.searchParams.get("id") || "").toLowerCase(), frameId = String(requestUrl.searchParams.get("frame") || "");
      if (!/^[a-z]{2}\d{6}$/i.test(id) || !/^[A-Za-z0-9_-]{8,50}$/.test(frameId)) { sendJson(response, 400, { error:"Invalid storm satellite frame" }); return true; }
      const cacheKey = `${id}:${frameId}:v1`, cached = stormSatelliteGraphicCache.get(cacheKey);
      let imageBuffer = cached?.buffer;
      if (!imageBuffer) {
        const current = await fetchJson("https://www.nhc.noaa.gov/CurrentStorms.json"), storm = (current.activeStorms || []).find((item) => String(item.id).toLowerCase() === id);
        if (!storm) { sendJson(response, 404, { error:"Active NHC storm not found" }); return true; }
        const satellite = Number(storm.longitudeNumeric) < -105 ? "west" : "east", view = satellite === "west" ? "goes-18" : "goes-19";
        const manifest = await fetchJson(`https://level2.nexrad.info/v1/satellite/goes/full-disk/${view}/frames`), frame = (manifest.frames || []).find((item) => String(item.id) === frameId && item.ready && item.imageUrl);
        if (!frame) { sendJson(response, 404, { error:"Satellite frame not found" }); return true; }
        const parsedSource = new URL(frame.imageUrl);
        if (parsedSource.protocol !== "https:" || parsedSource.hostname !== "level2.nexrad.info" || !parsedSource.pathname.endsWith("/image.webp")) throw new Error("Unexpected satellite image source");
        imageBuffer = await renderStormSatelliteGraphic({ sourceUrl:frame.imageUrl, frame, storm, satellite });
        stormSatelliteGraphicCache.set(cacheKey, { buffer:imageBuffer, at:Date.now() });
        while (stormSatelliteGraphicCache.size > 80) stormSatelliteGraphicCache.delete(stormSatelliteGraphicCache.keys().next().value);
      }
      response.writeHead(200, { "Content-Type":"image/webp", "Content-Length":imageBuffer.length, "Cache-Control":"public, max-age=31536000, immutable", ETag:`"${crypto.createHash("sha1").update(imageBuffer).digest("hex")}"` });
      if (request.method === "HEAD") response.end(); else response.end(imageBuffer);
    } catch (error) { sendJson(response, 502, { error:"Storm satellite WebP unavailable", detail:error.message }); }
    return true;
  }

  // Single full-frame PNG for Ops sat loop (avoids tile "blocks" on the map).
  if (request.method === "GET" && requestUrl.pathname === "/api/public/satellite/frame.png") {
    return handleSatelliteFrameImage(requestUrl, response);
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/weather/satellite-animated") {
    const product = normalizeNesdisSatelliteProduct(requestUrl.searchParams.get("product") || "geocolor");
    // RealEarth products use XYZ tiles (see /api/public/satellite/nesdis/…?time=).
    // NESDIS GeoColor keeps exportImage for MapLibre bbox tiles.
    if (satLoopTileScheme(product) === "xyz") {
      sendJson(response, 400, {
        error: "Use XYZ tiles for this satellite loop",
        detail: `Request /api/public/satellite/nesdis/${product}/{z}/{x}/{y}?time=<token>`
      });
      return true;
    }
    const serviceName = nesdisSatelliteArchiveService(product);
    return proxyWeatherMapImage(
      requestUrl,
      response,
      `https://satellitemaps.nesdis.noaa.gov/arcgis/rest/services/${serviceName}/ImageServer/exportImage`
    );
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/satellite/geocolor") {
    return proxyWeatherMapImage(requestUrl, response, "https://satellitemaps.nesdis.noaa.gov/arcgis/rest/services/MERGEDGC_current/ImageServer/exportImage");
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/weather/satellite-animated/frames") {
    try {
      const product = normalizeNesdisSatelliteProduct(requestUrl.searchParams.get("product") || "geocolor");
      const durationMinutes = Math.max(30, Math.min(720, Number(requestUrl.searchParams.get("durationMinutes")) || 120));
      const maxFrames = Math.max(6, Math.min(36, Number(requestUrl.searchParams.get("maxFrames")) || 24));
      const cacheKey = `${product}:${durationMinutes}:${maxFrames}`;
      const now = Date.now();
      let cached = satelliteLoopCatalogCache.get(cacheKey);
      if (!cached || now - cached.at > 30_000) {
        if (!cached?.pending) {
          const previous = cached;
          const pending = fetchNesdisSatelliteArchiveFrames(product, {
            maxDurationMs: durationMinutes * 60_000,
            maxFrames
          }).then((result) => {
            satelliteLoopCatalogCache.set(cacheKey, { at: Date.now(), result, pending: null });
            return result;
          }).catch((error) => {
            if (previous?.result && now - previous.at < 5 * 60_000) {
              satelliteLoopCatalogCache.set(cacheKey, { ...previous, pending: null });
              return previous.result;
            }
            satelliteLoopCatalogCache.delete(cacheKey);
            throw error;
          });
          cached = { ...(cached || {}), pending };
          satelliteLoopCatalogCache.set(cacheKey, cached);
        }
      }
      const result = cached?.pending ? await cached.pending : cached.result;
      sendJson(response, 200, {
        ...result,
        product,
        durationMinutes,
        frameCount: result.frames?.length || 0
      });
    } catch (error) {
      sendJson(response, 502, { error: "Animated GOES frames unavailable", detail: error.message });
    }
    return true;
  }

  const satelliteTileMatch = requestUrl.pathname.match(
    /^\/api\/public\/satellite\/nesdis\/([A-Za-z0-9_-]+)\/(\d+)\/(\d+)\/(\d+)$/
  );
  if (request.method === "GET" && satelliteTileMatch) {
    const [, product, z, x, y] = satelliteTileMatch;
    if (!normalizeSatLoopProductId(product) && !["geocolor", "abi10", "abi13"].includes(product)) {
      sendJson(response, 404, { error: "Unknown satellite product", product });
      return true;
    }
    return proxyPublicSatelliteTile(product, z, x, y, response, requestUrl);
  }

  if (request.method === "GET" && requestUrl.pathname.startsWith("/api/public/radar/rainviewer")) {
    if (handleRainviewerPublic(requestUrl, response)) {
      return true;
    }
  }

  if (request.method === "GET" && requestUrl.pathname === "/api/public/radar/local-level3.png") {
    return handleNativeRadarImage(requestUrl, response);
  }
  if (request.method === "GET" && requestUrl.pathname === "/api/public/radar/local-level3/frames") {
    return handleNativeRadarFrames(requestUrl, response);
  }

  if (request.method === "GET" && requestUrl.pathname.startsWith("/api/public/radar/iem/")) {
    if (handleIemRadarTile(requestUrl, response)) {
      return true;
    }
  }

  // NWS api.weather.gov active alerts (proxied — requires User-Agent)
  if (request.method === "GET" && requestUrl.pathname === "/api/nws/alerts/active") {
    return handleNwsActiveAlerts(requestUrl, response);
  }

  return false;
}

/**
 * Proxy active NWS alerts (GeoJSON). Client filters to outside local CWA.
 * https://www.weather.gov/documentation/services-web-api
 *
 * Important: api.weather.gov wants a *single* comma-separated `event` value.
 * Repeated `event=A&event=B` only keeps the last type (we were only getting SPS).
 */
function handleNwsActiveAlerts(requestUrl, response) {
  // Only warning/statement products (not watches)
  const defaultEvents = [
    "Tornado Warning",
    "Severe Thunderstorm Warning",
    "Severe Weather Statement",
    "Flash Flood Warning",
    "Special Weather Statement"
  ];
  // Collect all event= query values (supports ?event=A&event=B or ?event=A,B)
  const eventParams = requestUrl.searchParams.getAll("event");
  const events =
    eventParams.length > 0
      ? eventParams
          .flatMap((e) => String(e).split(","))
          .map((e) => e.trim())
          .filter(Boolean)
      : defaultEvents;

  const params = new URLSearchParams({
    status: "actual",
    // Do not restrict message_type to "alert". Active continuations and
    // corrections are published as "update" and must replace the initial
    // product on the map (for example, an FFW continuation from KRIW).
    // Comma-separated list — required for multi-type fetch
    event: events.join(",")
  });

  const upstreamUrl = `https://api.weather.gov/alerts/active?${params.toString()}`;
  const req = https.get(
    upstreamUrl,
    {
      headers: {
        "User-Agent": "ZNCaveWeatherOps/1.0 (practice desk; local operator)",
        Accept: "application/geo+json"
      }
    },
    (upstream) => {
      const status = upstream.statusCode || 502;
      if (status >= 300 && status < 400 && upstream.headers.location) {
        upstream.resume();
        // one redirect
        https
          .get(
            upstream.headers.location,
            {
              headers: {
                "User-Agent": "ZNCaveWeatherOps/1.0 (practice desk; local operator)",
                Accept: "application/geo+json"
              }
            },
            (up2) => {
              response.writeHead(up2.statusCode || 502, {
                "Content-Type": up2.headers["content-type"] || "application/geo+json",
                "Cache-Control": "public, max-age=30",
                "Access-Control-Allow-Origin": "*"
              });
              up2.pipe(response);
            }
          )
          .on("error", (err) => sendJson(response, 502, { error: err.message }));
        return;
      }
      if (status >= 400) {
        let body = "";
        upstream.on("data", (c) => (body += c));
        upstream.on("end", () => {
          sendJson(response, status, { error: "NWS alerts upstream error", body: body.slice(0, 500) });
        });
        return;
      }
      response.writeHead(200, {
        "Content-Type": upstream.headers["content-type"] || "application/geo+json",
        "Cache-Control": "public, max-age=30",
        "Access-Control-Allow-Origin": "*"
      });
      upstream.pipe(response);
    }
  );
  req.on("error", (error) => {
    sendJson(response, 502, { error: "NWS alerts request failed", detail: error.message });
  });
  return true;
}

function resolveRequestPath(urlPath, request) {
  const cleanPath = decodeURIComponent(urlPath.split("?")[0]);
  if (cleanPath === "/data/access-audit.jsonl") {
    return null;
  }
  const requestedPath =
    cleanPath === "/"
      ? (isWfoAutomationHost(request) ? "/wfo-automation.html" : isApiSiteHost(request) ? "/api.html" : isPublicSiteHost(request) ? "/public.html" : "/index.html")
      : cleanPath === "/api" || cleanPath === "/api/"
        ? "/api.html"
      : cleanPath === "/api/openapi.json"
        ? "/openapi.json"
      : cleanPath === "/admin"
        ? "/ops-admin.html"
      : cleanPath === "/wfo" || cleanPath === "/wfo/"
        ? "/wfo-automation.html"
      : cleanPath === "/beta"
        ? "/beta.html"
      : cleanPath === "/spc-beta"
        ? "/spc-beta.html"
      : cleanPath === "/spc" || cleanPath === "/spc/"
        ? "/spc.html"
      : ["/hive", "/hive/", "/hive-beta", "/hive-beta/", "/hive-legacy", "/hive-legacy/"].includes(cleanPath)
        ? "/index.html"
      : cleanPath === "/forecast-beta"
        ? "/forecast-beta.html"
      : cleanPath === "/weather-icons"
        ? "/weather-icons.html"
      : cleanPath === "/live-map"
        ? "/live-map.html"
      : cleanPath === "/sat" || cleanPath === "/sat/"
        ? "/sat.html"
      : cleanPath === "/criteria" || cleanPath === "/criteria/"
        ? "/criteria.html"
      : cleanPath === "/severe-weather"
          ? "/severe-weather.html"
        : cleanPath === "/weather-maps"
          ? "/weather-maps.html"
        : cleanPath === "/models"
          ? "/models.html"
        : cleanPath === "/model-status"
          ? "/model-status.html"
        : cleanPath === "/model-operations"
          ? "/model-operations.html"
        : cleanPath === "/nexrad"
          ? "/nexrad.html"
        : cleanPath === "/tropics"
          ? "/tropics.html"
        : cleanPath === "/tropics/storm"
          ? "/tropics-storm.html"
        : cleanPath === "/storms"
          ? "/storms.html"
        : cleanPath;
  const filePath = path.normalize(path.join(publicDir, requestedPath));

  if (!filePath.startsWith(publicDir)) {
    return null;
  }

  return filePath;
}

const server = http.createServer(async (request, response) => {
  try {
    const requestUrl = new URL(request.url || "/", `http://${request.headers.host || "localhost"}`);
    const requestHost = String(getHeader(request, "host") || "").split(":")[0].toLowerCase();

    // api.zasnetwx.com exposes concise public-alert aliases while retaining the
    // original /api/public routes used by existing clients and the website.
    if (requestHost === "api.zasnetwx.com") {
      const originalPathname = requestUrl.pathname;
      if (requestUrl.pathname === "/alerts/active" || requestUrl.pathname.startsWith("/alerts/active/")) {
        requestUrl.pathname = `/api/public${requestUrl.pathname}`;
      } else if (/^\/alerts\/[^/]+(?:\.txt)?$/.test(requestUrl.pathname)) {
        requestUrl.pathname = `/api/public${requestUrl.pathname}`;
      } else if (requestUrl.pathname === "/openapi.json") {
        requestUrl.pathname = "/api/openapi.json";
      }
      if (requestUrl.pathname !== originalPathname) request.url = `${requestUrl.pathname}${requestUrl.search}`;
    }

    if (publicServerMode && !isPublicRuntimeRequest(request, requestUrl.pathname)) {
      response.writeHead(404, {
        "Content-Type": "text/plain; charset=utf-8",
        "Cache-Control": "no-store"
      });
      response.end("Not found");
      return;
    }

    if (
      requestHost === "ops.zasnetwx.com" &&
      ["/model-operations", "/model-operations.html"].includes(requestUrl.pathname)
    ) {
      response.writeHead(308, {
        Location: `https://zasnetwx.com/model-operations${requestUrl.search}`,
        "Cache-Control": "no-store"
      });
      response.end();
      return;
    }

    if (requestUrl.pathname === "/audit.html" && !canViewAccessAudit(getSession(request))) {
      try { recordAccessEvent(request, getSession(request), "audit-access-denied", { page: requestUrl.pathname }); } catch { /* preserve denial */ }
      response.writeHead(403, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
      response.end("Forbidden: access audit permission required");
      return;
    }
    const pageSession = getSession(request);
    if (
      (requestUrl.pathname === "/admin" || requestUrl.pathname === "/ops-admin.html") &&
      ((!pageSession.authenticated && !oidcEnabled) || (pageSession.authenticated && !canAdministerHazardTemplates(pageSession)))
    ) {
      response.writeHead(403, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
      response.end("Forbidden: hazard template administrator permission required");
      return;
    }
    if (requestUrl.pathname === "/audit.html") {
      try { recordAccessEvent(request, getSession(request), "audit-view", { page: requestUrl.pathname }); } catch { /* page remains available */ }
    }

    // OIDC ops gate: send unauthenticated browsers to login (public paths stay open)
    if (
      oidcEnabled &&
      authentikRequireAuth &&
      !isPublicUnauthenticatedPath(requestUrl.pathname, request) &&
      !requestUrl.pathname.startsWith("/auth/") &&
      !requestUrl.pathname.startsWith("/api/session") &&
      !getSession(request).authenticated
    ) {
      // HTML navigations → login; API → 401 via handleApi
      const accept = getHeader(request, "accept") || "";
      if (requestUrl.pathname.startsWith("/api/")) {
        // fall through to handleApi
      } else if (accept.includes("text/html") || requestUrl.pathname === "/" || requestUrl.pathname.endsWith(".html")) {
        const returnTo = requestUrl.pathname + requestUrl.search;
        response.writeHead(302, {
          Location: `/auth/login?returnTo=${encodeURIComponent(returnTo || "/")}`,
          "Cache-Control": "no-store"
        });
        response.end("Redirecting to login…");
        return;
      }
    }

    if (["GET", "HEAD"].includes(request.method) && ["/downloads/hive-beta/linux", "/downloads/hive-native/linux", "/downloads/hive-maplibre-preview/linux"].includes(requestUrl.pathname)) {
      const session = getSession(request);
      if (!session.authenticated || !canAdministerHazardTemplates(session)) {
        response.writeHead(403, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
        response.end("Forbidden: operations administrator permission required");
        return;
      }

      const nativeDownload = requestUrl.pathname === "/downloads/hive-native/linux";
      const mapLibrePreview = requestUrl.pathname === "/downloads/hive-maplibre-preview/linux";
      // Hive Beta Desktop = Electron shell over real /hive-beta (100% UI match).
      // Native MapLibre tarball is experimental and does not match the web UI.
      const installerName = mapLibrePreview || nativeDownload
        ? "ZASNet-Hive-Native-Beta-0.8.0-linux-x86_64.tar.gz"
        : "ZASNet-Hive-Beta-1.0.0-linux-x86_64.AppImage";
      const electronCandidates = [
        path.join(__dirname, "dist-desktop", installerName),
        path.join(__dirname, "dist-desktop", "ZASNet Hive Beta-1.0.0.AppImage"),
        path.join(__dirname, "dist-desktop", "ZASNet Hive Beta-0.1.0.AppImage"),
      ];
      const installerPath = mapLibrePreview || nativeDownload
        ? path.join(__dirname, "dist-native", installerName)
        : (electronCandidates.find((p) => {
            try { return fs.statSync(p).isFile(); } catch { return false; }
          }) || electronCandidates[0]);
      let stats;
      try {
        stats = fs.statSync(installerPath);
      } catch {
        response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
        response.end("Hive Desktop Beta installer is not available");
        return;
      }

      const range = String(getHeader(request, "range") || "").match(/^bytes=(\d*)-(\d*)$/);
      let start = 0;
      let end = stats.size - 1;
      if (range) {
        start = range[1] ? Number(range[1]) : 0;
        end = range[2] ? Number(range[2]) : end;
        if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start < 0 || end < start || start >= stats.size) {
          response.writeHead(416, { "Content-Range": `bytes */${stats.size}`, "Cache-Control": "no-store" });
          response.end();
          return;
        }
        end = Math.min(end, stats.size - 1);
      }

      const headers = {
        "Content-Type": "application/octet-stream",
        "Content-Disposition": `attachment; filename="${installerName}"`,
        "Content-Length": end - start + 1,
        "Accept-Ranges": "bytes",
        "Cache-Control": "private, no-store",
        ...(range ? { "Content-Range": `bytes ${start}-${end}/${stats.size}` } : {})
      };
      response.writeHead(range ? 206 : 200, headers);
      if (request.method === "HEAD") {
        response.end();
        return;
      }
      const installer = fs.createReadStream(installerPath, { start, end });
      installer.on("error", () => response.destroy());
      installer.pipe(response);
      return;
    }

    if (await handleApi(request, response)) {
      return;
    }

    if (request.method === "GET" && requestUrl.pathname === "/ops-guidance.html") {
      response.writeHead(302, {
        Location: "https://zasnetwx.com/operations-guide",
        "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
        Pragma: "no-cache"
      });
      response.end();
      return;
    }

    // Use an application route so stale static/proxy responses cannot replace
    // the expanded manual with the former short guide.
    if (request.method === "GET" && (requestUrl.pathname === "/manual/live" || requestUrl.pathname === "/operations-guide")) {
      const manualPath = path.join(__dirname, "ops-guidance.html");
      try {
        const manual = fs.readFileSync(manualPath);
        response.writeHead(200, {
          "Content-Type": "text/html; charset=utf-8",
          "Content-Length": manual.length,
          "Cache-Control": "no-store, no-cache, must-revalidate, proxy-revalidate, max-age=0, s-maxage=0",
          Pragma: "no-cache",
          Expires: "0",
          "Surrogate-Control": "no-store",
          "X-Ops-Manual": "expanded-20260806-live"
        });
        response.end(manual);
      } catch (error) {
        console.error("[manual] Could not serve operations manual", error);
        response.writeHead(500, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
        response.end("Operations manual unavailable");
      }
      return;
    }

    const filePath = requestUrl.pathname === "/operations-manual-20260806.html"
      ? path.join(__dirname, "ops-guidance.html")
      : resolveRequestPath(request.url || "/", request);

    if (!filePath) {
      response.writeHead(403);
      response.end("Forbidden");
      return;
    }

    fs.stat(filePath, (statError, stats) => {
      if (statError || !stats.isFile()) {
        response.writeHead(statError && statError.code === "ENOENT" ? 404 : 500);
        response.end(statError && statError.code === "ENOENT" ? "Not found" : "Server error");
        return;
      }

      const extension = path.extname(filePath);
      // Ops UI assets must not be cached hard — dual/quad/MESH fixes ship as JS/CSS.
      const noCacheExt = new Set([".html", ".js", ".css"]);
      const headers = {
        "Content-Type": contentTypes[extension] || "application/octet-stream",
        "Content-Length": stats.size,
        "Accept-Ranges": "bytes"
      };
      // The public image proxy may optimize the wide header logo. Sending a
      // fixed origin length caused it to retain the original byte count while
      // returning the smaller transformed PNG, which browsers reject as a
      // truncated response. Stream this one asset with chunked framing and
      // require revalidation so the proxy computes its own representation.
      if (noCacheExt.has(extension)) {
        headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0";
        headers.Pragma = "no-cache";
      } else if (extension === ".geojson") {
        // Boundary / place layers are large; let the browser keep them.
        headers["Cache-Control"] = "public, max-age=86400";
      } else if (extension === ".png" || extension === ".bin" || extension === ".json") {
        headers["Cache-Control"] = "public, max-age=120";
      } else {
        headers["Cache-Control"] = "public, max-age=300";
      }
      if (path.basename(filePath).toLowerCase() === "znwsnew.png") {
        delete headers["Content-Length"];
        headers["Cache-Control"] = "no-cache, must-revalidate";
      }
      response.writeHead(200, headers);
      // Stream large geojson (cities ~38MB) — never buffer whole file in memory.
      const stream = fs.createReadStream(filePath);
      stream.on("error", () => {
        if (!response.headersSent) {
          response.writeHead(500);
        }
        response.end("Server error");
      });
      stream.pipe(response);
    });
  } catch (error) {
    console.error("[http] unhandled", error);
    if (!response.headersSent) {
      response.writeHead(500, { "Content-Type": "text/plain; charset=utf-8" });
      response.end("Internal server error");
    }
  }
});

server.on("upgrade", (request, socket, head) => {
  if (publicServerMode) {
    socket.end("HTTP/1.1 404 Not Found\r\nConnection: close\r\n\r\n");
    return;
  }
  let requestUrl;
  try {
    requestUrl = new URL(request.url || "/", `http://${request.headers.host || "localhost"}`);
  } catch {
    socket.end("HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n");
    return;
  }
  if (requestUrl.pathname !== "/ncep" && !requestUrl.pathname.startsWith("/ncep/")) {
    socket.end("HTTP/1.1 404 Not Found\r\nConnection: close\r\n\r\n");
    return;
  }
  if (authentikRequireAuth && oidcEnabled && !getSession(request).authenticated) {
    socket.end("HTTP/1.1 401 Unauthorized\r\nConnection: close\r\n\r\n");
    return;
  }
  const transport = ncepUpstream.protocol === "https:" ? https : http;
  const upstream = transport.request({
    protocol: ncepUpstream.protocol,
    hostname: ncepUpstream.hostname,
    port: ncepUpstream.port || (ncepUpstream.protocol === "https:" ? 443 : 80),
    method: request.method,
    path: ncepUpstreamPath(requestUrl),
    headers: ncepProxyHeaders(request, { websocket: true })
  });
  upstream.on("upgrade", (upstreamResponse, upstreamSocket, upstreamHead) => {
    const status = upstreamResponse.statusCode || 101;
    const message = upstreamResponse.statusMessage || "Switching Protocols";
    const headers = Object.entries(upstreamResponse.headers)
      .filter(([, value]) => value !== undefined)
      .map(([name, value]) => `${name}: ${Array.isArray(value) ? value.join(", ") : value}`)
      .join("\r\n");
    socket.write(`HTTP/1.1 ${status} ${message}\r\n${headers}\r\n\r\n`);
    if (upstreamHead.length) socket.write(upstreamHead);
    if (head.length) upstreamSocket.write(head);
    upstreamSocket.pipe(socket);
    socket.pipe(upstreamSocket);
  });
  upstream.setTimeout(30_000, () => upstream.destroy(new Error("NCEP WebSocket upstream timed out")));
  upstream.on("error", (error) => {
    console.warn("[ncep-proxy] WebSocket failed", error.message);
    if (!socket.destroyed) socket.end("HTTP/1.1 502 Bad Gateway\r\nConnection: close\r\n\r\n");
  });
  upstream.end();
});

async function startWfoAutomationWorker() {
  console.log(`[wfo-worker] started as PID ${process.pid}`);
  process.on("disconnect", () => process.exit(0));
  try {
    const bulkFile = path.join(dataDir, "wfo-ndfd-bulk.json");
    const stat = fs.statSync(bulkFile);
    if (Date.now() - stat.mtimeMs <= 2 * 60 * 60_000) {
      const body = JSON.parse(fs.readFileSync(bulkFile, "utf8"));
      const requiredFields=[...Object.keys(wfoNdfdBulkFields),...Object.keys(wfoHeatRiskBulkFields)];
      if(Number(body.samplingVersion)!==5)throw new Error("Bulk guidance requires every-intersecting-grid-cell zone extrema sampling");
      if(!requiredFields.every((field)=>(body.fields||[]).includes(field)))throw new Error("Bulk guidance is missing required fields");
      loadWfoNdfdBulkZoneIndex(body);
      wfoNdfdBulkStatus = { running:false, stage:"ready", startedAt:null, completedAt:new Date(stat.mtimeMs).toISOString(), fields:body.fields||[], zoneCount:body.zoneCount||0, error:null };
      console.log(`[wfo-worker] loaded fresh bulk guidance for ${wfoNdfdBulkStatus.zoneCount} zones`);
    } else {
      await refreshWfoNdfdBulkGuidance();
    }
  } catch {
    await refreshWfoNdfdBulkGuidance();
  }
  await runNationalWfoMonitor();
  setInterval(runNationalWfoMonitor, 5 * 60_000);
  setInterval(refreshWfoNdfdBulkGuidance, 2 * 60 * 60_000);
}

let wfoAutomationChild = null;
function startWfoAutomationChild() {
  if (wfoAutomationChild) return;
  wfoAutomationChild = fork(__filename, [], {
    env: { ...process.env, WFO_AUTOMATION_WORKER: "1" },
    stdio: ["ignore", "inherit", "inherit", "ipc"]
  });
  console.log(`[wfo-worker] launched PID ${wfoAutomationChild.pid}`);
  wfoAutomationChild.on("exit", (code, signal) => {
    console.warn(`[wfo-worker] exited code=${code ?? "none"} signal=${signal || "none"}`);
    wfoAutomationChild = null;
    setTimeout(startWfoAutomationChild, 10_000);
  });
}

let modelPrewarmChild = null;
function startModelPrewarmChild() {
  if (modelPrewarmChild) return;
  modelPrewarmChild = fork(__filename, [], {
    env: { ...process.env, MODEL_PREWARM_WORKER: "1" },
    stdio: ["ignore", "inherit", "inherit", "ipc"]
  });
  console.log(`[model-prewarm] launched PID ${modelPrewarmChild.pid}`);
  modelPrewarmChild.on("exit", (code, signal) => {
    console.warn(`[model-prewarm] exited code=${code ?? "none"} signal=${signal || "none"}`);
    modelPrewarmChild = null;
    setTimeout(startModelPrewarmChild, 30_000);
  });
}

if (process.env.WFO_AUTOMATION_WORKER === "1") {
  startWfoAutomationWorker().catch((error) => {
    console.error("[wfo-worker] fatal:", error.stack || error.message);
    process.exitCode = 1;
  });
} else if (process.env.MODEL_PREWARM_WORKER === "1") {
  startModelPrewarmWorker().catch((error) => {
    console.error("[model-prewarm] fatal:", error.stack || error.message);
    process.exitCode = 1;
  });
} else server.listen(port, host, () => {
  console.log(`ZNCave Weather ${publicServerMode ? "Public" : "Operations"} running at http://${host}:${port}`);
  console.log(
    oidcEnabled
      ? `[SSO] Webpage login: /auth/login → ${authentikOidcIssuer}`
      : "[SSO] Webpage login OFF — export AUTHENTIK_CLIENT_ID and AUTHENTIK_CLIENT_SECRET"
  );
  console.log(`[warnings-server] GRLevel Warning Settings URL: http://${host}:${port}/warnings/`);
  if (!publicServerMode) {
    try {
      const repaired=reconcileGfePublicLifecycle();
      if(repaired)console.log(`[gfe] reconciled ${repaired} public product lifecycle record(s)`);
    } catch (error) {
      console.warn("[gfe] startup public lifecycle reconciliation failed", error.message);
    }
    // Seed COD-style files from any existing public alerts
    try {
      rebuildCodStyleWarningsServer(loadPublicAlerts());
    } catch (error) {
      console.warn("[warnings-server] initial rebuild failed", error && error.message ? error.message : error);
    }
  }
  // GOES cache cleanup walks a large raster tree synchronously. Run it from a
  // maintenance worker, not from the HTTP server's startup callback.
  // Do not synchronously scan the potentially multi-gigabyte generated-map
  // directory in the request-serving process during startup.
  publicMapCacheCleanupAt = Date.now();
  // Outlooks are generated on demand. Running the nationwide/region prewarm
  // inside this process can monopolize the Node event loop and make the
  // website appear offline while dozens of large SVGs are assembled.
  if (!publicServerMode) {
    setTimeout(prewarmPublicHrrrDailyGuidance, 30_000);
    setInterval(prewarmPublicHrrrDailyGuidance, 6 * 60 * 60_000);
    setTimeout(startModelPrewarmChild, 45_000);
  }
  // Warm NOAA AWS satellite plates newest-first so Hive Beta opens like radar:
  // the latest frame paints immediately and animation frames are already local.
  if (!publicServerMode) setTimeout(() => {
    void prewarmGoesSatelliteLoops();
    setInterval(() => void prewarmGoesSatelliteLoops(), 5 * 60_000);
  }, 90_000);
  // Local alert maps are also rendered on demand. Their detailed county/CWA
  // geometry must not be parsed and projected on the request-serving thread
  // during startup.
  if (!publicServerMode) setTimeout(() => {
    prefetchPrimaryRadars();
    setInterval(prefetchPrimaryRadars, radarPrefetchIntervalMs);
  }, radarPrefetchStartDelayMs);
  // Tracked NCEP downloads must run in a separate worker/service. The legacy
  // in-process 15-second synchronizer can perform large synchronous writes and
  // starve every HTTP request, so it is intentionally not started here.
  // National WFO guidance and issuance run in a dedicated worker/service.
  // They must never share the HTTP event loop: a nationwide zone scan can be
  // CPU intensive enough to stall the public site and map endpoints.
  if (!publicServerMode) {
    setTimeout(startWfoAutomationChild, 5_000);
    startMrmsBackgroundRefresh();
  }
});
